insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kafka producer tuning: batching, linger, compression, delivery — как поднять throughput?', 'Producer-буфер: accumulator собирает записи в батчи по partition; linger.ms (0 дефолт — сразу; 5-20мс аггрегирует мелкие записи в батч — латентность чуть вверх, throughput сильно вверх), batch.size (макс батча, 16KB дефолт — увеличить до 64-256KB для жирных потоков), buffer.memory + max.block.ms (переполнение буфера — блокировка/исключение продюсера — обратное давление). Compression: lz4 (быстрый), zstd (лучший ratio, чуть CPU), gzip (медленный, legacy), none; сжимается батч целиком — чем больше батч, тем лучше сжатие; тип единый producer→broker→consumer (broker не распаковывает). Подтверждения: acks=all + enable.idempotence=true (дефолт 3.x) — retries без дублей, max.in.flight.requests.per.connection ≤5 сохраняет порядок при ретраях; delivery.timeout.ms (время на все ретраи — 120с дефолт), request.timeout.ms на один запрос. Ключи: null — sticky-партиции (round-robin батчами), ключ → муравьиная партиция (порядок только внутри партиции — смена ключа меняет партицию). Кастомный partitioner: по гео/tenant. Ошибки: RecordTooLargeException — max.request.size + broker message.max.bytes; InvalidReplicationFactor на автосоздании — создавать топики явно с RF=3. Мониторинг: record-error-rate, record-send-rate, batch-size-avg, compression-rate-avg (JMX).', 'Что делает linger.ms и какую цену платим латентностью? Почему сжатие эффективнее на больших батчах? Как idempotence сохраняет порядок при ретраях?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kafka lag и мёртвые консьюмеры: мониторинг, replay, offset-менеджмент?', 'Lag = log-end-offset − committed offset партиции — ключевая метрика здоровья консьюмера: растёт — не успеваем; скачком — завис/рестарт; у Burrow/kafka-exporter алерты по темпу (lag растёт быстрее скорости обработки → финишный сбой). Причины растущего lag: медленная обработка (профилировать), мало партиций (параллелизм потолок = число партиций в группе), rebalance-шторм (метрики join/sync time), внешний шейдинг (БД не тянет — bulk-оптимизация). Replay: сброс offset группы на earliest/таймстамп (kafka-consumer-groups --reset-offsets --to-datetime ...) — только при остановленной группе; альтернатива — новая группа с fresh-подпиской + фильтр по нужному окну; для точечного репроцессинга — отдельный инструмент/топик. Offset-коммит: после обработки (at-least-once + идемпотентный consumer), ручной commitSync после записи результата в БД (или транзакционно с исходом — exact-смещения в той же транзакции БД); auto-commit — риск потери при падении между poll и commit (at-most-once window). Mёртвая буква: topic DLT с причинами (serialization errors, poison pill — запись, валидно ломающая парсер: изолировать в DLT, группа живёт), retry-топики с backoff (spring-kafka @RetryableTopic).', 'Почему lag — главная метрика консьюмера и какие два сценария её роста? Как безопасно сделать replay и почему только на остановленной группе? Что такое poison pill и как DLT спасает группу?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'PostgreSQL: типы данных — jsonb, enum, массивы — где уместны и где вред?', 'jsonb: бинарный JSON — индексируем (GIN), операторы ->> (текст), @> (содержит), выборка полей; уместен: полуструктурированные атрибуты (переменный набор полей), аудит-снимки, интеграция с внешними API; вред: «сущность в jsonb» — нет FK, нет NOT NULL на полях, слабее статистика планировщика, миграции схемы невидимы — реляционная таблица всегда лучше, когда структура известна. Enum: читаемость, компактность, строгий тип; недостатки: изменение порядка/добавление значения — ALTER TYPE (транзакционно с PG 12 для добавления), невозможно удалить значение; альтернатива — lookup-таблица + FK (гибкость) или CHECK-констрейнт на text. Массивы: int[], text[] — GIN-индекс, ANY/CONTAINS; уместны: теги, автороли — компактнее join-таблицы для read-heavy; вред: нормализация Many-to-Many в массиве теряет ссылочную целостность. UUID: v4 хаотичен в B-tree (страница-сплит, локальность кэша) — v7/ulid монотонные лучше. timestamptz всегда против timestamp (без зоны — только локальные «стенные» события). numeric против bigint для денег (точность против скорости). Правильный тип = бесплатная целостность: домен-констрейнты, CHECK, FK.', 'Когда jsonb лучше отдельной таблицы и когда вредит оптимизатору? Чем lookup-таблица гибнее enum-типа PG? Почему UUIDv4 вреден индексам и что лучше?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'PostgreSQL: блокировки, deadlock, advisory locks — разбор сценариев?', 'Уровни блокировок строк: FOR KEY SHARE → SHARE → NO KEY UPDATE → UPDATE → FOR UPDATE (усиливаются); UPDATE строки берёт ROW EXCLUSIVE на строку + блокирует версии: конфликтующие UPDATE одной строки — второй ждёт первого. Deadlock классика: две транзакции апдейтят строки A→B и B→A в разном порядке — PG детектит (deadlock_timeout 1с) и убивает одну (в логе «deadlock detected») — фикс: единый порядок сортировки id перед апдейтами. Табличные локи: AccessExclusive (ALTER/DROP/TRUNCATE) против всего — длинная транзакция с SELECT держит AccessShare и блокирует ALTER (autovacuum не может почистить). Lock queue: запрос с более сильным локом становится в очередь и блокирует всех последующих слабых (даже совместимых с текущим) — «ледяной занавес» после ALTER в очереди. pg_locks/pg_stat_activity: кто кого (blocking_pid, wait_event), pg_blocking_pids(pid). Advisory locks: pg_advisory_xact_lock(key) — приложение-уровень взаимное исключение (shedlock-задачи, миграции) на одной БД без таблиц; session vs xact variants. Оптимистичная альтернатива: @Version в приложении — без ожидания, retry при конфликте. Практика: короткие транзакции, порядок доступа единый, SET lock_timeout (не висеть вечно), мониторинг longest-transaction.', 'Какой порядок UPDATE порождает дедлок и как сортировка его лечит? Почему ALTER в очереди блокирует даже SELECT-ы после него? Чем advisory lock удобен таблицы-флага для задач?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Мониторинг приложения: Micrometer, custom metrics, health checks — что мерить в своём сервисе?', 'Micrometer — фасад метрик (Spring Boot Actuator из коробки): MeterRegistry → Prometheus/Datadog. Что мерить обязательно (RED): счётчик запросов по endpoint+status (http.server.requests — авто), таймер длительностей (гистограмма для квантилей: percentiles/histogram=true, serviceLevelObjectives), ошибки — из тех же тегов. Бизнес-метрики: регистрация, платежи, очередь задач (gauge размера). Инфраструктура: пулы (HikariCP: активные/ожидание — авто), Kafka consumer lag, кэш hit-ratio. Кастом: Counter.builder("orders.created").tag("tenant", t), Timer, Gauge (ссылку на объект-число), DistributionSummary для размеров; именование: точка-разделители, единицы в имени (latency не время!), теги без высокой кардинальности (endpoint да, userId нет). Health checks: actuator health groups (liveness/readiness для k8s — readiness отражает готовность принимать трафик, liveness — что не зациклился), custom HealthIndicator (проверка внешних зависимостей критичных с optional down). Экспозиция: /actuator/prometheus (management.endpoints.web.exposure), security на эндпоинты. Правило наблюдаемости: каждую неочевидную проблему прод-инцидента закрывать новой метрикой/алертом — иначе повторится незамеченной.', 'Какие три метрики составляют RED и как их получить из http.server.requests? Чем опасна высокая кардинальность тегов и что вместо неё? В чём разница readiness и liveness probe по смыслу?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Grafana-дашборд и алерты на сервис: что положить на главный экран?', 'Уровни дашборда: (1) сервис-уровень (главный): RPS + error rate (5xx%) + p50/p95/p99 латентности (гистограмма), одновременные пользователи, статус подов/инстансов; (2) зависимости: DB-пул (wait/active), внешние вызовы (rate/latency/errors по клиенту), Kafka lag; (3) JVM (если проблема): heap usage/live-set после GC, GC-паузы, потоки; (4) бизнес: ключевые события. Принципы: золотые сигналы сверху, drill-down через ссылки-переменные (datasource-переменные: сервис, env, pod); единицы и min-decimal всегда; пороги цветом только по делу; тайм-рендер по зоне зрителя. Алерты: multi-window burn (error-rate: 2% бюджета за час → page; за 6ч → ticket), латентность p99>SLO c for:10m; абсолюты для инфраструктуры: пул-исчерпание, restart-шторм, disk>85%; каждый алерт: runbook-ссылка (аннотация), приоритет (page vs ticket), уникальный смысл (не два алерта про одно). Антипаттерны: дашборд-«свалка» из 30 панелей без иерархии, алерты на всё (усталость → игнор), средние латентности, graphs без юнитов. Содержание alert-текста: что сломалось, где смотреть, ожидаемое действие — человек в 3 утра скажет спасибо.', 'Что такое золотые сигналы и почему они на верхней панели? Чем page отличается от ticket-алерта и что в него писать? Почему средняя латентность на дашборде — антипаттерн?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Jenkins: declarative pipeline, parallel, shared library — структура без копипасты?', 'Declarative pipeline: Jenkinsfile в репо — pipeline { agent (docker-образ для сборки); stages → stage → steps; post (always/success/failure — слак, архив артефактов); options (timestamps, retry, timeout — обязательно на stage); environment (credentials() для секретов — не в env-переменных открытых) }. Параллель: stage("tests") { parallel { unit...; integration... } } — матрица axis для JDK/модулей; failFast=true отменяет остальные. Кэши: gradle-кэш в volume/persistent, docker layer caching (buildkit cache-from). Shared library: _vars/*.groovy (custom steps: mvnBuild(), deployTo(env)) + src/ (классы) — версия в отдельном репо, @Library("lib@v3") — переиспользование между командами без копипасты Jenkinsfile; осторожно с магией (неявные шаги читаются плохо — явные сигнатуры). Артефакты: один build → один образ/джарник, archiveArtifacts/junit-отчёты (test-визуализация), fingerprint трейсит зависимости. Credentials: Jenkins credentials store (secret text/file), vault-плагин; логи маскируют значения. Гейты: input-шаг для прод-approval, milestone для упорядочивания. PR-билды: multibranch pipeline — ветка = джоба автоматически, история изолирована.', 'Чем declarative pipeline отличается от scripted и почему выбрали первый? Зачем shared library и где её граница разумного использования? Как правильно хранить секреты в Jenkins?' from categories where slug = 'ci-cd';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Feature flags: типы, реализация, техдолг — выпускать без риска?', 'Типы флагов: release (включалка новой версии кода — живёт дни), experiment (A/B — статистика, hasta победы), ops/toggle (kill-switch: выключить фичу без деплоя — деградация под нагрузкой), permission (доступ по сегменту юзера — долгоживущий). Реализация: простые — конфигурация (env/yaml) + @ConditionalOnProperty / Spring @Value; динамические — сервис флагов (получение по ключу+контексту юзера, кэш, refresh): открытое Unleash/Flagsmith, SaaS LaunchDarkly; паттерны кода: if (flags.isEnabled("new-checkout", userCtx)) — инъекция FlagService, изоляция веток (стратегии вместо глубокой вложенности),注射 старой ветки удаляется после 100% раскатки. Риски: техдолг мёртвых флагов (код живёт годами «на всякий» — аудит перед релизом: флаги >2 спринтов → удалить), комбинаторный взрыв (несколько флагов пересекаются — тестирование матрицы), кэш-инвалидация (флаг переключён — через сколько виден: push vs poll), латентность проверки (локальный кэш vs сетевой вызов на каждый запрос). Практики: именование с датой (checkout-v2-2026-04), owner флага, алерт «флаг живёт >N дней», флаги не для бизнес-логики конфигурации (это настройки), тесты обеих веток до раскатки.', 'Чем release-флаг отличается от ops-тоггла по времени жизни? Почему мёртвые флаги — техдолг и как с ним бороться? Что опасного в пересечении нескольких флагов?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Логирование: уровни, структурирование, корреляция — как делать логи полезными?', 'Уровни: ERROR (сбой, требующий действия), WARN (аномалия, авто-восстановилось: retry удался, очередь растёт), INFO (жизненный цикл: старт, конфигурация, ключевые бизнес-события — «заказ оплачен»), DEBUG (детали для диагностики), TRACE (очень мелко); прод-уровень INFO, DEBUG включать точечно по логгеру (logger configuration change без рестарта). Структурированные логи: JSON-вывод (logstash-logback-encoder) — поля вместо prose: timestamp, level, logger, message, trace_id, user_id, duration_ms, error.stacktrace; парсимые агрегатором (Loki/ELK) — фильтрация по полям вместо grep-фольклора. Корреляция: MDC (trace_id в ThreadLocal → appender добавляет в каждое сообщение) — с виртуальными потоками/reactive — context-propagation; запрос → trace_id генерится на входе (фильтр) → передаётся через HTTP-header/Kafka-header всем участникам. Антипаттерны: лог-спам в цикле (100k строк/мин — стоимость I/O), пароли/токены/PII в логах (маскирование), e.printStackTrace() (мимо логгера, без структуры), System.out.println, «логирование ради галочки» (событие без контекста: «ERROR null»), два логгера-конфликтa. Message — константа + поля-параметры (logger.info("order {} paid in {}ms", id, ms)) — не конкатенация (lazy-вычисление при выключенном уровне).', 'Чем WARN отличается от ERROR по обязанности действовать? Зачем структурированный JSON вместо текстовых логов? Как trace_id попадает в логи всех сервисов цепочки?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Пограничные ситуации в тестах: concurrency, time, randomness — детерминизм превыше всего?', 'Тест должен быть детерминирован: одинаковый вход → одинаковый результат; источник флаков — неподконтрольные зависимости. Время: inject Clock (java.time.Clock) — тест с Clock.fixed(Instant, zone) / mutable-test-clock (перематывать); НЕ LocalDateTime.now() в коде — только clock.instant(); ShedLock/scheduler — тестировать логику задачи отдельно от расписания. Randomness: inject Random/seed (new Random(42) — воспроизводимо), seed в сообщении assertion (печатать seed — воспроизвести фейл). Concurrency: тесты гонок — не гарантия, но JCStress для инвариантов; в прикладных тестах: fixed-потоки + барьер (CyclicBarrier) + awaitility на итог; concurrency-тест не должен быть в обычном прогоне — отдельная медленная категория. Внешний мир: внешние HTTP → WireMock (стаб-ответы, latencies, faults), время-зависимости → fake; БД — Testcontainers (реальный PG). Окружение: locale/timezone/parallel-execution — зафиксировать в тест-сетапе (JUnit @Execution(SAME_THREAD) при общем состоянии); System-переменные в тесте — не наследуются гонками. Флаки-политика: каждый флак — тикет с анализом (не «перезапустить и забыть»), карантин-сьют с таймером на починку; счётчик флаков — метрика качества сьюта.', 'Зачем внедрять Clock и как тестировать «через час наступит X»? Как seed делает random-тест воспроизводимым? Что делать с зафлакившим тестом по процессу, а не перезапуску?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Мутационное тестирование и coverage: что измеряет PIT и почему 100% coverage мало?', 'Line/branch coverage меряет исполнение кода, не осмысленность проверок: тест без assert даёт 100%; assertion-розы (Roulette) — тесты падают только если исключение. Мутационное тестирование (PIT): инструмент меняет код (мутации: invert boundary < на <=, удалить вызов, вернуть default) и гоняет тесты: мутация выжила → тест не ловит эту ошибку; метрика mutation score = убитые/всего; конфигурация: target classes, threads, форматы отчёта (HTML — построчные выжившие). Ценность: показывает пустые assert-ы и недотестированные ветки, приоритизирует доработку сьюта; цена: медленно (полный прогон × число мутаций) — на дифф-изменениях (incremental) в CI, полный — периодически/ночью. Практика: не гнаться за 100% мутационного — порог 70-80% на бизнес-логике; выжившие мутации в DTO/getters — эквивалентные мутанты (не убиваются в принципе) — пометить. Coverage-политика: line coverage как дым-индикатор (внезапное падение = удалили тесты), gate на дифф (изменённый код покрыт на 80%), а не на весь проект (легаси-регресс бесплоден). JaCoCo + PIT — комплиментарны: первый «код исполнялся», второй «тесты проверяют».', 'Чем мутационный score честнее line coverage? Что означает выжившая мутация и эквивалентный мутант? Почему gate на дифф лучше gate на весь репозиторий?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Docker networking и k8s Service/Ingress: как трафик доходит до пода?', 'Docker: bridge-сеть (дефолт) — NAT через iptables, port-mapping публикует; контейнеры одной user-defined network резолвятся по имени (embedded DNS); host-network — без NAT (порт-конфликты, но скорость); none — изоляция. K8s: Pod имеет IP (эфемерный, из cluster-CIDR) — все поды взаимодостижимы (flat network, без NAT между подами — требование CNI). Service — стабильный виртуальный IP + DNS-имя (my-svc.namespace.svc.cluster.local): ClusterIP — kube-proxy (iptables/IPVS rules) балансирует на endpoints (поды, прошедшие readiness); NodePort — порт на каждом узле; LoadBalancer — внешний LB (облако) → NodePort. Endpoints/EndpointSlice обновляются контроллером при изменении подов. Ingress — L7: правила host/path → Service; Ingress-контроллер (nginx/traefik/istio-gateway) — сам под с LB/NodePort; TLS терминируется (cert-manager автосертификаты). NetworkPolicy — firewall подов (ingress/egress rules по label-селекторам; требует CNI-поддержки — calico/cilium). DNS-кейсы: headless service (clusterIP: None) — DNS отдаёт IP всех подов (StatefulSet-per-pod имена), ExternalName — CNAME. Отладка: nslookup/dig в debug-контейнере, kubectl get endpoints, connectivity из ephemeral-контейнера.', 'Чем Service отличается от прямого обращения к Pod IP и зачем он нужен? Что делает Ingress и чем L7-правила отличаются от Service? Зачем headless service и когда NetworkPolicy необходима?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', '12-factor и конфигурация окружения: dev/stage/prod — где разница между средами?', '12-factor: конфиг — в окружении (env), один артефакт через все среды, логи — поток, процессы — stateless, зависимости — явные; отходы: конфиг в образе (пароль в образе утёк навсегда), «у нас как в проде, но IP другой» — ручные правки. Среды различаются ТОЛЬКО: внешние эндпоинты (URL БД, брокера, внешних API), креды (rotating), ресурсы (лимиты, реплики), фичи-тоги (эксперименты — только stage/prod), observability (уровень логов, сэмплирование). Одинаково везде: код, схема БД (миграции идут вперёд), структура конфига (ключи одни, значения разные). Проверка «прод-like»: stage с prod-размером данных и той же топологией (иначе stage ничего не ловит); деградация окружений — приручённые данные/льготные креды → расхождение поведения. GitOps: декларативное описание среды в git (k8s-manifests/helm values per env), PR на изменение среды — ревью и история; секреты — внешне (vault/sealed), не в git открыто. Anti: отдельная long-lived ветка «для прода» (дифф копится — релиз боль), конфиги в Wiki (устаревают), сборка артефакта заново на деплое (не воспроизводимо).', 'Какие три вещи обязаны совпадать между средами и что законно различается? Почему stage с игрушечными данными ничего не ловит? Чем GitOps-подход дисциплинирует изменения окружения?' from categories where slug = 'ci-cd';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Comparable vs Comparator: контракт, сортировки, binarySearch — тонкости?', 'Comparable (compareTo) — естественный порядок, реализуется самим классом; Comparator — внешний, переопределяемый, композиция: Comparator.comparing(User::getName).thenComparing(User::getAge, reverseOrder()); comparingInt для примитивов (без бокса). Контракт compareTo: анти-симметрия (sgn(a.compareTo(b)) = -sgn(b.compareTo(a))), транзитивность, с NullPointerException при null (не как equals) — nullsFirst/nullsLast обёртки. Согласованность с equals: TreeMap/TreeSet используют compareTo для «равенства» — если compareTo говорит 0, а equals false — TreeMap теряет элементы (классический баг BigDecimal: 1.0 и 1.00 equals false, compareTo 0 — TreeSet держит один). Arrays.sort объектов — TimSort (стабильный, O(n log n), merge-для частично-упорядоченных); примитивов — dual-pivot quicksort (не стабильно — неважно для примитивов); Collections.sort — copy-в-массив-sort-copy-back (по modCount). binarySearch требует отсортированности — иначе мусорный результат (не исключение!); несортированный массив может «найти» не тот индекс. List.sort vs stream.sorted(): первый in-place, второй новый стрим; sorted с comparator на потоке — stateful операция. Subtleties: вычитание в compareTo (a.field - b.field) — overflow на int-полях (Integer.compare безопасен); compareTo по нескольким полям — цепочка Integer.compare/asym.', 'Почему TreeMap «теряет» элемент при compareTo=0 и equals=false на примере BigDecimal? Чем TimSort для объектов отличается от quicksort для примитивов? Что вернёт binarySearch по неотсортированному массиву?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Функциональные интерфейсы: Predicate/Function/Supplier/BiFunction — зачем и что composition?', 'Четыре базовых: Predicate<T> (T→boolean — фильтры, conditions: and/or/negate — композиция предикатов), Function<T,R> (T→R — трансформации: andThen (сначала этот), compose (сначала аргумент)), Supplier<T> (()→T — ленивая поставка, фабрики, T.get в Optional), Consumer<T> (T→void — side-эффекты, forEach). BiFunction<T,U,R> — два входа; BiPredicate; BinaryOperator<T> (T,T→T — reduce-аккумулятор: min/max по accumulator); UnaryOperator<T> (T→T — replaceAll). Специализации примитивов: IntFunction, ToIntFunction, IntPredicate... — без бокса в стримах (mapToInt). Ссылки на методы: Class::staticMethod, instance::method (bound/unbound), Class::new — читаемее лямбд когда сигнатура совпадает. Лямбда vs анонимный класс: лямбда не создаёт this-связь (this = внешний), не захватывает лишнего; захватывающие лямбды (referencing локальные переменные) требуют effectively final — состояние вне — источник гонок в parallel стримах. Композиция в дизайне: strategy-цепочки (List<Predicate> → reduce andThen), валидация через stream of predicates; Function-композиция заменяет вложенные вызовы: f.andThen(g).andThen(h) — пайплайн-читаемость. Ограничение checked-исключений в лямбдах — обёртки (sneaky-throw утилиты или try-обёртка).', 'Чем andThen отличается от compose у Function и что захватывающая лямбда требует от переменных? Почему BiFunction недостаточно для reduce и что такое BinaryOperator? Какую пользу дают примитивные специализации в стримах?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'I/O модели: BIO/NIO/AIO, epoll, файловый I/O — что стоит за «неблокирующим»?', 'BIO (blocking): поток на соединение — accept/read блокируют; тысячи соединений = тысячи потоков — память+контекст-свитчи; приемлемо при малом числе клиентов или с virtual threads (блокировка VT дешёвая). NIO (неблокирующий + мультиплексирование): Channels + Selector — один поток опрашивает готовность (accept/read/write) множества каналов; под капотом Linux — epoll (уровневые события: readiness), macOS — kqueue; Selector.select() просыпается по готовым ключам — Netty построен на этом: event-loop-группа, каналы регистрируются, обработка без блокировки. AIO/async I/O (io_uring — современный Linux): завершение по callback — JVM-поддержка слабая, Netty экспериментирует; практически NIO+epoll доминирует. Файловый I/O: не эпулится (обычные файлы всегда «готовы» но блокируют) — FileChannel + transferTo (sendfile, zero-copy для статики), memory-mapped файлы (MappedByteBuffer — страница-кэш ОС, быстрый random-access). Неблокирующая цепочка клиент→сервер:连接 устанавливается неблокирующе (connect завершается по готовности), записи буферизуются. Backpressure: скорость чтения сети > обработки — очередь растёт — нужно ограничение (Netty autoRead=false, watermark). Virtual threads возвращают «BIO-стиль» коду с NIO-эффективностью — JVM паркует VT на блокирующем вызове канала.', 'Почему поток-на-соединение не масштабируется и как epoll решает это? Почему файловый I/O нельзя замультиплексировать через selector? Что даёт virtual thread для blocking-кода на NIO-каналах?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Varargs, массивы и heap pollution: @SafeVarargs, List.of — глубже в детали?', 'Varargs (T...) — синтаксис массива: компилятор создаёт Object[] при вызове; generics+varargs = потенциальный heap pollution: метод получает Object[], куда можно (через сырой тип) положить не-String — позже ClassCastException в неожиданном месте; @SafeVarargs (final/static/private методы) — контракт разработчика «не загрязняю». Правило безопасного дженерик-varargs: только читать из массива, не писать; не возвращать массив наружу; не доверять ClassCastException-кластерам. List.of(...)/Set.of(...) (Java 9+): иммутабельны, null-элементы запрещены (NPE на создание — ловит баги рано), set-семантика дедупликации, порядок не гарантирован у Set; List.copyOf — иммутабельная копия (без лишнего копирования если источник уже иммутабельный list-of). Массивы: ковариантны (Object[] = new String[{}] компилируется — runtime ArrayStoreException при записи не-String); создание дженерик-массива запрещено (new T[10]) — обход: (T[]) new Object[10] с @SuppressWarnings (ArrayList так делает) или Object[] + каст при чтении. Arrays.asList — фиксированный размер, view над массивом (изменение массива видно!). Collections.singletonX — микро-коллекции. Stream.of vs List.of: первый — поток из элементов, не коллекция.', 'Что такое heap pollution и почему varargs с дженериками его создают? Чем List.of отличается от Arrays.asList по мутабельности и null-политике? Почему массивы ковариантны и как это приводит к ArrayStoreException?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'JMH-бенчмарки: warmup, forks, режимы — как не обмануть себя измерением?', 'JMH — каркас против типичных ошибок измерения: DCE (dead-code elimination — результат вычисления не используется → JIT удаляет: использовать Blackhole.consume), constant-folding (вычисление константы на этапе компиляции — параметризовать @Param), GC-шум ( forks изолируют, -prof gc), прогрев (warmup iterations до стабильного JIT-кода). Режимы: Throughput (ops/time), AverageTime (время/операция), SampleTime (гистограмма — хвосты), All; @BenchmarkMode. Изоляция: forks=3 (новая JVM на форк — JIT-профили не смешиваются), threads — конкурентность. Параметры: @Param({"10","100","1000"}) — прогон по сетке. Результаты: сравнивать не только среднее но и error-интервалы (99% CI); α=.01 результата overlap → разницы нет — не выдумывать оптимизацию. Практика: measure don''t guess — бенчмарк после профилирования (JFR/flame показал горячее место); микробенчмарк ≠ прод-поведение (нет реального кэш-паттерна, аллокации распределены иначе) — проверять интеграционный эффект; gradle-плагин jmh — прогон в CI на коммит-диффе опасных мест. @State(Scope.Benchmark/Thread) — совместное/раздельное состояние; Setup/Level.Trial/Iteration — стоимость инициализации не в измерении.', 'Что такое DCE и как Blackhole спасает бенчмарк от JIT-удаления? Зачем forks и почему один прогон в одной JVM врёт? Как правильно интерпретировать error-интервалы результатов?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Unit-тесты: границы класса, test doubles (mock/stub/fake/spy) — когда мок уместен?', 'Test doubles: dummy (передать чтобы компилировалось), stub (заготовленные ответы на вызовы — состояние), mock (проверка взаимодействий: вызван ли, сколько раз, с чем — поведение), spy (обёртка реального с записью вызовов), fake (рабочая лёгкая реализация: in-memory репозиторий). Правила London-стиля: мокать только владеемые-границы (интерфейсы, которые сами определили) и внешние системы; мокать value-объекты и простые функции — деградация тестов (мок тестирует implementation, а не контракт — рефакторинг без изменения поведения ломает тесты). Тестируем поведение: один тест — один сценарий (given-when-then), имя отражает сценарий (should_reject_when_card_expired), asserts — осмысленные (не verifyNoInteractions на всё подряд). Границы: не мокать то, что тестируется (SUT); использовать реальные Immutable/утилиты; fake-репозиторий лучше мока-репозитория для доменных сценариев (меньше хрупкости). Mockito: when/thenReturn (stub), verify (mock-проверки), ArgumentCaptor, @InjectMocks (осторожно: скрывает зависимости); BDD-стиль given/willReturn. Проверка «тест без реализации»: удалить тело метода — если тест зелёный, он ничего не проверяет (мутационная логика руками).', 'Чем stub отличается от mock по проверяемому: состояние или поведение? Почему мокание value-объектов и собственных утилит — деградация? Как понять, что тест проверяет контракт, а не implementation?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Архитектурные тесты: ArchUnit, package dependency — как зафиксировать архитектуру?', 'ArchUnit — правила поверх байткода: noClasses().that().resideInAPackage("..service..").should().dependOnClassesThat().resideInAPackage("..controller..") — зависимость направлена вниз (controller→service→repository), нарушение = падение теста = регрессия архитектуры в PR. Классы правил: слоистость (layeredArchitecture), циклы (slicesShouldNotBeCyclic — циклические зависимости пакетов — источник спагетти), именование (классы в ..service.. должны оканчиваться на Service), аннотации (@Service только в определённых пакетах), изоляция (domain не зависит от spring — чистое ядро: FreezingArchRule фиксирует существующие нарушения, новые — падают). Ценность: архитектурные решения живут не в Wiki, а в CI — деградация ловится мгновенно; ревью освобождается от рутины «а можно ли отсюда вызывать». Настройка: правила как тесты JUnit (@AnalyzeClasses(packages)), composite-правила для слоёв; тесты в отдельном модуле собираются быстро. Границы: ArchUnit видит только зависимости классов, не динамику (runtime-связи через события — не увидит); для контрактов модулей — module-info JPMS (жёсткая инкапуляция) или Gradle modularization-плагин (api vs implementation — отсекает транзитивные зависимости). Гексагонал-фиксация: adapter-пакеты не видят друг друга, порт-интерфейсы в domain — иначе тест красный.', 'Какие три вида правил ArchUnit закрывают 90% деградации архитектуры? Что такое FreezingArchRule и зачем замораживать старые нарушения? Почему ArchUnit не видит связей через события и что ловит их?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Keycloak: realms, clients, flows — когда свой OAuth-сервер не нужен?', 'Keycloak — готовый identity-провайдер: realm (изолированная зона юзеров/клиентов), client (приложение: confidential с secret / public SPA+PKCE), roles/groups, identity brokering (вход через Google/GitHub — federation), user federation (LDAP/AD). Токены: OIDC id_token + access JWT с ролями в claim''ах (realm/client roles, mapper-ы настраиваются); refresh + вращение; logout (revocation). Интеграция Spring: resource-server (JWT валидация из JWKS — stateless), или adapter/gateway (сессия). Админ: REST admin-API, экспорт/импорт realm-JSON (конфиг в git — воспроизводимые окружения). Когда НЕ свой сервер: стандартные входы (соцсети, корпоративные LDAP), 2FA из коробки, аудит — Keycloak экономит месяцы; свой JWT-сервис оправдан: один тип входа навсегда (наш Sobes — только Telegram), экзотические требования протокола, неприемлема зависимость/память (Keycloak ~512MB+). Эксплуатация: stateless-режим (Infinispan distributed), БД своя, версия вверх миграциями; производительность входа — кэш, загрузка пользователей лениво. Security-нюансы: PKCE для public clients обязателен, redirect_uri whitelist, короткий access-token TTL (5-15 мин).', 'Что такое realm и client в Keycloak и зачем PKCE для SPA-клиента? Когда свой JWT-сервер оправдан против Keycloak? Как роли попадают в JWT-claims и как их читает resource-server?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Security-инциденты: OWASP top рисков для API — что проверять в своём сервисе?', 'Топ-риски API: BOLA/IDOR (доступ к чужому объекту по id — /users/123/orders где 123 чужой: авторизация на каждом обращении к ресурсу, не только на endpoint), broken auth (слабые токены, отсутствие expiry, JWT none-alg), excessive data exposure (отдаёте полную сущность, фронт фильтрует — «утечка в браузер»), rate-limiting отсутствие (брутфорс, scraping), mass assignment (биндинг запроса прямо в сущность — юзер присылает isAdmin: true — whitelist полей DTO), SSRF (сервер ходит по юзерскому URL — metadata-эндпоинты облака), injection (SQL — параметризация всегда; NoSQL-операторы), misconfig (CORS *, отладка в проде, дефолт-креды), vuln-зависимости (log4shell-класс: SCA-скан trivy/dependabot в CI). Проактивный чек-лист: авторизация ресурса (не только аутентификация), DTO с whitelist, валидация входа (bean validation + схема), rate-limit на auth/тяжёлых, security-заголовки (CSP, X-Content-Type), аудит логов доступа, секреты вне кода/образа, dependency-scan gate. Пентест-минимум: OWASP ZAP baseline-scan в CI против стенда. Response-гигиена: ошибки без стектрейсов наружу (ProblemDetail), 404 вместо 403 на чужие ресурсы (не раскрывать существование).', 'Что такое BOLA/IDOR и почему аутентификации недостаточно для защиты? Как mass assignment работает и что защищает — DTO или валидация? Почему 404 вместо 403 на чужом ресурсе — лучшая практика?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kafka: partitioning ключи и порядок — как гарантировать порядок обработки?', 'Порядок в Kafka гарантирован только внутри партиции: продюсер с одним ключом → одна партиция (murmur2 хеш) → брокер пишет последовательно → консьюмер группы читает партицию одним потоком = порядок сохранён end-to-end. Что ломает порядок: (1) retries без idempotence при max.in.flight>1 — переупорядочивание батчей (enable.idempotence=true решает); (2) смена ключа/партиционера — сообщения по одному entity уезжают в разные партиции (рефакторинг ключа молча ломает порядок); (3) несколько потоков обработки одной партиции (ручной executor внутри консьюмера) — завершение вразнобой; (4) репартиционирование внутри приложения (aggregate/repartition-темы в Streams). Когда порядок нужен: события состояния (создан→оплачен→отправлен — обратный порядок ломает логику), financial ledger; когда нет — независимые события, clickstream. Антипаттерн «одна партиция для порядка»: убивает параллелизм и масштабирование; правильный ключ (userId, orderId) даёт порядок per-entity + параллелизм across entities. Ручки: кастомный partitioner ( sticky по бизнес-группе), NumberOfPartitions планировать заранее (рост партиций = перераспределение ключей! порядок в переходный период ломается); compacted-топики + версионные схемы с event-id для дедупликации вне порядка.', 'Почему одна партиция на топик — антипаттерн и что даёт ключ-партиционирование? Какие три вещи молча ломают порядок сообщений одной сущности? Что происходит с порядком при увеличении числа партиций?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'PostgreSQL: connection pool (HikariCP) — настройка, утечки, pool sizing?', 'HikariCP — дефолт Spring Boot: maximumPoolSize (дефолт 10 — не факт что верно), minimumIdle (== max для фиксированного пула — рекомендуют), connectionTimeout (30с — ожидание коннекта из пула), maxLifetime (30 мин — меньше чем БД-side timeout/idle-in-transaction), keepaliveTime, leakDetectionThreshold (60с — WARN с стектрейсом взявшего коннект — ловит незакрытые). Sizing-формула: pool_size = core_count * 2 + effective_spindle_count (PostgreSQL: соединения = процессы на сервере — каждый ест память; OLTP-сервис: 10-20 соединений достаточно для сотен RPS при коротких запросах); больше пул ≠ быстрее — конкуренция за блокировки/CPU, очередь в БД. Переподключение: pool.closeConnection на SQLException (connection-level errors), validation — connectionTestQuery не нужен (JDBC4 isValid). Утечки: коннект не возвращён (забыт close в ручном коде — всегда try-with-resources; Spring @Transactional закрывает сам), долгие транзакции держат коннект (async-обработка внутри транзакции!) — leakDetection найдёт. PgBouncer (transaction-pooling) — когда коннектов к БД нужно много (serverless, сотни инстансов): пул соединений к БД меньше числа клиентов; Session-level features (PREPARE, LISTEN) ломаются — mode учитывать. Мониторинг: hikari-метрики (active/pending/usage) — алерт на pending>0 стабильно.', 'Почему большой пул замедляет систему и как оценить правильный размер? Что делает leakDetectionThreshold и как найти утечку коннекта? Зачем PgBouncer и что ломается в transaction-pooling режиме?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Event sourcing + CQRS: когда оправданы и чем дорого платим?', 'ES: события (факты домена) — источник истины, состояние — проекция (replay событий); CQRS: команды (запись) и запросы (чтение) — разные модели/хранилища. Выгода: полный аудит-журнал (пересоздать любое состояние), темпоральные запросы (state на дату), естественный integration (события наружу), независимое масштабирование чтения. Цена: (1) eventual consistency — проекция отстаёт: юзер сохранил — список ещё не обновился (UX усложнение); (2) versioning событий — schema evolution на годы (upcast-ы, слабые схемы); (3) запросы «по текущему состоянию» невозможны на событиях — нужны проекции под каждый use-case (синхронизация, rebuild); (4) сложность дебага (гонки проекций, дедупликация); (5) snapshоts для длинных агрегатов. Когда оправдано: финансовые системы (ledger — аудит), домены со сложной историей (бронирования, ставки), требование event-driven интеграций. Когда нет: обычный CRUD — ES добавляет 3-5x сложности без пользы; стартап без доменного анализа. Инфраструктура: event-store (EventStoreDB, PG-jsonb самопис, Kafka как store — спорно: compacted + ключи, но нет уникальности версии агрегата из коробки), проекции — подписчики, catch-up subscriptions. Гибрид: обычная БД + outbox-события для интеграций — 80% пользы при 20% сложности.', 'Почему eventual consistency — цена CQRS и как она бьёт по UX? Что такое upcast событий и почему schema evolution — главная боль ES? Когда обычная БД + outbox даёт пользу ES дешевле?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'JWT против сессий: stateless-цена — отзыв, инвалидация, logout?', 'JWT stateless: подпись гарантирует целостность, сервер не хранит состояние — горизонтальное масштабирование без общего хранилища сессий. Цена: невозможно отозвать до истечения (access 5-15 мин — компромисс); logout — клиент удаляет токен (сервер не помнит — украденный живёт до expiry); отзыв при компрометации — denylist по jti в Redis (уже stateful!) или смена подписи (все токены невалидны — грубо). Refresh-токен: долгий, хранится server-side (сессия всё же есть) — вращение + reuse-detection: украденный refresh использован дважды — семейство инвалидируется. Сессии: сервер-стор (Redis/DB) — отзыв мгновенный, logout реальный, размер-проблема при миллионах; cookie httpOnly — CSRF-защита нужна. Гибрид: короткий JWT access + refresh в httpOnly-cookie с серверным отслеживанием — практичный стандарт SPA. Хранение на клиенте: localStorage (XSS-уязвимость: скрипт украл) vs httpOnly-cookie (XSS не читает, но CSRF — SameSite+token). Claims-минимум: sub, exp, iat, iss, aud — не пихать PII (токен виден в логах прокси). Алгоритмы: RS/ES (асимметричные — верификатор без секрета, микросервисы), HS (симметричный — секрет shared: подписавший = проверяющий).', 'Почему JWT нельзя отозвать и что делает denylist по jti? Как refresh-вращение с reuse-detection ловит кражу токена? Где хранить токен на клиенте и от чего защищает httpOnly?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'JUNIOR', 'Первое техсобеседование: формат, типовой flow, как готовиться?', 'Формат среднего джун-флоу: скрин HR (10-15 мин мотивация/зарплата) → техническое интервью (60-90 мин: алгоритмы 1-2 easy/medium, вопросы по языку/ООП, иногда live-coding) → иногда системный мини-дизайн или тестовое → финал (команда/менеджер). Типовые темы джуна: ООП (инкапсуляция/полиморфизм на примерах), коллекции (HashMap базово, ArrayList/LinkedList), строки, исключения, базовый SQL (join, group by), простые алгоритмы (два указателя, хеш-множество, сортировки наизусть не нужны — понимать O), HTTP-базис (методы, статус-коды), Git-минимум. Live-coding: проговаривать ход мысли вслух (молчание = красный флаг), уточнять входные данные, сначала brute-force потом оптимизация, тестировать на примерах вслух. Подготовка: 50-100 задач easy-medium на leetcode (паттерны: hash-map, two-pointers, sliding window, BFS/DFS), собственные pet-проекты уметь рассказать (какая задача, стек, что именно делал ты), резюме знать наизусть — спрашивают по каждой строке. Психология: не знать ответ — нормально («не сталкивался, но предположил бы...») — оценивают мышление; переспрашивать — нормально; отказ — статистика, не приговор.', 'Какие три темы спрашивают почти на каждом джун-собеседовании? Что делать на live-coding, если не знаешь решение сразу? Зачем проговаривать мысли вслух и что говорит молчание интервьюеру?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Онбординг на новое место: первые 90 дней — как зарекомендовать себя?', 'Дни 1-30 (учусь): поднять окружение по README (фиксить доку по мере прохождения — первые благодарности), карта системы (кто какой сервис ведёт, как ходит трафик), первые мелкие таски (good-first-issue уровня: баг-фикс, тест, логирование) — цель: закрыть цикл «ветка→PR→мерж→прод» на первой неделе; слушать больше, предлагать меньше (контекст ещё не набран). Дни 31-60 (вклад): таски среднего размера, ревью чужих PR (внимательные вопросы — лучший способ выучить код и познакомиться), первую несложную инициативу (метрика, скрипт, дока) — маленькую и законченную; понять процесс релизов и онколл (встать в shadow). Дни 61-90 (самостоятельность): задача со сквозной ответственностью (фича от дизайна до прода), дежурство самостоятельно, наработки решений не «как в прошлом месте», а с учётом местного контекста. Контакты: 1-1 с лидом (ожидания — прямо спросить: «что будет успешным испытательным сроком?»), ментор назначен? нет — найти неформально. Антипаттерны: переписывать легаси «правильно» без спроса, молчать на стояках когда непонятно, тонуть неделю в проблеме без эскалации (правило: 30-60 минут тупика — иди спрашивай).', 'Что должно случиться в первую неделю на новом месте и почему это важно? Когда уместно предлагать изменения процессов новичку? Правило 30-60 минут и почему молчаливое тупление — худшая стратегия?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Tech-лид: техдолг-менеджмент, arguing с бизнесом, время на качество?', 'Техдолг-менеджмент: инвентаризация (реестр: что, риск, стоимость фикса сейчас vs позже), квота на погашение в каждом спринте (20% времени — защищать как фичу), привязка к рискам (инцидент из-за долга — аргумент №1 для погашения), visible-радар (дашборд возрастающих рисков). Спор с бизнесом о времени на качество: переводить на их язык — деньги и риски (баг в проде = N часов дежурных + репутация; медленный релиз = неделя задержки фичи = упущенные контракты), данные > мнения (метрика lead time, failure rate до/после), предлагать выбор с ценой («фича X за 2 недели без тестов — 40% риск падения прода в первый месяц» — пусть решают информированно). Правило качества: definition of done включает тесты/ревью/метрики — не предмет торга каждой задачи; technical excellence — маркетинговая смерть если объяснять красотой кода — объяснять скоростью поставки. Уровни лома: critical (чиним сейчас), high (ближайший спринт), medium (в реестр с квотой), low (только при касании файла — boy-scout rule). Роль лида: не самый умный кодер, а мультипликатор команды — время на парное программирование/ревью окупается.', 'Как продать бизнесу время на техдолг через деньги и риски, а не «красоту кода»? Что должно входить в definition of done и почему это не предмет торга? Как приоритизировать долг: критичный сейчас vs при-касании?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Декомпозиция монолита: strangler fig, seams, данные — безопасный путь?', 'Strangler fig: новый функционал — сразу в новых сервисах; старый — постепенно «оплетается»: фасоль-прокси (routing в шлюзе: часть URL → новый сервис), инкрементальное переключение трафика (canary по проценту/сегменту), старый код отмирает — в конце прокси удаляется. Seams (швы): границы разреза — по доменам (DDD bounded contexts: заказы, платежи, каталог), не по техслоям (вынести «все репозитории» — антипаттерн); признак хорошего шва: данные домена вместе, редко трогается другими. Данные — сложнее кода: shared database (обе версии пишут одну схему — переходный этап только), затем отдельная схема → отдельная БД, синхронизация через CDC/outbox-события (старый монолит публикует изменения, новый строит своё состояние); distributed transactions заменить сагами/ eventual consistency. Порядок: (1) выделить модуль в монолите (пакеты, ArchUnit-границы — без деплоя), (2) модуль → сервис с own DB, (3) переключить трафик, (4) убрать старое. Антипаттерны: «распилить всё за квартал» (биг-банг), микросервисы без доменной карты (распределённый монолит — хуже исходного), игнор оргструктуры (закон Конвея: границы сервисов = границы команд).', 'Почему швы по доменам, а не по техслоям — что ломается при тех-разрезе? Как разделяют данные при strangler-миграции и зачем CDC? Что такое распределённый монолит и почему он хуже цельного?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Idempotency keys и exactly-once на границе систем — практика?', 'Idempotency: операция повторима без вреда — ключ (UUID от клиента) + хранение результата: первый запрос выполняет и сохраняет (key→результат/статус), повтор с тем же ключом возвращает сохранённый ответ без повторного эффекта; срок жизни ключа (24ч), конкурентные повторы — блокировка (in-flight статус: второй запрос ждёт/отклоняется 409). Где обязательна: платежи (двойное списание при retry клиента/прокси), создание ресурсов из колбеков (Kafka at-least-once — consumer упал после сайд-эффекта до коммита → повтор), любые POST с деньгами/созданием; header Idempotency-Key — стандарт Stripe-стиля. БД-уровень: уникальный констрейнт на (user_id, operation_key) — дубль падает → приложение возвращает существующий результат; оптимистичная блокировка @Version для апдейтов. Kafka-консьюмер: обработка + коммит смещения не атомарны — варианты: (1) идемпотентный обработчик (ключ в БД — повтор безопасен), (2) смещение в той же транзакции БД, что и результат (transactional consumer). Exactly-once end-to-end: конвейер Kafka→Kafka — транзакции продюсера; Kafka→внешняя БД — только идемпотентность приложения (Kafka-транзакции туда не тянутся). Ретраи клиентов: сервер должен переживать повтор (PUT идемпотентен по RFC — PUT с тем же телом = тот же результат; POST — нет, потому ключ).', 'Как хранится результат идемпотентной операции и что делать при параллельном повторе с тем же ключом? Почему Kafka-консьюмер обязан быть идемпотентным при at-least-once? Чем PUT идемпотентен по природе, а POST нет?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'MongoDB: индексы и план исполнения — explain, covered, ESR — практический разбор?', 'explain("executionStats"): totalKeysExamined (индекс-ключей) vs totalDocsExamined (документов) vs nReturned: идеал IXSCAN keys≈returned, COLLSCAN (без индекса — весь сканинг) красный флаг; stage: IXSCAN → FETCH (документ по указателю) → SORT (in-memory сортировка — 32MB лимит abort!). Covered query: индекс содержит все запрошенные поля → FETCH пропущен (projection только индексные поля). ESR-правило compound-индекса: Equality поля первыми, Sort потом, Range последним: {user: 1, status: 1, createdAt: -1} под запрос user=X status=Y order by createdAt → equality+sort закрыты индексом, range по createdAt не мешает сортировке; перепутать порядок (range перед sort) — SORT-стейдж в памяти. Частичные индексы: partialFilterExpression (индекс только по archive=false — меньше размер). TTL-индексы (expireAfterSeconds) — автоудаление сессий/логов. Text-индексы — полнотекст (или внешний поиск — elastic). $hint для принуждения (диагностика). Мониторинг: profiler (db.setProfilingLevel(1, {slowms: 100})), $indexStats (usage — неиспользуемые сносить). Кластеризованные коллекции (clustered index on _id) — диапазонные сканы по времени.', 'Какие три числа explain сравнить для оценки индекса и что такое идеальное соотношение? Что даёт ESR-порядок и почему range перед sort ломает план? Зачем partial-индекс и $indexStats?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Redis: структуры данных (hash, sorted set, stream) — что под какую задачу?', 'Структуры под задачи: String — кэш объекта (сериализованный JSON), счётчики (INCR), distributed lock (SET NX PX). Hash — объект с полями (HSET user:1 name X age 30): частичное чтение/запись без десериализации всего; HINCRBY атомарный. List — стек/очередь (LPUSH+BRPOP — blocking), timeline (LPUSH+LTRIM фиксированная длина). Set — уникальные (SADD), теги/подписки, операции SINTER/SUNION (пересечение подписок), SRANDMEMBER — случайные. Sorted Set — рейтинг (ZADD score=очки, ZREVRANGE топ-N), приоритетная очередь (score=timestamp), sliding-window rate limiter (ZADD now, ZREMRANGEBYSCORE окно, ZCARD счёт), delayed-задачи (score=when, ZRANGEBYSCORE готовые). Stream — append-only лог с consumer groups (XADD/XREADGROUP/XACK): очередь с подтверждением обработки, pending-list (XPENDING — необработанные, XCLAIM перехват), в отличие от List: история, группы, авто-ack нет — контроль. HyperLogLog — cardinality (миллионы уникальных на 12KB — PFADD/PFCOUNT). Bitmap — активность по дням (SETBIT user:day, BITCOUNT). Практика: ключи с TTL всегда (кроме очередей),命名 namespace:user:id:field, big-key избегать (миллион элементов — резать).', 'Какая структура лучше для топа пользователей и почему sorted set? Чем Stream отличается от List-очереди по семантике обработки? Что считать на HyperLogLog и почему он такой маленький?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Виртуальные потоки и Spring: enable-флаг, @Async, JDBC — что реально ускоряется?', 'spring.threads.virtual.enabled=true (Boot 3.2+): Tomcat обрабатывает запросы на VT, @Async и @Scheduled тоже переезжают; эффект — IO-bound throughput: запросы, ждущие БД/HTTP/Redis, не занимают platform-потоки — сотни тысяч конкурентных запросов без WebFlux. Что НЕ ускоряется: CPU-bound (парсинг, крипто — ядер не больше), долгие synchronized-секции (pinning — до JDK 24 synchronized не паркует VT: carrier заблокирован — при конкуренции деградация), JNI/native блокировки, JDBC-драйверы с synchronized-внутренностями (до JDK 21 фиксы в драйверах — pgjdbc обновить!). Практика: пул соединений — главный новый bottleneck (10 коннектов Hikari — VT очередь в БД, а не потоки — sizing пересмотреть или PgBouncer); ThreadLocal-загрязнение: миллионы VT × MDC/security-контекст — передача через ScopedValue; structured concurrency для параллельных вызовов внутри запроса (два сервиса параллельно: Executors.newVirtualThreadPerTaskExecutor + invokeAll). Совместимость: logback/MDC — context-propagation-библиотека; OpenTelemetry-агент — поддержка VT из коробки в свежих. Мониторинг: jcmd Thread.dump — видно паркинги; метрики carrier-пула. Миграция: включить флаг → нагрузочный тест → смотреть pinning (jfr jdk.VirtualThreadPinned).', 'Какой класс приложений получает прирост от VT и почему CPU-bound не ускоряется? Что становится новым узким горлышком при VT+JDBC? Как обнаружить pinning виртуальных потоков в проде?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Optional в Java и nullable в Kotlin: конвергенция подходов к отсутствию значения?', 'Java Optional: тип-обёртка для «может не быть» — возвращаемый тип только; методы: map/flatMap (трансформация), orElse/orElseGet (дефолт: первый вычисляет выражение всегда!), orElseThrow, ifPresentOrElse (Java 9+), or (альтернативный supplier, 9+), stream() — фильтрация пустых. Антипаттерны: поле Optional (не сериализуется), параметр Optional (лучше перегрузки), Optional.get без проверки, Optional.of(null) — NPE сразу (ofNullable для сомнительных), isPresent+get — хуже map. Kotlin: nullable T? встроен в систему типов: safe call ?., elvis ?:, smart-cast после проверки, let-цепочки; конвергенция: оба решают «null-проблему», но Kotlin — компайл-тайм гарантией, Java — конвенцией обёртки; platform types — границы. Взаимодействие: JvmOptionals (Kotlin-расширения: getOrNull, getOrDefault, toNullableU). Коллекции: пустая коллекция вместо Optional<List> — сама семантика отсутствия уже есть. Примитивы: OptionalInt/Long/Double — без бокса; свёртка: orElseGet дорогого вычисления — лениво. В API: Optional возвращает честнее null-контракта; javadoc @Nullable — второй путь (annotations + инструменты: Checker, Spring nullability). В стримах: stream.findFirst() → Optional; flatMap(Optional::stream) — фильтрация с сохранением.', 'Чем orElse отличается от orElseGet и когда это важно для производительности? Почему Optional-поле и Optional-аргумент — антипаттерны? Как Kotlin решает ту же проблему на уровне системы типов?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Records + Jackson/JPA: сериализация, десериализация, валидация — грабли границ?', 'Record + Jackson (2.12+): десериализация через канонический конструктор (не через setters — их нет); @JsonProperty на компонентах переименовывает, @JsonIgnore исключает; Jackson вызывает канонический конструктор — валидация в компактном конструкторе выполняется при десериализации (броски — 400-маппингом); @JsonCreator как альтернатива; unknown-поля: @JsonIgnoreProperties(ignoreUnknown=true) — иначе UnrecognizedPropertyException на лишних полях клиента; immutable + Jackson — никаких проблем потокобезопасности. Валидация Bean Validation: @Valid на record-компонентах работает (JSR-380 на полях конструктора) — но сообщение не знает имя поля без @JsonProperty соответствия. JPA: record НЕ сущность (нет прокси, ленивости, dirty checking) — но идеален как DTO-проекция: constructor expression JPQL (select new ru.app.UserDto(u.id, u.name)), interface projection, @Query с new. MapStruct: record-таргет работает из коробки (конструктор). Грабли: канонический конструктор с валидацией + Jackson пишет в него null — null-check обязателен (Objects.requireNonNull / List.copyOf падают — JsonMappingException обёртка — маппить в 400 осмысленно); Jackson+records требует jackson 2.12+ (Boot 2.5+); вложенные records — рекурсивная десериализация ок; Optional-компонента в record — Jackson сражается (jdk8-module) — лучше nullable-тип с @Nullable-аннотацией.', 'Как Jackson создаёт record без сеттеров и где выполняется валидация? Что сделать с unknown-полями запроса и почему это падает по умолчанию? Почему record идеален для DTO-проекций JPA и невозможен как сущность?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Switch-выражения и pattern matching: новые синтаксисы Java 14-21 — практическое применение?', 'Switch-выражение (14+): yield значение, стрелочные case без fall-through (главный источник багов старого switch), multi-label case 1, 2, 3 ->; исчерпываемость с sealed — компилятор требует все варианты или default. Pattern matching for instanceof (16): if (o instanceof String s && s.isBlank()) — переменная сразу; убивает явный каст — тройную конструкцию. Pattern matching for switch (21): case Integer i when i > 0 -> (guarded-паттерны, 21 preview/22 финал), case null -> (null-обработка в switch — до этого NPE сразу), доминирование паттернов проверяется (частный до общего — иначе ошибка компиляции). Record deconstruction (21): case Line(Point(var x1, var y1), Point p2) -> — разбор вложенных данных прямо в case; с sealed-иерархией = алгебраические типы: исчерпывающая обработка вариантов с типобезопасным доступом к полям. Практика: парсинг Result/Either-подобных sealed: case Success(var value) → ..., case Failure(var code, var msg) → ...; замена цепочек if-instanceof (антипаттерн instanceof-каскады читаются ужасно). Совместимость со старым switch: двоеточие-синтаксис остаётся (fall-through) — в новом коде стрелки всегда.', 'Чем стрелочный case отличается от двоеточия по fall-through и почему это важно? Что даёт case null в switch-21 и как обрабатывался null раньше? Как record deconstruction + sealed заменяют visitor-паттерн?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Collectors.teeing, mapping, flatMapping — редко используемые, но решающие?', 'teeing(c1, c2, merger) (Java 12+): два коллектора параллельно над одним стримом, потом слияние результатов: статистика за один проход — count и sum: teeing(counting(), summingDouble(Double::doubleValue), (n, s) -> s/n) — среднее; min/max в один проход для диапазона. mapping(mapper, downstream): преобразовать элементы ПЕРЕД downstream-коллектором внутри groupingBy: groupingBy(city, mapping(Person::name, toList())) — мапа город→лист имён (без mapping — лист Person). flatMapping (9+): flatten вложенных: groupingBy(user, flatMapping(u -> u.roles.stream(), toSet())) — user→сет ролей из вложенных списков; аналог flatMap, но на уровне коллектора внутри группировки (flatMap до groupingBy изменит ключ группировки — нельзя). filtering(predicate, downstream): фильтр внутри группы: groupingBy(city, filtering(p -> p.age > 18, counting()) — взрослые по городам; от filter-до-groupingBy отличается: группы без подходящих НЕ исчезают (пустой список/ноль) — сохранение полного набора ключей. collectingAndThen: пост-обработка результата (toSet → unmodifiable, averaging → rounding). Практический паттерн: отчёты «за один проход»: teeing + groupingBy заменяют цикл с картой аккумуляторов; читаемость: вложенные коллекторы сложнее цикла на 3+ уровней — граница разумного.', 'Чем groupingBy с mapping-downstream отличается от map до groupingBy? Когда filtering внутри группировки лучше filter до неё? Что посчитает teeing за один проход и почему это эффективно?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Параллельные стримы на практике: когда оправданы и как правильно измерить?', 'parallelStream: сплит источника (Spliterator), ForkJoinPool.commonPool, work-stealing. Оправдан: CPU-bound обработка, большие N (>10k элементов), простые лямбды без блокировок, хорошо делимый источник (массив/ArrayList — идеальный сплит; LinkedList/iterate — плохой, stream.iterate несплитуем — parallel молчит и работает последовательно!). Не оправдан: IO в лямбде (общий пул ограничен ядрами-1 — все ждут сеть, CPU-задачи голодают), маленькие N (оверхед fork/join > выигрыша), мутации общего состояния (гонки), ordered-операции (forEachOrdered, limit в ordered-стриме сериализует), Java 9+ takeWhile/dropWhile в parallel — слабое распараллеливание. Изоляция: свой пул — customPool.submit(() -> list.parallelStream()...).get() (хак, но работает) — когда общий пул занят чужими задачами. Измерение: JMH (warmup, forks), режим Throughput, сравнить seq vs par на прод-размере данных; метрики: не только ops/time, но и allocation rate (parallel бьёт по GC). Альтернативы: явный executor с батчами (управляемый параллелизм, IO-friendly), virtual threads для IO. Debug: пайплайн с parallel — стек-трейсы в ForkJoinTask — сложнее; отладка через peek с идентификатором потока.', 'Почему stream.iterate в parallel молча работает последовательно? Как изолировать параллельный стрим в собственный пул и когда это нужно? Какие две метрики сравнивать в JMH для seq vs parallel?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Spring MVC: перехватчики, фильтры, резолверы — где какая точка расширения?', 'Порядок запроса: Filter (servlet-уровень, до Spring MVC: кодировка, CORS, security-цепочка, requestId-MDC, gzip; OncePerRequestFilter базовый класс; регистрация FilterRegistrationBean с order) → DispatcherServlet → HandlerMapping находит контроллер → Interceptor (preHandle → контроллер → postHandle → afterCompletion — исключения в afterCompletion; задачи: авторизация действий, измерение времени, обогащение модели, логирование; addInterceptors в WebMvcConfigurer; порядок order) → аргумент-резолверы (HandlerMethodArgumentResolver: инъекция принципала, своих объектов из заголовков) → контроллер → возвращаемое значение → HttpMessageConverter (сериализация) → @ControllerAdvice (@ExceptionHandler глобально, @ModelAttribute, @InitBinder — биндинг-кастомизация). Фильтр vs интерцептор: фильтр — про запрос целиком (даже не-MVC ресурсы), интерцептор — про handler (доступ к методу-хендлеру, аннотациям на нём); security-логика может в обоих — конвенция: аутентификация (кто) в фильтре, авторизация (можно ли этому) — в интерцепторе/метод-секьюрити. Async-обработка: Callable/DeferredResult/WebAsyncTask — освобождение потока Tomcat; фильтры оборачиваются AsyncListener-ом — тонкости dispatch. Реестр: несколько фильтров/интерцепторов — порядок критичен (MDC-фильтр до security-логирования).', 'Что выполняется раньше — фильтр или интерцептор — и какие данные доступны каждому? Почему аутентификация в фильтре, а авторизация в интерцепторе — конвенция? Зачем @InitBinder и @ExceptionHandler в @ControllerAdvice?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Spring Cache: @Cacheable, менеджеры, инвалидация — кэш без сюрпризов?', '@Cacheable(cacheNames="users", key="#id") — до метода: есть в кэше → вернуть из кэша, метод не вызывается; @CachePut — всегда выполнить и обновить кэш; @CacheEvict — удалить (allEntries=true по паттерну); @Caching — композиция; key SpEL: #param, #param.field, result → T (root). Менеджеры: ConcurrentMap (дефолт, in-memory, без TTL — только для тестов/моно), Caffeine (in-memory production: maximumSize, expireAfterWrite, near-cache идеал), Redis (распределённый, TTL, но сериализация: JSON-значения — JDK-сериализация хрупка), multi-level (Caffeine+Redis — сложность инвалидации ×2). Грабли: (1) self-invocation — прокси-мимо (как @Transactional); (2) key по умолчанию — все параметры: mutable-ключ (DTO без equals) = каждый раз промах/неверный hit — ключ явным SpEL; (3) null-кэширование: unless="#result == null" или nullValues-настройка — иначе NullPointerException-вызовы не кэшируются (thundering herd на отсутствующих); (4) TTL vs актуальность: обновление БД мимо @CachePut → stale до expiry — инвалидация по событию (evict из service-метода записи); (5) сериализация: смена класса → десериализация падает (JsonSerializable + версии); (6) cache- промахи при разных toString у ключа-объекта. Мониторинг: hit/miss ratio (Caffeine recordStats + Micrometer), размер; sync=true — синхронная загрузка (защита от stampede одного ключа).', 'Чем @Cacheable отличается от @CachePut и когда нужен каждый? Какие три классических бага с ключами кэша? Как устроена многоуровневая инвалидация Caffeine+Redis и чем она сложна?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'JPA: наследование (SINGLE_TABLE/JOINED/TABLE_PER_CLASS) и когда без него?', 'Стратегии: SINGLE_TABLE (дефолт) — одна таблица, discriminator-колонка, поля подклассов nullable (нет NOT NULL — констрейнты теряются!); быстрая (без join), но редкие подклассы с множеством полей раздувают таблицу. JOINED — таблица на класс, join по id: нормализовано, NOT NULL работают, но каждый запрос = join (или несколько при глубокой иерархии), запись в две таблицы. TABLE_PER_CLASS — таблица на конкретный класс, полиморфные запросы через UNION ALL — медленно, identity (@Id) не генерится автоматически (sequence-пул); редко оправдана. @MappedSuperclass — без таблицы, только шаринг полей/маппингов (audit-базовый класс: id, createdAt) — не полиморфизм, нет запросов по родителю. Выбор: полиморфные запросы нужны (Animal→Dog/Cat с общим поведением) — SINGLE_TABLE при малом числе специфичных полей, JOINED при строгих констрейнтах; полиморфизм не нужен — композиция (Type-поле + enum) проще и быстрее: стратегия «наследование в коде, плоская таблица в БД» часто лучший. Грабли: eager-fetch коллекций в иерархии (картезиан), discriminator-значения вручную (читаемость), abstract-сущность с @DiscriminatorFormula (вычисляемый тип).', 'Чем SINGLE_TABLE быстрее JOINED и какие констрейнты она теряет? Почему TABLE_PER_CLASS ломает identity-генерацию? Когда композиция с enum-полем лучше любой стратегии наследования?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kotlin + Spring: корутины в веб-слое, WebFluxKT, suspend-контроллеры?', 'Spring + suspend: контроллеры/WebFlux поддерживают suspend-функции напрямую: suspend fun getUser(): UserDto — фреймворк вызывает в реактивном контексте (CoroutinesUtils.invokeSuspending); в MVC (Boot 3.2+) — suspend выполняется на виртуальных/платформенных потоках с асинхронной диспетчеризацией. R2DBC-репозитории: suspend-методы в CoroutineCrudRepository — реактивный драйвер БД без блокировки; JDBC — блокирующий: withContext(Dispatchers.IO) (VT смягчает). Последовательные независимые вызовы в suspend — зло: async/awaitAll (coroutineScope { val a = async {...}; val b = async {...} }) — параллельность; structured concurrency — отмена по таймауту: withTimeout(2.seconds). Flow из репозитория → контроллер отдаёт Flow<Dto> (стриминг, NDJSON). MDC/контекст: контекст корутины + ThreadContextElement (MDCContext-библиотека) — иначе trace_id потеряется. Тестирование: runTest + MockK coEvery/coVerify; WebTestClient + awaitExchange. Границы: смешивать блокирующий и suspend-код аккуратно (RunBlocking только в main/тестах); Dispatchers.Unconfined — не для прода. Отладка: -Dkotlinx.coroutines.debug — имена корутин в стектрейсах, IDEA coroutine debugger.', 'Как Spring вызывает suspend-контроллер и что происходит с потоком запроса? Почему JDBC в корутинах требует withContext(IO)? Как сделать два независимых запроса параллельно и добавить таймаут на оба?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kotlin serialization, data classes, copy — иммутабельность домена на практике?', 'kotlinx.serialization: @Serializable data class — компайл-тайм генерация сериализатора (без reflection — быстро, работает на native/JS); @SerialName переименование полей, @Transient исключение, default-значения — optional-поля JSON; polymorphic-сериализация sealed-иерархий (classDiscriminator — авто type-поле); Json { ignoreUnknownKeys, coerceInputValues, explicitNulls } — конфигурация строгости; конфликт с Jackson: в Spring-стеке по умолчанию Jackson — подключить KotlinModule (data class, nullability соблюдаются!) или заменить на kotlinx (Spring Boot customizer). Data class: copy(...) — функциональное обновление: val updated = user.copy(email = "new") — новая инстанция, остальные поля те же; компонуется с validation (init-блок / require). Иммутабельный домен: val-поля, List (не MutableList), copy для изменений — безопасный шаринг между потоками; цена: массовые изменения — цепочка copy (аллокации) — для hot path внутренняя мутабельность + иммутабельная граница. destructuring: val (id, name) = user — по componentN; в лямбдах map { (id, _) -> id }. equals/hashCode из всех полей авто — data class в ключах коллекций безопасен (в отличие от обычного класса с var-полями). sealed + data class + when — доменное моделирование: статусы, результаты, команды.', 'Чем copy() решает проблему обновления иммутабельного объекта и что с производительностью цепочек? Почему нужен KotlinModule для Jackson и что он даёт data-классам? Как сериализуется sealed-иерархия в JSON?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kotlin: делегаты (by lazy, by map, custom) — property delegation на практике?', 'Delegated properties: val x by Lazy { expensive() } — лень с потокобезопасностью (SYNCHRONIZED дефолт; PUBLICATION — без блокировки после первого; NONE — однопоток); var_observed by Delegates.observable(v) { _, old, new -> log } — наблюдение изменений; vetoable — отклонение изменений; by map: class Config(val map: Map<String, Any>) { val url by map } — ключ=имя; custom delegation: operator getValue/setValue на классе — пример: сессионные атрибуты, DB-бэкед поля (ReadProperty/WriteProperty интерфейсы). Stdlib-делегаты: lazy, observable, vetoable, notNull (поздняя инициализация без lateinit-исключения). Под капотом: компилятор генерит поле-делегат и вызовы getValue(thisProp) на каждом доступе — цена: один объект-делегат + вызов метода (JIT инлайнит) — negligible в 99%. Практика: lazy для тяжёлых зависимостей view/service; map-делегат для динамических конфигов (env-словари); custom для транзакционных/кешируемых свойств (RedisProperty: getValue читает кэш, setValue пишет). Границы: делегат состояния на каждый инстанс (поле) vs object-делегат (один на класс) — память при миллионах инстансов. Kotlin/библиотеки: Kodein/DI на делегатах (inject by provider).', 'Какие три режима потокобезопасности у lazy и когда NONE безопасен? Что генерирует компилятор для by lazy и какова цена доступа? Напишите custom-делегат, читающий поле из Redis — какие методы нужны?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kubernetes: CronJob, Jobs, initContainers — фоновые задачи в кластере?', 'Job — разовый запуск до completion (completions, parallelism); restartPolicy Never/OnFailure; бэкофф при падении (backoffLimit=6). CronJob — расписание cron: schedule "0 3 * * *", timeZone (1.27+), concurrencyPolicy: Allow (параллельные — пропустили запуск, предыдущий ещё жив), Forbid (пропустить новый), Replace (убить старый); startingDeadlineSeconds — окно запуска (пропущенные при даунтайме контроллера); successfulJobsHistoryLimit — аудит. Идемпотентность обязательна: Job может перезапуститься (узел умер — контейнер пересоздан, код выполнился частично); с ShedLock/DB-флагом при множественных кластерах. initContainers — подготовка перед основными: миграции БД (init-контейнер с flyway до старта приложения — порядок гарантирован, образ тот же джарник), загрузка ключей, ожидание зависимости (nc -z db 5432 — бед-man-паттерн, лучше readiness-dependency). Sidecar-паттерн (1.28+ native sidecars: initContainers с restartPolicy Always — proxy/log-collector, живут с подом). Практика: CronJob-задачи — отдельные small-образы (не весь fat-jar с веб-сервером), лимиты ресурсов, activeDeadlineSeconds (защита от зависания), уведомление о failure (Job-статус → Prometheus/KubeEvent). Альтернативы: kafka-консьюмер-деплой (долгоживущий) vs CronJob (пакетный) — по природе задачи.', 'Чем concurrencyPolicy Forbid отличается от Replace при наложении расписания? Почему Job обязан быть идемпотентным и что его перезапускает? Что даёт native sidecar в 1.28+ против обычного контейнера?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kubernetes: StatefulSet, PV/PVC, storage classes — состояние в кластере?', 'StatefulSet: стабильные идентификаторы (pod-0, pod-1 — ordinal), стабильный storage (PVC per-pod через volumeClaimTemplates — при пересоздании пода том перепривязывается тому же ординалу), упорядоченный rolling update (pod by pod сверху вниз), headless service (clusterIP None) — DNS per-pod (pod-0.pg.data.svc). Для: БД-кластеры (PostgreSQL patroni, Kafka, Cassandra) — идентичность узлов критична. Deployment+PVC — для singleton-состояния (один PVC на все реплики — ReadWriteMany для параллельных, иначе одна реплика пишет). Storage: PV — физический том (облако/локал), PVC — запрос на том (size, access mode, storageClassName); StorageClass — динамическое provision (standard SSD, fast NVMe) + reclaimPolicy (Delete — данные исчезнут с PVC! Retain — сохранить); VolumeBindingMode WaitForFirstConsumer — том создаётся в зоне пода. Local PV — высокая скорость, привязка к узлу (под прибит к узлу — узел умер = данные недоступны до возврата). Внешнее хранилище vs in-cluster: прод-БД в k8s — патронi/операторы (CloudNativePG) с репликацией и backup-операцией, либо managed вне кластера (RDS) — проще; in-cluster оправдан для dev/собственных кластеров с операторами. Backup: CSI snapshots, Velero (весь кластер), pg_dump/WAL-архив — БД-специфика обязательна.', 'Чем PVC у StatefulSet отличается от PVC у Deployment по привязке к подам? Что означает reclaimPolicy Delete и чем опасен? Когда БД в кластере оправдана против managed-RDS?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Liquibase vs Flyway: сравнение и миграция между ними?', 'Flyway: SQL-first — чистые .sql с версией в имени (V1__, R__repeatable); простота, предсказуемость, checksum-валидация; undo — платная версия (на практике откаты новыми миграциями). Liquibase: XML/YAML/JSON/SQL-абстракция (changelog, changeset: createTable/addColumn — БД-независимость), databasechangelog-таблица, premConditions/rollback-секции (авто-генерация отката для части операций), diff-инструменты (сравнение схем), контексты/лейблы (один ченджлог на окружения). Выбор: одна СУБД, SQL-культура — Flyway (проще, прозрачнее); мульти-СУБД продукт, GUI-инструменты, формальные rollback — Liquibase. Миграция между: обе держат таблицу истории — недостающие версии подтянутся при первом запуске нового инструмента: заморозить старые изменения в истории, новые вести новым инструментом (Flyway с baselineOnMigrate поверх существующей схемы Liquibase — baseline фиксирует текущее состояние). Общие правила: миграции идемпотентны где возможно (IF NOT EXISTS), большие таблицы — онлайн-операции (CONCURRENTLY, batch-бэкофилл), CI-прогон на копии данных, checksum конфликт (ветка изменила применённый файл) — resolve (flyway repair — осознанно!). Distribution lock: миграции в момент старта нескольких реплик — Flyway берёт advisory-lock PG — безопасно из коробки.', 'Когда Liquibase оправдан против Flyway и чем платим за абстракцию? Как перейти с одного на другой без даунтайма? Что делать при checksum-конфликте и почему это вообще происходит?' from categories where slug = 'db-migrations';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Данные: партиционирование таблиц в PostgreSQL — когда и как?', 'Партиционирование: таблица-родитель разбита на партиции по диапазону/списку/хешу (declarative, PG 10+): RANGE по времени (логи, события — месячные партиции), LIST по tenant/region, HASH для равномерного размазывания. Когда: таблицы >100GB или >100M строк: vacuum не успевает, индексы гигантские, запросы по фильтру партиционирования — partition pruning (планер режет ненужные партиции: WHERE created_at BETWEEN — только 2 партиции сканируются). Достоинства: DROP PARTITION — мгновенное удаление старых данных (вместо DELETE миллиардов строк + bloat); партиционные индексы локальные (rebuild по одной); maintenance изолирован. Ограничания: уникальные констрейнты обязаны включать ключ партиционирования (PK по id невозможно при range по дате — PK (id, created_at)); foreign keys на партиционированную таблицу (PG 12+ — ok, но осторожно); UPDATE ключа = перенос между партициями (row movement); join между партиционированными таблицами — partition-wise join (enable_partitionwise_join). Автоматизация: pg_partman (автосоздание партиций вперёд, ротация),/range по месяцу; выбор ключа — под запросы (время — 90% случаев). Альтернатива: archiving в отдельную таблицу, BRIN-индекс для append-only (компактнее в 1000 раз B-tree на time-series).', 'Какие три типа партиционирования и под какие запросы каждый? Почему PK партиционированной таблицы обязан включать ключ разбиения? Чем DROP PARTITION лучше DELETE для старых данных?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'MongoDB aggregation pipeline: $match, $group, $lookup, $facet — отчёты без MapReduce?', 'Pipeline — конвейер стадий над документами: $match (фильтр — первым! до $group — использует индексы и режет объём), $project/$addFields (форма/вычисления), $group (агрегация: _id ключ, сумма $sum, среднее $avg, массивы $push/$addToSet, first/last), $sort/$limit/$skip, $unwind (развернуть массив — каждый элемент отдельным документом: опции preserveNullAndEmptyArrays), $lookup (left outer join: from, localField/foreignField, as — вложенный массив; с pipeline-синтаксисом — фильтрация на месте join), $facet (несколько под-конвейеров над одним входе — страница данных + totalCount за один проход!), $bucket/$bucketAuto (гистограммы), $merge (результат в коллекцию — materialized view), $setWindowFields (окна: нарастающий итог, lag/lead). Оптимизация: $match + $project как можно раньше (сократить поток), allowDiskUse (100MB стадия — большие сортировки), индексы под $match+$sort первой стадии (covered scan), $lookup — дорого: денормализация вместо частых join. Практика: пагинация с $facet (items + total), отчёт по дням ($group по $dateToString), обогащение справочником $lookup один-к-одному — допустимо. Exchanges: explain на aggregate — стадии и используемые индексы.', 'Почему $match обязан идти первой стадией, где возможно? Что делает $facet и какую типовую задачу решает одним проходом? Почему $lookup считается дорогим и что вместо него в hot-path?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Redis в проде: maxmemory, eviction, latency — типовые инциденты и профилактика?', 'maxmemory обязателен: без него Redis растёт до OOM-убийства (очередь сообщений с replication backlog — быстрый рост); maxmemory-policy: noeviction (дефолт — записи падают OOM error: осознанно для очередей/lock!), allkeys-lru (кэш — классика), volatile-lru (с TTL только), allkeys-lfu (частотный — лучше при скewed-доступе), volatile-ttl (ближайшее истечение). Latency-источники: (1) KEYS * — блокирующий обход: SCAN cursor (не блокирует, итеративно); (2) big keys — удаление DEL большого списка блокирует (миллионы элементов): UNLINK (асинхронное удаление, lazy-free), big-value операции (HGETALL гигантского hash — рассмотреть hash-под-slot: key:subkey); (3) fork под RDB/AOF-rewrite — страница-copy копирование: при 10GB записей + высокой записи — задержки (latency spike при save);复制ит off-peak или replica-only persistence; (4) expiry-шторм (миллион ключей истекает одновременно — активный цикл истечения ест CPU) — jitter TTL; (5) сеть/TCP — slowlog (Redis SLOWLOG — встроенный профилировщик медленных команд), latency-monitor-threshold. Инцидентный кейс: «Redis не отвечает» — top: redis-cli --latency, INFO memory (fragmentation ratio), SLOWLOG GET, monitored pub/sub. Профилактика: алерты на used_memory/maxmemory, evicted_keys rate, connected_clients, replication offset lag.', 'Чем noeviction отличается от allkeys-lru по последствиям при заполнении памяти? Почему KEYS блокирует и как SCAN решает? Что делает UNLINK и когда fork вызывает latency-пики?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kubernetes: operators и CRD — автоматизация всего — как это работает?', 'CRD — свой тип ресурса (apiVersion: myapp.io/v1, kind: BackupJob) — k8s хранит etcd, kubectl get работает; Operator — контроллер-цикл: watch CRD-объекты → reconcile желаемое vs фактическое (создать Deployment/Service/ConfigMap по спеке CR) → статус обратно в объект; kubebuilder/operator-sdk — каркас (code-gen клиентов, CRD-схемы из Go-типов, webhook-валидации). Паттерн уровня: application-оператор (одним CR описываем весь стек приложения — helm-подобно, но живое: следит и чинит), backup-оператор (CronJob + retention по спеку), DB-операторы (CloudNativePG: кластер PostgreSQL CR — failover, backup, resizing автоматом). Reconcile-принципы: идемпотентность (цикл перезапускается постоянно — любое действие должно быть безопасно к повтору), уровень усилий: не событие «создан» → сделать, а «текущее состояние ≠ желаемое» → приблизить; ownerReferences — каскадное удаление детей с CR. Когда оператор: повторяемая установка сложного стека многим командам, автоматизация recovery; когда нет — helm/kustomize достаточно (декларация без reconciliation-логики). Опасности: оператор-баг = массовые разрушения (RBAC минимальный, dry-run), сложность дебага (k8s-события + логи контроллера), vendor lock на custom CRD-схемах.', 'Что такое reconcile-цикл и почему оператор обязан быть идемпотентным? Чем CRD-подход отличается от Helm-чарта по «жизни» установки? Какие риски несёт баг в операторе и как их ограничить?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Пограничный перфоманс: String.concat vs StringBuilder vs StringWriter — микрооптимизации строк?', 'Компилятор: одиночный a + b → StringBuilder под капотом (или StringConcatFactory invokedynamic с Java 9 — стратегия комбинированной конкатенации: точные размеры, примитивы без промежуточных боксов); a + b + c в выражении — один builder — ок. Проблема — конкатенация в ЦИКЛЕ: каждая итерация новый builder + промежуточные строки: O(n²) память/время; решение — один StringBuilder снаружи (or StringWriter для IO-моста), предвыделять capacity (new StringBuilder(len) — ресайз копирует). Сравнение: StringBuilder (не синхронизирован — однопоток) vs StringBuffer (синхронизирован — legacy, не использовать) vs StringJoiner (разделители: String.join(", ", list) — под капотом) vs StringWriter (Writer-иерархия — мост к IO/библиотекам). Мелкие детали: + с константой складывается компилятором ("a" + "b" → "ab" в класс-файле); switch по строке — hashCode+equals два шага; String.format медленный (парсинг паттерна) — в горячем пути конкатенация/formatted подготовленный; repeated String.valueOf(char) — CHARACTERS_ARRAY кэш. Измерение: JMH (не догадки — JIT творит чудеса с современным concat). Реальный кейс: JSON-склейка руками — заменить на библиотеку (Jackson) — читаемость+скорость.', 'Почему конкатенация в цикле даёт O(n²) и как один builder лечит? Что делает StringConcatFactory с Java 9 и почему «+» уже не плохой тон? Чем StringJoiner удобен и когда StringWriter?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Timezone-кошмары: DST, границы, хранение — как не наступить второй раз?', 'Правила: (1) храним мгновения в UTC (Instant/timestamptz) — точка на оси времени однозначна; (2) локальное представление (ZonedDateTime с зоной пользователя) — только на отображении; (3) будущие «стенные» события (будильник на 9:00 МСК) — храним LocalDateTime + зону, пересчёт в Instant в момент наступления (DST-закон может измениться — IANA-обновления JDK!); (4) повторяющиеся расписания — cron с zone=, но 2:30 весной не существует — стратегия (shift/next-valid). Грабли: (a) сравнение LocalDateTime из разных зон (всегда ZonedDateTime/Instant для сравнения); (b) длительность между событиями: Duration между Instant — верно; между LocalDateTime — ignorance зон (летнее время не учтено); (c) Formatting с локалью vs зоной (независимы); (d) «день» в UTC vs локальный — daily-агрегации по локальному дню пользователя: группировка с AT TIME ZONE в PG; (e) JDBC: setObject(LocalDateTime) vs setTimestamp(Instant) — семантика связки с колонкой (timestamp vs timestamptz — привести соответствие); (f) JavaScript-граница: Date всегда UTC-millis, toLocaleString зона браузера; (g) ID зоны не смещение: "Europe/Moscow" знает историю (до 2011 +3/+4 переходы), "+03:00" — срез; (h) тесты с фиксированными датами вокруг DST-переходов (26 марта 2:00→3:00). Мониторинг: TZ-данные обновляются (tzdata в JRE — обновление JDK = изменение поведения расписаний!).', 'Почему будущие будильники хранят LocalDateTime+зону, а не Instant? Чем Duration между LocalDateTime неправильна через DST? Почему ID зоны лучше числового смещения и что знает история IANA?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Soft/Weak/Phantom references: кэши с умом и финализация ресурсов?', 'Reference-типы: Strong (обычная — живёт пока достижим), Soft (очищается при нехватке памяти — до OOM: чувствительный кэш, но непредсказуем по времени —现代化 замена: Caffeine с size/TTL), Weak (собирается в следующем GC при отсутствии strong — WeakHashMap: ключи weak, значения strong — auto-чистка мёртвых ключей; слушатели/кэш метаданных класса), Phantom (после финализации — очередь ссылок: пост-действия над памятью объекта; основа Cleaner — замена finalize: register объект+очиститель, вызывается когда объект собран — освобождение native-ресурсов (DirectByteBuffer); порядок: phantom-референс в ReferenceQueue, объект уже мёртв — чистится нативная часть). ReferenceQueue — уведомления о сборке: poll/remove. Практика: SoftReference-кэш — антипаттерн сегодня (паузы под давлением памяти, непредсказуемость hit-rate) — явные лимиты лучше; WeakHashMap для канонических соответствий (объект→метаданные, не мешая GC объекта); Phantom/Cleaner — когда обёртка над нативным ресурсом, но try-with-resources остаётся первичным (Cleaner — страховка от забывчивости, не основной механизм). Внутренности: reference-processing в GC — special handling, KeepAlive semantics; -Djdk.lang.ref.finalize... туманные детали финализации устарели — не углубляться без нужды.', 'Чем Soft отличается от Weak по моменту сборки и почему Soft-кэш сегодня антипаттерн? Что чистит Cleaner (phantom-очередь) и почему он замена finalize? Куда смотрит WeakHashMap и что происходит со значением?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'HTTP-кеширование: ETag, Cache-Control, conditional requests — сервер+клиент экономят трафик?', 'Cache-Control (запрос/ответ): max-age=N (свежесть), no-cache (кешировать, но валидировать), no-store (не кешировать — секреты), private (только браузер, не CDN), public, s-maxage (для CDN), stale-while-revalidate (отдать несвежее, обновить фоном), immutable (фичу не изменится — файлы с хешем в имени: main.a1b2.js + max-age=31536000, immutable — вечный кеш статических ассетов). Валидаторы: ETag (сильный/слабый W/) — версия ресурса; Last-Modified — время; conditional GET: If-None-Match: <etag> / If-Modified-Since → 304 Not Modified (без тела — экономия трафика, но RTT остаётся). Паттерн SPA: index.html — no-cache (всегда свежий — маленький), hashed-ассеты — immutable+год; API: данные — private, max-age=0 или короткий + ETag (дешёвый 304 через if-match: etag = hash ответа: shallowETag Spring — автоматически). Кэш-иерархия: браузер → proxy/CDN → origin: no-cache+vary (Accept-Encoding, Authorization) — чтобы CDN не склеивал авторизованных с анонимами. Spring: @CacheControl, ShallowEtagHeaderFilter (hash ответа — слабый etag: пересчёт ответа всё равно выполняется, экономится только трафик; сильный — инкрементные версии в приложении). Ловушки: ETag с внутренним состоянием (hash с sessionId — никогда не совпадёт), GET-параметры варьирование (Vary: Accept-Language для локализованных ответов).', 'Чем no-cache отличается от no-store и что делает stale-while-revalidate? Почему hashed-ассеты кешируют на год с immutable, а index.html — никогда? Что экономит 304-ответ по сравнению с полным — трафик или время?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'JSON-границы: Jackson аннотации, view, версии — управление сериализей?', 'Core-аннотации: @JsonProperty (имя), @JsonIgnore (поле), @JsonFormat (даты/числа: shape STRING, pattern), @JsonInclude(NON_NULL) — не писать null (чистые ответы API), @JsonUnwrapped (флаттенить вложенный), @JsonAlias (несколько имён при чтении — миграция клиентов), @JsonCreator/@JsonProperty (конструктор-десериализация для immutable), @JsonValue (enum-сериализация значением), @JsonEnumDefaultValue. Полиморфизм: @JsonTypeInfo(use=NAME, property="type") + @JsonSubTypes — typeId в JSON (безопаснее всего класса: use=CLASS — сериализация className — уязвимость полиморфной десериализации!). @JsonView(Views.Public.class) — один класс, разные проекции по контексту: контроллер @JsonView(Public) — пароли не утекут; конвенция — иерархия Views.Public extends Base. @JsonManagedReference/@JsonBackReference —双向 связи без рекурсии (parent-child), @JsonIdentityInfo — циклы по id. Настройка глобально: ObjectMapper бин (Jackson2ObjectMapperBuilderCustomizer): FAIL_ON_UNKNOWN_PROPERTIES=false, даты ISO, naming SNAKE_CASE, mixins (сторонний класс без аннотаций — rule: @JsonIgnore в отдельном mixin-классе). Версионирование ответов: v1/v2 DTO-классы (не view) при ломающих изменениях; Spring-сериализация через message converters — один маппер на всё приложение (валидация/спека одинаковые). Spring Boot: spring.jackson.* свойства — конфиг без кода.', 'Чем @JsonView отличается от отдельных DTO на каждую версию? Почему use=CLASS в JsonTypeInfo — риск и что вместо? Как изменить сериализацию класса без правки его кода?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Retry-паттерны в распределённых системах: куда ретраить, а куда — очередь?', 'Ретрай уместен: transient-ошибки (таймаут, connection reset, 503, 429 с Retry-After), идемпотентная операция; exponential backoff + jitter (синхронные ретраи без jitter — thundering herd после сбоя), бюджет попыток (2-3 — не 10), timeout на попытку < общий бюджет. Ретрай неуместен: бизнес-ошибки (400 insufficient funds — повтор тот же), non-idempotent без ключа идемпотентности, глубокая вложенность ретраев (retry в retry — мультипликация нагрузки: 3×3×3=27 запросов вниз при сбое底层), исчерпание ресурсов (пул занят — ретраи усугубляют), уже длительные операции (retry с тем же таймаутом = затык вызывающего). Альтернатива ретраю в синхроне: асинхронная очередь — сбойный вызов → отложить (outbox-событие/Kafka) → повтор фоново с backoff; пользователь не ждёт (UX), нагрузка размазана, retry-политика в одном месте (dead-letter после N). Паттерн combined: синхронный quick-retry (сеть мигнула) + асинхронный recovery (система лежит) — level-based: 2 попытки сразу, дальше очередь. Circuit breaker поверх — не ретраить в открытом состоянии (_fail fast, дать восстановиться). Идемпотентность обязательна при любом повторе — ключ операций. Spring Retry/Resilience4j — декларативно; Kafka-retry-топики (spring @RetryableTopic: backoff+DLT) — для событий.', 'Почему вложенные ретраи умножают нагрузку и как решить? Когда асинхронная очередь лучше синхронного ретрая по UX и устойчивости? Что делает @RetryableTopic и куда попадает сообщение после истощения попыток?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Собеседование за еду: вопросы про Agile/Scrum-процессы — что отвечать инженеру?', 'Спрашивают: «как работаете в спринтах?», «что делаете когда задача не влезает в спринт?», «как относитесь к ретро/планированию?». Смысл — ищут зрелого участника процесса, не свидетеля. Отвечать по сути: оценка задачи — декомпозиция до понятных кусков (≤1-2 дня), неизвестное — спайк с таймбоксом (исследование отдельно от реализации); не влезает — режем scope (MVP-часть сейчас, остальное следующим), не «задвинемdeadline»; планирование — команда считает, не лид назначает (commitment vs назначение); daily — синхронизация по блокерам (не отчёт), 2 минуты на человека; story points/кол-во — инструменты, не догма: фокус-фактор и стабильность скорости важнее точных оценок. Ретро: конкретика → actions с владельцем (не «улучшить коммуникацию», а «ввести шаблон ПР — Саша, до пятницы»). Definition of Done: тесты+ревью+докуметация в задаче. Инженерная позиция: предлагать улучшения процесса через ретро (не тихое страдание), защищать качество в оценках (тесты — часть задачи, не отдельная «потом»). Red flags ответов: «скарам-мастер заставляет», «не знаю, мы просто кодим» — отсутствие вовлечённости.', 'Что делать с задачей, которая не влезает в спринт — растягивать или резать? Как выглядит хорошее ретро-action и чем оно плохое? Почему тесты в оценке задачи — часть или отдельная работа?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Отказ и переговоры по офферу: вилка, альтернативы, отказы — как вести себя достойно?', 'Переговоры: называть ожидания — диапазон с нижней границей = приемлемой (не «сколько дадите»); вилка в вакансии — ориентироваться на верхнюю треть при релевантном опыте; аргументы — рынок (предложения-альтернативы), уникальный стек/домен, текущая компенсация+индексация; всегда вежливое «есть другие предложения, вы приоритетны» — без блефа (проверяют). Тестовый период/испытательный — оклад полный по ТК. Отказ работодателя: «мы выбрали другого» — спросить фидбек (HR передаст, если вежливо попросить) —)data для следующих; не оспаривать решение. Отказ работодателю: поблагодарить, назвать причину нейтрально (выбрал предложение ближе к целевому стеку), дверь открытой (maybe через год), не гейтить и не пропадать — индустрия узкая. Два оффера: брать время на решение (это норма — 2-3 дня), взвесить: деньги vs рост vs команда vs стабильность; отказывать второму честно и быстро (не держать на скамейке). Красные флаги в оффере: «оформим как самозанятого» без объяснений (нет отпуска/больничных), отсрочка индексации устная, опционы «позже обсудим» письменно не зафиксированы. Устные обещания → просить в оффер-письмо.', 'Как назвать зарплатные ожидания и почему диапазон с нижней границей лучше «сколько дадите»? Как правильно отказать работодателю, не сжигая мосты? Какие пункты оффера обязаны быть письменными?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'JIT глубже: инлайнинг-стратегия, профили, CHA — почему «простой» код вдруг тормозит?', 'Инлайнинг: методы до FreqInlineSize (325 байт байткода) горячие / MaxInlineSize (35) холодные; маленькие методы инлайнятся, крупные — нет: однострочный делегат с generic-обёрткой может быть за порогом из-за бриджа/генериков — вызов не инлайнится, конвейер оптимизаций обрывается (нет межпроцедурного анализа). Профили: C1 собирает (типы в call-сайтах, ветки), C2 спекулирует по ним; типовой профиль искажённый (прогрев маленький/данные однообразные) → спекуляция ошибочна → деоптимизация → пере-компиляция (провал производительности в проде, которого не было в тесте с другими данными). CHA (class hierarchy analysis): девиртуализация вызова, если иерархия закрыта на момент компиляции; загрузка нового подкласса инвалидирует — deopt. Причины «простой, но тормозит»: (1) lambda-цепочки без инлайнинга (мелкие wrapper-методы + megamorphic call-site: >2 реализций интерфейса в одном месте — inline-кэш не работает); (2) ветвление с редкими, но тяжёлыми путями; (3) аллокации не скалярно замещённые (escape за метод); (4) границы модулей (method handle invoke); (5) JVMTI-агент/флаги отключившие оптимизацию. Диагностика: -XX:+PrintInlining (что НЕ инлайнится и почему: hot method too big), JFR execution samples, async-profiler; JITWatch визуализация. Лечение: уменьшить горячие методы, стабилизировать call-site (моно/биморфный), final/sealed подсказки, @HotSpotIntrinsicCandidate не трогать — intrinsic уже.', 'Что такое megamorphic call-site и как он убивает инлайнинг? Почему профиль прогрева с однотипными данными приводит к прод-деоптимизации? Как прочитать «hot method too big» в PrintInlining?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Compressed oops, heap-границы, object alignment — почему 32GB куча хуже 31?', 'Compressed oops: ссылки сжимаются до 32 бит (при куче ≤32GB: сдвиг 3 бита — 8-byte alignment объектов: 32bit-указатель адресует 4G × 8 байт = 32GB); >32GB — ссылки 64-бит: +8 байт на каждое поле-ссылку, размер объектов растёт ~на 10-20%, кэш-плотность падает, GC работает медленнее — 40GB куча может работать ХУЖЕ 31GB. Варианты: heap ≤31GB с compressed oops, или heap ≥48GB+ где выгода объёма перевешивает; CheckCompressedOops. Object alignment: 8 байт дефолт (ObjectAlignmentInBytes=16 удваивает адресуемое — редко, влияет на все размеры объектов). GC-аргументы: heap regions G1 при маленькой куче <6GB неэффективны; humongous-порог зависит от региона; NIO direct memory — вне кучи (MaxDirectMemorySize) — сумма с heap в лимит пода. Class compression: -XX:+UseCompressedClassPointers (аналогично для class-указателей, CCП boundary с compressed class space metaspace). Практика: контейнер 4GB — heap 3GB (Xmx3072m: остальное metaspace+stacks+code+direct); переход 31→36GB нелинеен — тестировать; JVM всегда показывает «GC heap」 vs RSS в мониторинге контейнера — следить на OOMKill. Compressed oops «выключается» молча при Xmx>32g — осознавать при росте куч.', 'Почему именно 32GB граница для compressed oops и что меняется после неё? Как ObjectAlignmentInBytes=16 расширяет адресуемое пространство? Как правильно поделить 4GB лимит пода между heap и остальным?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Реактивные транзакции: R2DBC, транзакциональность в WebFlux — как не потерять данные?', 'R2DBC — реактивный драйвер БД (PostgreSQL/MySQL): неблокирующее соединение, пулы (r2dbc-pool), SQL поверх reactive-стримов; нет общего с JDBC: JPA не работает (Hibernate Reactive — отдельный продукт, зрелость ниже). Транзакции в реактиве: @Transactional работает на reactive-цепочках (ReactiveTransactionManager: begin/commit/rollback через цепочку сигналов) — НО: транзакционный контекст передаётся через Reactor Context, НЕ ThreadLocal — переключение потоков внутри цепочки безопасно, а вот код, вытащивший зависимость через ThreadLocal (legacy-сервис) — выпадает из транзакции молча. Правила: (1) вся цепочка одной транзакции — монолитна (flatMap внутри, не внешние подписки); (2) блокирующие вызовы (JDBC legacy) в цепочке — нетранзакционны + блокируют event-loop; (3) транзакция живёт дольше подписки — длинные цепочки держат коннект; (4) ошибка в цепочке — rollback через сигнал error; retry-оператор внутрь транзакции — осторожно (retry повторит side-effects). Outbox-паттерн в реактиве: запись события в той же reactive-транзакции → публикация после коммита (TransactionSynchronization reactive-вариант). Отладка: Hooks.onOperatorDebug (сборка стека — дорого, только debug), checkpoint() в цепочке, logging DoOnNext. Выбор: R2DBC оправдан в чисто реактивном стеке; смешанный (JDBC+WebFlux) — главный источник «потерянных» транзакций.', 'Почему ThreadLocal-транзакция не работает в реактивной цепочке и что вместо? Что происходит с транзакцией при retry-операторе внутри неё? Когда смешанный стек JDBC+WebFlux приводит к потере данных?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Планировщик запросов PG: статистика, cost model, generic vs custom plans — почему «вдруг» стало медленно?', 'Планировщик строит оценку стоимости из статистики (pg_statistic: гистограммы, MCV — most common values, корреляция, доля null): ANALYZE обновляет; autovacuum — авто (порог по долям изменений). Деградация «вдруг»: (1) статистика устарела (массовая загрузка данных → распределение изменилось → план по старой гистограмме: rows off на порядки); (2) data skew: параметр меняется — generic plan (prepared statement, 5+ исполнений — план без значений параметров) хорош для одних значений и катастрофичен для редких: custom vs generic переключение по average cost — флип-флоп; (3) correlated columns: WHERE a=1 AND b=2 — независимость столбцов в модели → huge misestimate: CREATE STATISTICS (dependencies) лечит; (4) план-кэш poisoned: перезагрузка кэша — другой план. Диагностика: EXPLAIN (анализ фактических rows vs оценка), pg_stat_statements (top по total_time, регресс), auto_explain (лог медленных с планами, thresholds), track_io_timing. Управление: extensions pg_hint_plan (принуждение), enable_*=off per-session (диагностика), planner constants: random_page_cost (SSD → 1.1 против 4 дефолтной — меняет выбор index scan), effective_cache_size, work_mem (сортировки в памяти vs spill). Generic-план: plan_cache_mode=force_custom_plan для skewed-запросов; JDBC prepared-параметры и batch — баланс.', 'Что делает статистика MCV и гистограммы при data skew? Почему prepared statement с generic plan то быстрый, то внезапно медленный? Как random_page_cost влияет на выбор index scan?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'PostgreSQL: оконные функции, CTE, lateral — аналитика без выгрузки?', 'Оконные функции: агрегат ПО ОКНУ без схлопывания строк: SUM(amount) OVER (PARTITION BY user_id ORDER BY created_at) — нарастающий итог; ROW_NUMBER/RANK/DENSE_RANK (топ-N в группе: rn=1), LAG/LEAD (предыдущая/следующая строка — дельты), FIRST_VALUE, NTILE; frame: ROWS BETWEEN 5 PRECEDING AND CURRENT ROW — скользящее среднее; оконные в SELECT после WHERE — фильтр по оконному значению через подзапрос/QUALIFY-аналог. CTE: WITH — именованные подзапросы: читаемость, рекурсия (WITH RECURSIVE — деревья: category → parents, org-структуры); до PG 12 CTE — оптимизационный барьер (материализация), с 12 — инлайнятся (MATERIALIZED keyword принудительно). LATERAL join — подзапрос с доступом к колонкам предыдущей таблицы: топ-3 заказа каждого клиента (join lateral select ... order by ... limit 3) — классика; cross apply-аналог MSSQL; циклы по массивам/генерациям (generate_series + lateral). Практика: отчёты «нарастайка по месяцам» — окно + date_trunc; «последнее событие юзера» — distinct on (user_id) order by created_at desc (PG-специфика — проще окна); медианы: percentile_cont (агрегат, не окно). Производительность: окна требуют сортировки по partition/order — индекс под ключ окна ускоряет; большой frame в памяти — work_mem.', 'Чем ROW_NUMBER отличается от RANK и когда какой для топ-N? Что делает LATERAL и какую задачу deduplicate-join он решает? Как получить нарастающий итог и что для него индексировать?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kotlin: infix, operator overloading, DSL — когда синтаксический сахар оправдан?', 'infix fun: a to b (Pair), x until y — читаемость парных операций: infix fun Int.percentOf(total: Int) — 20 percentOf 300; злоупотребление — криптограммы (20 pct 300 — что это?). Operator overloading: plus/minus/get/set/contains/compareTo/invoke/rangeTo — коллекции a[i], string in list уже через операторы; свои: Vector + Vector читаемо; дата ± Duration (LocalDate.plus) — идиоматично; анти: побочные эффекты в операторах (a + b пишет в БД — нет), неочевидные типы (File + File — конкатенация путей? содержимого?). DSL-строительство: лямбды с receiver + infix + operators: buildString { append() }, Gradle Kotlin DSL, Ktor routing (route("/api") { get("/users") {...} }), kotlinx.html; рецепт DSL: типизированные билдеры (HTML: html { body { p("text") } }) — приём type-safe builders; intermediate. Оправданность: предметная область с естественной нотацией (математика, запросы, конфиг-деревья) — сахар повышает читаемость; generic-код без доменной семантики — сахар прячет смысл. Соглашения: operator должен соответствовать интуиции (+ не ассоциируется с записью в файл); документировать нестандартное. Groovy-мир GraphQL/Gradle показывает потолок DSL-подхода — Kotlin строит статически-типизированные DSL безопаснее.', 'Что такое лямбда с receiver и почему она — основа Kotlin DSL? Когда operator overloading повышает, а когда убивает читаемость? Назовите два примера DSL из stdlib/экосистемы и их ключевой приём?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Structured concurrency и параллельные вызовы в Spring-сервисе — практические рецепты?', 'Рецепт «N независимых вызовов параллельно»: (1) CompletableFuture: оба = CompletableFuture.supplyAsync(a, pool).thenCombine(supplyAsync(b, pool), ...); все = allOf(cf1..cfN).thenApply(...) — извлечение результатов join-ами; собственный пул обязательно; (2) Virtual threads (Java 21): try (var ex = Executors.newVirtualThreadPerTaskExecutor()) { var f1 = ex.submit(() -> clientA()); ... } — структурно: close() ждёт всех; (3) Kotlin: coroutineScope { async { a() }; async { b() } }.map { it.await() } — отмена при первом сбое автоматически. Таймауты: orTimeout у CF / withTimeout у корутин / Future.get(timeout) у executor; частичная деградация: exceptionally(fallback) — один источник упал → дефолт (кэш), не весь экран. Кэширование параллельных вызовов: Caffeine AsyncLoadingCache — get() всех, недостающие грузятся пачкой. Ошибки: все падают если один (thenCombine — при сбое любой) — разрывать: recover каждого до объединения. Блокирующий источник в параллельном блоке — считать: пул IO достаточного размера (или VT — не важно). Паттерн fan-out/fan-in: разбить большой список на чанки → parallel обработка каждого → собрать; контрольConcurrency: Semaphore (VT: Semaphore между виртуальными — работает). Наблюдаемость: каждый вызов — таймер с тегом источника; общий latency = max(параллельных) — трассировка показывает ожидание. Отмена: пользователь ушёл — cancel(true) фичей (Spring MVC request-отмена → interceptor cancellation).', 'Чем структурная параллель корутин отличается от allOf у CompletableFuture при сбое одного вызова? Как сделать частичную деградацию экрана при падении одного источника? Почему с virtual threads не нужно думать о размере пула вызовов?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Тестирование REST: MockMvc vs WebTestClient vs TestRestTemplate — что выбрать?', 'MockMvc: сервер не поднимается — DispatcherServlet вызывается напрямую (fast): для @WebMvcTest slice-тестов контроллеров (сервисы @MockBean); синтаксис: perform(get(...)).andExpect(status().isOk()).andExpect(jsonPath("$.name").value("X")); фильтры (security) подключаются — полная web-цепочка; ограничения: нет реальной сети/сериализации на транспортном уровне (легко пропустить проблему границ — например заголовок кодировки). TestRestTemplate: реальный HTTP на RANDOM_PORT (@SpringBootTest webEnvironment) — полный стек: сериализация через Jackson реальный, таймауты, фильтры — честный интеграционный тест; медленнее; rest-assured поверх — BDD-синтаксис given/when/then читаемее. WebTestClient: изначально для WebFlux, работает и с MVC (mock-режим через bindToApplicationContext) — fluent-цепочки, стриминг, SSE; шаг в реактивный мир. Выбор: контроллер-логика (валидация, маппинг, статусы) — MockMvc slice (быстро, изолированно); полный сценарий (security + сериализация + реальный конфиг) — RANDOM_PORT + TestRestTemplate; реактивный стек — WebTestClient. Практика: JSON-схема ответа стабом WireMock при внешних зависимостях; testcontainers для БД в интеграционных; contract-test фиксирует форму (Pact). Классика ошибок: MockMvc тест зелёный, прод падает — потому что slice не покрыл security-конфиг/фильтр — критичное проверять на RANDOM_PORT.', 'Почему MockMvc быстрее и что он НЕ проверяет по сравнению с RANDOM_PORT? В чём сила slice-теста @WebMvcTest по изоляции? Когда TestRestTemplate обязателен несмотря на медленность?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Производительность БД-доступа Spring: JdbcTemplate, batch, fetchSize — когда JPA лишний?', 'JPA удобен доменом, но добавляет накладные: dirty checking (снапшоты сущностей — память на больших контекстах), кэш 1-уровня, прокси ленивости, синтез SQL; тяжёлые отчёты/ETL — JdbcTemplate/NamedParameterJdbcTemplate напрямую: без сущностей, ручной маппинг (DataClassRowMapper на record/Data class — быстро и просто), batchUpdate (список аргументов — один round-trip на батч), fetchSize (postgres: без fetchSize тянет ВСЁ в память! statement.setFetchSize(500) — курсорный режим, autocommit off), rewriteBatchedStatements (MySQL) / reWriteBatchedInserts (PG JDBC — множественные VALUES). Практические числа: вставка 100k строк: saveAll JPA = N вставок (без батча при IDENTITY!) vs JdbcTemplate.batchUpdate по 1000 — разница в 10-50 раз; чтение 1M строк: JPA-сущности (managed, dirty-костs) vs stream-проекция/JdbcTemplate RowMapper — в 3-5 раз память и скорость. Смешанный подход: домен — JPA, массовые операции — JdbcTemplate/@Query(nativeQuery) в той же транзакции; SPI: оба через один DataSource — транзакционность общая. StatelessSession Hibernate — альтернатива (без dirty-check) для потоковой обработки. Large result set: стриминг через cursor + обработка чанками, коммит партициями (не одна транзакция на миллион — undo-log растёт).', 'Почему saveAll без батча при IDENTITY делает N вставок и как переписать на batch? Что делает fetchSize=500 против дефолта в PostgreSQL JDBC? Когда оправдан StatelessSession против JdbcTemplate?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kafka Streams против обычного consumer: stateful processing — где граница?', 'Kafka Streams: встроенное состояние (RocksDB + changelog-тема: восстановление после рестарта), оконные агрегации, join-ы потоков, exactly-once processing v2; DSL (KStream/KTable) + Processor API (низкоуровневый); интерактивные запросы (IQ): сторе читается другим сервисом — материализованные представления без внешней БД. Обычный consumer (@KafkaListener): statelessness вне БД — состояние в своей Postgres/Redis: полная свобода логики (транзакции с БД через тот же datasource!), ноWindowState/восстановление/масштабирование — сами. Граница выбора: (1) чистые трансформации и обогащения потоков без сложного состояния — Streams удобен, развертывание просто (приложение = Streams-инстанс); (2) агрегации/окна/sessionization — Streams почти безальтернативен (своё = недели работы: watermark-и, recovery); (3) результат обязан попадать в реляционную БД атомарно с другими записями — consumer + транзакция БД (Streams пишет в Kafka — для БД нужен sink-слой, или interactive queries с консистентностью чтения другой); (4) существующая логика на Spring-стеке — @KafkaListener переиспользует сервисы/транзакции. Масштабирование: Streams — по партициям (instance scaling автоматом через rebalance), стейт-сторы переезжают (state restoration через changelog — минуты); consumer с внешним состоянием — состояние шардируется ключом по БД. Пограничный кейс: Streams с external-state (GlobalKTable — глобальная копия справочника на каждом инстансе) — компромисс read-only справочников.', 'Что даёт changelog-тема для восстановления стейта Streams? Когда агрегации руками на consumer + БД выгоднее Streams? Что такое GlobalKTable и для каких данных она создана?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Docker-compose для локальной разработки:profiles, healthchecks,depends_on — зрелый dev-стек?', 'Compose-файл — воспроизводимое окружение команды: postgres+backend+frontend+broker одной командой. Зрелость: (1) healthchecks: test: ["CMD-SHELL", "pg_isready -U $$POSTGRES_USER"], interval/timeout/retries — готовность по факту; (2) depends_on: condition: service_healthy — порядок старта без sleep-хаков (ждёт healthcheck); (3) profiles: docker compose --profile kafka up — опциональные сервисы (лёгкий дефолт, полные локально); (4) volumes: named (pg-data) + bind для кода (hot-reload); (5) env: .env-файл (compose подставляет ${VAR}), environment в сервисе; (6) resources: limits локально редко, cpus для «прод-похожести»; (7) networks: изоляция стека, aliases (db как hostname). Антипаттерны: sleep 10 в entrypoint-скриптах (races: 10 сек не всегда хватает — healthcheck честно), latest-теги (у соседей другие версии — «у меня работает»), общая external сеть без нужды, секреты в compose-файле коммиченные (env_file в .gitignore, примеры в .example). Dev-режим: только инфраструктура в compose (БД, брокер, redis), приложения — IDE (debugger!) — гибрид; полная композиция — для e2e/демо. Override-файлы: docker-compose.override.yml (авто) — локальные твики поверх базового, docker-compose.prod.yml — прод-вариант (никогда без review). Port-менеджмент: локальные порты контейнеров ≠ стандартные (5432 занят локальной PG — мапить 55432:5432) — фиксировать в README.', 'Чем condition: service_healthy лучше sleep в entrypoint? Зачем profiles в dev-композе и как их включают? Почему приложения часто запускают в IDE поверх compose-инфраструктуры?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Собеседование: рассказ о pet-проекте — как за 3 минуты заинтересовать?', 'Структура «проблема → решение → технические решения → результат»: (1) проблема личная/рыночная в одном предложении («готовясь к собесам, я держал вопросы в заметках — искал систему с повторениями — не нашёл подходящую — сделал»); (2) что делает (функциональность в 2-3 пунктах: каталог вопросов с эталонами, интервальные повторения SM-2, Telegram-бот); (3) технические решения с обоснованием (стек: Kotlin/Spring Boot + Next.js; «почему SM-2, а не просто даты» — показать осознанный выбор; CI с тестами на Testcontainers — культура качества); (4) живой результат (пользователи/коммиты/выложен на домен — реальное использование сильнее «учебного» статуса). Что оценивают: способность довести до релиза (завершённость — главный сигнал), осознанность выбора (не «взял модное», а «решил задачу Х через Y потому что Z»), глубина хотя бы в одном месте (алгоритм SM-2, авторизация через Telegram — уметь нырнуть в детали по вопросу). Красные флаги: «скачал курс, повторяю», TODO-проект без README, «планирую сделать» вместо сделанного. Подготовка: README как витрина (проблема, скриншоты, как запустить одной командой, архитектура-схема); демо-стенд или видео 2 мин; ссылки на код и живой сайт. Ответ на «что бы улучшил» — честный бэклог (показывает зрелость, а не «всё идеально»).', 'Из каких четырёх блоков состоит сильный рассказ о пет-проекте? Что сильнее всего сигнализирует работодателю в любительском проекте? Как отвечать на вопрос «что бы ты улучшил»?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'On-call зрелость: дежурства, алерты качество, инцидент-менеджмент — как выживать?', 'Личный алгоритм дежурства: (1) страница → acknowledge (взял), (2) triage 5 минут: severity (прод лежит vs деградация vs ложный), blast radius (все юзеры/сегмент), (3) mitigate first, fix later: rollback, фичефлаг off, scale-up, failover — уменьшить ущерб, не diagnose-час; (4) communicate: статус-канал, «изучаю» → «причина X, восстанавливаю» → «восстановлено в HH:MM»; (5) после — постмортем blameless (timeline, root cause, action items с дедлайнами и владельцами). Качество алертов (антиспам): каждый page — «действие человеком сейчас» (иначе — ticket); симптомные алерты (error rate, latency) лучше причинных (CPU 90% — и что?); flapping — hysteresis (for/resolved дифференциал), дедупликация по группам; «no incidents»-неделя ≠ хорошая неделя: 20 pages/день — система алертов больна, не сервис здоров. Runbooks: к каждому page-алерту ссылка: симптомы → диагностика → действия (даже «перезапусти X если Y» экономит дежурному 30 минут ночи). Организация: ротация с компенсацией, escalation policy (не ответил 5 мин → следующий), handoff-документ (текущие горящие темы). Личные: телефон не беззвучный на дежурстве; laptop+интернет доступ проверен; знания: хоть раз порепетируй сценарий (game day) — стресс реального инцидента не место для первого знакомства с runbook.', 'Что означает «mitigate first, fix later» и почему диагностика — второй шаг? Чем симптомные алерты лучше причинных? Что должно быть в runbook и зачем проводить game days?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Долгоживущие данные: мягкое удаление, архивирование, GDPR-стиль — дизайн жизненного цикла?', 'Мягкое удаление (deleted_at timestamp): восстановимо, аудит; цена: ВСЕ запросы обязаны фильтровать deleted_at IS NULL (забытый фильтр = утечка данных!), уникальные констрейнты конфликтуют (удалённый email блокирует повторную регистрацию — partial unique index WHERE deleted_at IS NULL); производительность: таблица пухнет, индексы растут — партиционирование по времени + архив. Архивирование: горячие данные (90 дней) в основной таблице, холодные — партиции/отдельная archive-таблица/объектное хранилище (S3: parquet-выгрузки — аналитика дешевле); DROP старой партиции — дешёвое удаление; доступ к архиву — отдельный API/отчёты (не в прод-пути). Право на забвение/GDPR: персональные данные (PII) — идентификация полей (карта данных: где что лежит — БД, логи, бэкапы!), удаление по запросу: anonymization (перезапись PII-полей NULL/маской — сохраняет статистическую ценность строки), каскады (токены, вложения, поисковые индексы, аналитика); логи с PII — TTL + маскирование при записи (не «удалим потом» — не удалятся из бэкапов). Практики: retention-политики по типам данных (заказы — 5 лет законодательно, сессии — 30 дней), бэкапы — retention ограничен тем же окном где возможно; событие UserDeleted в шине для каскадной чистки подписчиков. Тестирование: удаление юзера удаляет всё (e2e-сценарий) — счётчик артефактов = 0.', 'Какие две проблемы создаёт мягкое удаление и как partial index решает одну из них? Что делать с PII в логах и бэкапах при праве на забвение? Чем anonymization отличается от удаления строки и когда выбирать?' from categories where slug = 'db-migrations';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Масштабирование команды разработки: ревью-культура, PR-размер, trunk-based — поток изменений?', 'Ревью-культура: PR ≤400 строк диффа (исследования Google: выше — качество ревью падает), описание PR: что+зачем+как тестировал, скриншоты UI; ревьюер: 24ч SLA (не держим), конкретика комментариев (не «плохо», а «здесь гонка: поток A читает до записи»), различать blocking vs nit (префиксы); автор: сам прогуляйся по диффу перед отправкой (self-review), отвечай на каждый коммент (fixed/объяснил/спор — офлайн). Branching: trunk-based (короткоживущие ветки <2 дней, мерж в main постоянно) vs git-flow (долгие фичи — боль интеграций): современный дефолт — trunk-based + фичефлаги (скрывать незаконченное) + merge-queue (линейная история CI-гарантий); длинные ветки = интеграционный ад (неделя ребейз-конфликтов). Мерж-стратегии: squash (одна логическая единица в историю) vs merge-commit (сохранение веток — релизные); rebase-команды: «не пушить в общие» правило. Масштабирование: CODEOWNERS (автоматический ревьюер по путям), авто-чеки до людей (линтер/тесты/формат — роботом, не глазами), шаблоны PR/issue, архитектурные RFC для больших изменений (до кода!). Поток метрик: lead time (коммит→прод), время ревью (по прошлому пункту), PR-размер распределение — дашборд команды.', 'Почему PR больше 400 строк ревьюится хуже и как это лечить? Как trunk-based + фичефлаги заменяют долгие фича-ветки? Какие три вещи автоматизируют до людей в ревью?' from categories where slug = 'ci-cd';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'SSE и WebSocket: серверный push — выбор транспорта и Spring-реализация?', 'SSE (Server-Sent Events): однонаправленный сервер→клиент поверх HTTP: Content-Type: text/event-stream, формат data: ...\n\n, авто-reconnect браузером (Last-Event-ID header — ресюм с последнего события), события id/event-типы; идеально: уведомления, прогресс, live-обновления дашбордов; ограничения: HTTP/1.1 — 6 соединений на домен (браузер; HTTP/2 multiplexing решает), только текст (base64 для бинарного), нельзя клиент→сервер. WebSocket: полнодуплексный бинарный/текст протокол после upgrade-рукопожатия: чаты, игры, collaborative-редактирование (быстрые двусторонние потоки); сложнее инфраструктура (прокси/LB таймауты, sticky sessions при масштабе), собственная переподключение/пинг-понг логика. Spring: SSE — SseEmitter (MVC, возврат из контроллера, emitter.send(event)) / Flux<ServerSentEvent> (WebFlux); WebSocket — @MessageMapping + STOMP (spring-boot-starter-websocket, брокер simple/external RabbitMQ для кластера, subscribe-префиксы); raw WebSocketHandler — без STOMP-ов. Auth: SSE — обычные заголовки/куки (HTTP!), WS — токен в query/первом сообщении (заголовки не всегда доступны браузером). Масштаб: SSE — соединение держится (VT/реактивные делают дёшево; на потоках — пул упрётся); WS-кластер — брокер сообщений или pub/sub Redis-шина. Выбор 90% веб-приложений: SSE достаточно (клиенту слать можно обычным POST).', 'Чем SSE отличается от WebSocket по направлению и протоколу? Что даёт Last-Event-ID и встроенный reconnect SSE? Почему аутентификация WebSocket сложнее и как передают токен?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Scheduling в распределённом виде: Quartz, dbos, temporal — когда cron''а мало?', 'Прогрессия сложности: (1) @Scheduled — один инстанс, без персистентности: рестарт = потеря срабатываний; (2) ShedLock — кластер, single-execution, без истории/misfire; (3) Quartz clustered: persistence (JDBC-таблицы), misfire-политики (fire-now/once/never), история, cron/interval, but API 2000-х и конфиги громоздки; (4) workflow-оркестраторы (Temporal, DBOS, Camunda): durable execution — состояние шагов переживает рестарты, ретраи/таймеры/саги декларативно, визуализация прогресса; код как оркестрация: @WorkflowInterface, activity-вызовы, workflow-код выполняется годами (сону может спать месяцами — фреймворк восстанавливает). Когда что: ночные регламент-задачи без строгости — ShedLock достаточно; корпоративный шедулер с UI/историей/мисфайрами — Quartz; длинные бизнес-процессы (онбординг клиента: 12 шагов с ожиданием ответов дней, компенсации при сбоях) — Temporal: императивный код читаемее саги на событиях; обработка пачек данных с чекпоинтами — тоже workflow (restart с места). Антипаттерн: свой «workflow-движок» на таблице статусов + cron-сканирование — 80% Temporal-функций, 5x багов. Spring-интеграции: temporal-spring-boot-starter (activity/workflow beans, worker-пулы), Quartz spring-boot-starter-quartz (jdbc store auto).', 'Чем durable execution Temporal отличается от ShedLock по переживаемости сбоев? Какие задачи решает Quartz и где его границы? Почему свой движок на таблице статусов — антипаттерн?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Чем record отличается от final-класса с Lombok @Value и когда record проигрывает?', 'record — синтаксис Java 16+ для прозрачного носителя данных: канонический конструктор, приватные final-поля, акцессоры name(), equals/hashCode/toString из компонент — всё без boilerplate. Отличия от @Value-класса: record нельзя наследовать (неявно final) и от него нельзя наследоваться, нельзя менять поля вообще, зато компактный конструктор позволяет валидацию, а канонический — нормализацию (trim, uppercase). Проигрывает record, когда нужны: мутабельность (builder + setter), JPA-сущность (Hibernate требует пустой конструктор и проксирование — с Java 16 работает с записями частично, но associations ломаются), наследование иерархии DTO, ленивые вычисляемые поля (кэш в компоненте невозможен — обход через static-метод). @Value гибче: наследование, кастомные equals, частичная мутабельность. Правило: чистый иммутабельный DTO на границе — record; всё сложнее — класс.', 'Можно ли в record добавить ещё один конструктор и что он обязан вызвать? Почему JPA-сущность не делают record? Как в record запретить null-компоненту без аннотаций?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Memory model Java: happens-before, volatile, final-поля — как гарантировать видимость без блокировок?', 'JMM определяет частичный порядок happens-before: запись A happens-before чтение B, тогда B видит эффекты A. Пары HB: program order в одном потоке; разблокировка монитора HB следующий захват того же монитора; запись volatile HB любое следующее чтение этого поля; запись final-поля в конструкторе HB публикацию ссылки (safe publication); start потока HB первый оператор; запись в CompletableFuture HB thenApply-цепочку. volatile гарантирует видимость и порядок (запрет переупорядочивания через барьеры), но НЕ атомарность составных операций (count++ на volatile — гонка, нужен AtomicXX или sync). final-поле, записанное в конструкторе без утечки this, неизменно и видимо всем без синхронизации — фундамент иммутабельности. Unsafe publication (публикация через незащищённое поле) даёт partial construction: другой поток видит объект с null-полями. Data race — два конфликующих доступа без HB — JMM разрешает любые исходы, включая torn long/double (без volatile 64-битные чтения могут рваться до Java 9 строгости). Лечение: immutable + final, volatile для флагов, Atomic для счётчиков, блокировки для инвариантов над несколькими полями.', 'Почему count++ на volatile — гонка, а volatile boolean flag — корректен? Что такое unsafe publication и как final спасает от half-constructed объекта? Какие действия образуют happens-before помимо volatile?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Класс Object в Java: equals/hashCode контракт, клоны, finalize — почему половину методов нельзя использовать?', 'equals: рефлексивность, симметричность, транзитивность, консистентность, x.equals(null)=false. Нарушение транзитивности при наследовании с дополнительным полем — классическая ловушка (Point/ColorPoint), лечится композицией вместо наследования или instanceof-проверкой без подклассов. hashCode: равные объекты обязаны иметь равный хеш (обратное неверно); менять поля, участвующие в hash, после помещения в HashSet — объект «теряется». clone: поверхностная копия, Cloneable без публичного clone в Object — трюк с проверкой интерфейса; для изменяемых полей нужна глубокая копия, проще конструктор копирования или статическая фабрика. finalize удалён (deprecated с 9, отключён с 18) — вместо него Cleaner/try-with-resources. wait/notify/notifyAll требуют монитора (IllegalMonitorStateException иначе) и в прикладном коде вытеснены java.util.concurrent. getClass() надёжнее instanceof при симметричной семантике equals. toString — контракт на отладку; hashCode по всем полям через Objects.hash быстро деградирует при varargs-аллокациях в горячем коде.', 'Почему наследование с новым полем ломает транзитивность equals и чем композиция лечит? Что произойдёт при мутации поля из hashCode у объекта в HashMap? Почему finalize выпилили из языка?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'JUNIOR', 'String pool, immutability и почему s == t нельзя — как устроено сравнение строк?', 'Строки иммутабельны: методы replace/substring возвращают НОВУЮ строку; это даёт thread-safety, кэширование hashCode и безопасное использование в HashMap. String pool — область кучи со ссылкой на уникальные литералы: одинаковые литералы в классе — один объект; "a"+ "b" константными выражениями интернируется компилятором, а результат concat в рантайме — нет (новый объект). == сравнивает ссылки — для строк, собранных по-разному, даст false даже при одинаковом содержимом; equals — по символам. intern() вручную кладёт строку в пул — почти всегда антипаттерн, исключая легаси-оптимизации памяти. switch по строке использует hashCode+equals внутри. Для конкатенации в циклах — StringBuilder (иначе O(n²) промежуточных строк). Text blocks Java 15+ — многострочные литералы. Compact strings (Java 9+): латиница хранится в byte[] с LATIN1-кодировкой — экономия памяти без изменения семантики.', 'Почему "a"+"b"=="ab" истинно, а s+"b"=="ab" ложно при s="a"? Зачем StringBuilder в цикле и что делает компилятор с одиночным concat? Что изменили compact strings?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Классы-загрузчики: delegation, иерархия, изоляция — как ломаются зависимости в контейнерах?', 'ClassLoader загружает класс по имени и определяет пространство имён: один и тот же class file в двух лоадерах — два разных класса (ClassCastException при обмене). Делегирование: дочерний сначала просит родителя (parent delegation) — java.lang.String всегда от bootstrap, нельзя подменить. Иерархия JVM-приложений: bootstrap (rt, java.*), platform (Java 9+, бывший extension), application (classpath). В контейнерах (Tomcat, OSGi) — свои лоадеры на каждое приложение: изоляция библиотек, но shared-классы должны идти выше; утечка классов при hot redeploy — лоадер держится корнями (ThreadLocal, JDBC-драйвер, shutdown hook) → Metaspace/PermGen OOM. SPI через thread context classloader, чтобы код из bootstrap находил реализации на classpath. ClassNotFoundException — класс не найден при явной загрузке; NoClassDefFoundError — был при компиляции, исчез в рантайме (сломанный classpath, конфликт версий). Диагностика: -verbose:class, какой лоадер загрузил: clazz.getClassLoader(). Fat-jar Spring Boot: JarLauncher с собственным лоадером для вложенных jar.', 'Почему один класс двумя лоадерами — это разные классы и к чему это приводит? Что удерживает ClassLoader при hot redeploy и почему течёт Metaspace? Чем NoClassDefFoundError отличается от ClassNotFoundException?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Virtual threads Java 21: как устроены, когда выгодны и что с ними нельзя делать?', 'Виртуальный поток — легковесный (десятки байт против мегабайта стека platform-потока), планируемый JVM на пуле carrier-потоков (ForkJoinPool). Блокирующий вызов внутри VT «паркуется»: JVM отдаёт carrier другому VT, пробуждение — по готовности (сетевые вызовы через NIO под капотом). Выгода — миллионы одновременных ожиданий: IO-bound сервисы, высокий concurrency (10k соединений), конкурентные фетчи. Ограничения: CPU-bound не ускоряется (число ядер физический потолок), pinning: synchronized блок внутри VT (до JDK 24) не паркует, а держит carrier — использовать ReentrantLock; Object.wait тоже пинит; ThreadLocal — память на миллионах VT,替代 ScopedValue. Не стоит: пулы VT (задачи создаём напрямую), cached регистры в ThreadLocal.ExecutorService с Executors.newVirtualThreadPerTaskExecutor(); structured concurrency (JEP 453) координирует через scope. С Spring Boot 3.2+ — spring.threads.virtual.enabled=true: Tomcat обрабатывает запросы на VT — throughput на IO-нагрузках растёт без реактивного переписывания. Диагностика: jcmd Thread.dump_to_file -format=json показывает паркинги.', 'Что такое pinning виртуального потока и почему synchronized опаснее ReentrantLock? Почему ThreadLocal — проблема для миллионов VT и что вместо? Когда VT медленнее платформенных потоков?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'CompletableFuture: композиция, пулы по умолчанию, исключения — как не наступить на грабли?', 'CF — pipeline асинхронных шагов: supplyAsync (ForkJoinPool.commonPool), thenApply/thenCompose (map/flatMap), thenCombine (два независимых), allOf/anyOf (N-арные). Грабли: (1) commonPool один на JVM — блокирующий шаг (JDBC, HTTP) в thenApply съедает воркеры, весь асинхронный мир встаёт; лечение — always явный executor: supplyAsync(supplier, myPool), thenApplyAsync(f, myPool); (2) thenApply на уже завершённом CF выполняется в вызывающем потоке — неожиданная блокировка вызывающего; (3) исключения летят по цепочке в exceptionally/handle, но thenAccept не получит результат — обязательная обработка хвоста, иначе «глотание» ошибок и зависание get(); (4) get() без таймаута — вечное ожидание; orTimeout/completeOnTimeout (Java 9+); (5) allOf возвращает CF<Void> — результаты доставать join-ом каждого, аккуратно с исключением любого. Модель памяти: действия в CF образуют happens-before. Для фиксированных наборов шагов читабельнее sequential композиция через thenCompose, чем вложенные thenApply.', 'Почему блокирующий вызов в thenApply на commonPool — бомба и как явно задать executor? Чем thenCompose отличается от thenApply? Как обработать исключение в середине цепочки и что вернёт allOf при сбое одного?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'ThreadLocal: сценарии, утечки в пулах потоков, альтернативы (ScopedValue)?', 'ThreadLocal хранит значение на поток: трейсинг-корреляция (MDC), SimpleDateFormat (не thread-safe), буферы, пользовательский контекст в legacy-коде. Механика: Thread.threadLocals — слабые ссылки на ThreadLocalMap.Entry: ключ чистится GC, но value живёт, пока жив поток — в пулах (Tomcat worker живёт вечно) значение протекает между запросами и держит классы/лейблы; лечение: remove() в finally, try-with-resources обёртки, предварительная очистка фильтром. Наследование: InheritableThreadLocal копируется в дочерний поток при создании — но с пулами потоки переиспользуются и копирование не происходит (ловушка). Кластеры значений: Netty FastThreadLocal (быстрее на массиве). Альтернатива Java 21+: ScopedValue — значение привязано к лексической области (ScopedValue.where(KEY, v).run(...)), автоматически очищается, неизменяемо, работает с VT дешевле ThreadLocal. MDC с VT: трансмиттеры (context propagation). Правило: ThreadLocal — только там, где нет другой передачи контекста, и всегда remove в finally.', 'Почему ThreadLocal течёт в пулах потоков и как remove() в finally это лечит? Чем InheritableThreadLocal опасен с пулами? Какие преимущества даёт ScopedValue перед ThreadLocal?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Неблокирующие алгоритмы: очередь Michael-Scott, LMAX Disruptor — когда lock-free быстрее?', 'Lock-free — прогресс гарантирован хотя бы одному потоку (wait-free — всем); CAS-циклы вместо блокировок: нет приостановки потока, нет инверсии приоритетов, но тратится CPU на спин и сложность выше на порядок. Michael-Scott queue — неблокирующая связанная FIFO: CAS на head/tail, помощь потокам (helping) для завершения чужой полу-операции; основа ConcurrentLinkedQueue. ArrayDeque-подобный MPMC: кольцевой буфер + CAS на курсорах (JCTools, Agrona). LMAX Disruptor — кольцевой буфер на 2^n слотов: Sequencer раздаёт слоты producer-ам (CAS или единственный продюсер без CAS), consumer-ы читают по sequence barrier — нет блокировок, нет аллокаций, кэш-дружелюбно (слот = одна кэш-линия, padding против false sharing); механизм batching effect амортизирует координацию. Быстрее locks когда: критическая секция крошечная, конкуренция высокая, задержка детерминирована (трейдинг, телеметрия). Проигрывает: сложные инварианты (легче монитора), низкая конкуренция (uncontended lock дешевле CAS-цикла), необходимость ожидания условия (park/unpark эффективнее спина). Всегда измерять: JCStress для корректности, JMH для скорости.', 'Чем lock-free отличается от wait-free и что такое helping? Почему Disruptor кладёт padding вокруг sequence? Когда synchronized быстрее CAS-цикла?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'ExecutorService: виды пулов, очередь, политика отказа — как настроить под веб-сервис?', 'Пул = corePoolSize (живут всегда), maximumPoolSize (растут при полной очереди), workQueue (unbounded/bounded/synchronous), RejectedExecutionHandler (Abort по умолчанию, CallerRuns —降压, Discard, DiscardOldest), keepAlive для потоков сверх core. Executors.newFixedThreadPool — фиксированный размер + unbounded LinkedBlockingQueue: риск OOM при очереди из задач; newCachedThreadPool — 0..Integer.MAX_VALUE потоков + SynchronousQueue: риск исчерпания потоков/файловых дескрипторов; в проде их не используют — new ThreadPoolExecutor явно с bounded-очередью и осмысленной политикой отказа. Размеры: CPU-bound ~ ядра, IO-bound ~ ядра * (1 + wait/compute), но честнее измерить; для кратких задач — общий пул на сервис, awaitTermination при shutdown + downgrade. Очередь: ArrayBlockingQueue (fixed, честнее по памяти), PriorityBlockingQueue (приоритеты), SynchronousQueue (передача из рук в руки). Отказ CallerRuns создаёт обратное давление — продьюсер замедляется, деградация вместо падения. Spring: @Async с ThreadPoolTaskExecutor, sync vs async, отмена задач Future.cancel(mayInterrupt).', 'Почему newFixedThreadPool с unbounded очередью опасен в проде? Что делает CallerRuns и когда это лучше Abort? Как подобрать размер пула для IO-bound задач?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'JUNIOR', 'synchronized под капотом: monitor, заголовок объекта, biased/thin/fat locks — что происходит при конкуренции?', 'Каждый объект имеет monitor: захват через monitorenter/monitorexit байткод (синхронные методы — флаг ACC_SYNCHRONIZED). Заголовок объекта (mark word) хранит состояние блокировки: unlocked → biased (один поток, атомарный CAS один раз; удалён с JDK 15+ как бессмысленный на современных CPU) → thin lock / stack lock (CAS указателя на запись блокировки в стеке владельца; спин краткий) → fat lock / inflated (взаимодействие с ОС: объект OS-mutex, паркинг потоков через park/unpark). Эскалация — при реальной конкуренции; при её отсутствии синхронный метод почти бесплатен. Reentrancy: счётчик рекурсии в записи блокировки. wait/notify — только владея монитором; парковка отпускает монитор. JIT: lock elision (escape analysis доказал, что объект локален — блокировка убирается), lock coarsening (смежные блокировки сливаются). Гонки данных vs гонки на блокировке: first — JMM, second — производительность. Дедлок: цикл в графе ожидания мониторов; jstack выдаёт «Found one Java-level deadlock»; профилактика — единый порядок захвата, tryLock с таймаутом.', 'Что хранится в mark word и как меняется при эскалации biased→thin→fat? Что делают lock elision и coarsening? Как jstack находит дедлок и какие два способа его предотвратить?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Модель памяти JVM: куча, поколения, metaspace, стек — куда что попадает и зачем зонировать?', 'JVM-память: heap (молодое поколение: eden + survivor S0/S1, старое — old/tenured), metaspace (метаданные классов, нативная память, вне кучи, растёт динамически — ограничивать MaxMetaspaceSize), стеки потоков (Xss, фреймы с локальными переменными), код-кэш (JIT-нативный код), прямые буферы (DirectByteBuffer вне кучи, освобождаются Cleaner-ом). Аллокация: TLAB (Thread-Local Allocation Buffer) — каждый поток аллоцирует в своём куске eden без синхронизации, указатель bump; сверхбыстрая аллокация объясняет, почему короткоживущие объекты почти бесплатны. Возраст объекта: выжил минорному сбору — возраст+1, MaxTenuringThreshold (по умолчанию 15, разбиение адаптивное); большие объекты идут сразу в old (PretenureSizeThreshold) или в humongous-регионы у G1. Escape analysis + scalar replacement — объект, не покинувший метод, вообще не аллоцируется (раскладывается по регистрам). Утечки: static-коллекции, кэши без eviction, слушатели без отписки, ThreadLocal без remove, classloader leaks (Metaspace). Диагностика: jmap -histo, heap dump + MAT (dominator tree), JFR Allocation profiling; native memory tracking -XX:NativeMemoryTracking=summary.', 'Зачем TLAB и почему аллокация в eden почти бесплатна? Что течёт в Metaspace и чем это отличается от утечки кучи? Как escape analysis убирает аллокации целиком?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'OutOfMemoryError: виды (heap, metaspace, GC overhead, direct memory) — как диагностировать каждый?', 'OOM types: «Java heap space» — кучи не хватает на аллокацию: heap dump (-XX:+HeapDumpOnOutOfMemoryError), MAT ищет dominator tree / leak suspects; причины — коллекции-накопители, кэш без лимита, большой результат запроса, нестрогие пагинации. «GC overhead limit exceeded» — 98% времени в GC и <2% результата: куча технически есть, но живые данные близки к пределу — расширить или искать утечку. «Metaspace» — утекают классы: hot redeploy, динамическая генерация (CGLIB/ASM без кэша), ограничения MaxMetaspaceSize; лечить classloader leaks. «Direct buffer memory» — DirectByteBuffer через Cleaner освобождается с задержкой: ограничить MaxDirectMemorySize, ByteBuffer pools (Netty PoolArena). «unable to create native thread» — исчерпаны OS-потоки/память на стеки: уменьшить число потоков/Xss. «Requested array size exceeds VM limit» — new byte[huge]. Общий порядок: какой тип → дамп/логи → воспроизведение под нагрузкой → профилирование (JFR, async-profiler) → фикс (лимит кэша, стриминг, пагинация) → тюнинг кучи как последний шаг, не первый.', 'Чем GC overhead limit отличается от heap space по причинам? Как найти виновника через dominator tree в MAT? Почему direct memory не чистится мгновенно и при чём тут Cleaner?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Профилирование продакшена: JFR, async-profiler, flame graphs — что и как измерять без деградации?', 'Java Flight Recorder — встроенный (с OpenJDK 11 свободный) низко-накладной регистратор событий: аллокации, блокировки, GC, ввод-вывод, профиль сэмплирования (методы execution samples); запуск -XX:StartFlightRecording=duration=60s,filename=... или jcmd JFR.start; анализ в JDK Mission Control (стек-трейсы, allocation by class, long allocation stalls). Накладные ~1-3% — можно держать постоянно (continuous profiling). async-profiler — сэмплирование через perf (Linux) без safepoint-bias: -e cpu / alloc / lock / wall; flame graph: ширина полосы = доля времени/аллокаций, «башни» — горячие пути; идеально для поиска CPU-hotspots и аллокационных пиков. Safepoint bias: JFR/JVM-стеки сэмплируются на safepoint — редкие, но застревающие методы видны с искажением; async-profiler свободен от этого. Практика: CPU-пик → flame (что греет), память → alloc-профиль + GC-лог (кто аллоцирует), паузы → GC-лог + JFR Long GC pause, блокировки → lock-профиль/jstack сериями. Правило: измерять на реальной нагрузке (prod-сэмплинг или точная реплика), микро-деградации ловить латентность per-endpoint (histograms, не среднее!).', 'Что такое safepoint bias и почему async-profiler честнее встроенных стеков? Как читать flame graph и что такое «башня»? Почему средняя латентность врёт и что смотреть вместо неё?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Флаги JVM на каждый день: heap sizes, GC-выбор, OOM-dump — что выставлять в контейнере?', 'База: -Xms=-Xmx (фиксированная куча — без колебаний ресайза; в контейнере память лимитами пода), -XX:MaxMetaspaceSize=256m, -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=... (дамп при первом OOM — золотой артефакт), -XX:+ExitOnOutOfMemoryError (умереть честно — k8s перезапустит, вместо полуживого состояния). Контейнер: -XX:+UseContainerSupport (дефолт с 10+) — JVM видит cgroup-лимиты; MaxRAMPercentage=75.0 вместо жёстких Xmx (память от лимита пода); осторожно: контейнер OOMKilled убивает по RSS — сумма heap+metaspace+stacks+direct+JIT должна влезать. GC: G1 дефолт (-XX:MaxGCPauseMillis=200 цель), ZGC для латентных (-XX:+UseZGC, паузы <1ms, чуть ниже throughput), Serial для 1 core/256MB. GC-лог: -Xlog:gc*:file=...:time,uptime:filecount=5,filesize=10m (ротация). JFR-старт: -XX:StartFlightRecording=filename=... Критично не перебирать: большинство флагов — тюнинг после измерений; стартовый набор — memory+dump+exit+GC-лог.', 'Почему Xms=Xmx считается хорошей практикой и что ломается при кучи «на вырост»? Зачем ExitOnOutOfMemoryError в k8s? Как JVM узнаёт о лимитах контейнера и что выставить вместо Xmx?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Sealed interfaces, pattern matching, records — как Java 17/21 меняют моделирование домена?', 'Sealed (Java 17): иерархия закрыта — permits перечисляет прямых наследников; компилятор знает полный набор вариантов. Вместе с pattern matching for switch (Java 21) даёт алгебраические типы: sealed interface Payment permits Card, Crypto, Invoice; switch по типам exhaustive — добавили вариант, забыли обработать → ошибка компиляции, а не рантайма. Record patterns (Java 21) разбирают вложенные структуры: if (obj instanceof Line(Point(var x1, var y1), Point(var x2, var y2))) — деконструкция без бойлерплейта. Records для носителей данных + sealed для альтернатив = domain modeling уровня функциональных языков: иммутабельность, исчерпывающий анализ, нулевая вероятность «забытого case». Гибкость ниже наследования классов — это фича: жёсткая иерархия дисциплинирует изменения (новый вариант = правки во всех switch). Когда не sealed: открытые расширения (публичные API-контракты, плагины). Record + sealed + static factory: компактные «умные конструкторы» с валидацией. Всё это снижает количество багов «состояние, которое не обработали» — класс迟到 ошибок в больших switch/if-else цепочках.', 'Что даёт exhaustive switch над sealed-иерархией и какую ошибку он предотвращает? Чем record pattern улучшает разбор вложенных структур? Когда sealed вреден для архитектуры?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Text blocks и новые String-методы — где реальная польза, а где вред?', 'Text block (Java 15): """ — многострочный литерал с автоматической.manage indent: минимальный отступ всех строк вырезается, \ сохраняет строку, \s — пробел в конце. Польза: SQL, JSON, HTML-шаблоны в тестах, скрипты — читаемость без конкатенации + переводов. Вред: динамические значения — интерполяции нет (придёт в 21+ со String templates), string.format поверх text block уродует; escape-симметрия SQL/JSON — кавычки внутри не дублируются (в отличие от старых строк), но легко забыть про язык-внутри-языка. Форматирование:formatted() (бывший format) — позиционные подстановки; stripIndent/translateEscapes — служебные для обработки. Антипаттерн: собирать SQL text block-ом с конкатенацией условий — читаемость падает; для динамики — JdbcTemplate/QueryDSL. Тесты: text block + JSONassert — компактные фикстуры. Внутри text block действует Java-лексика: \n — реальный перенос, а не два символа.', 'Как text block определяет, сколько отступа вырезать? Чем formatted() удобнее конкатенации? Почему динамический SQL на text block — антипаттерн?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Stream API: коллекторы groupingBy/downstream, teeing, flatMapping — сложные агрегации без циклов?', 'Collectors.groupingBy(classifier, downstream) — группировка; downstream-комбинатор строит конвейер внутри групп: counting(), summingInt(), mapping(фн, downstream) (сначала преобразовать, потом собрать), filtering(пред, downstream) (отфильтровать внутри группы — в отличие от filter до groupingBy, меняет состав ценой вложенности), flatMapping (флаттенить вложенные коллекции внутри групп). toMap(keyFn, valFn, mergeFn, mapFactory) — merge-функция обязательна при дубликатах ключей, иначе IllegalStateException; LinkedHashMap для порядка. teeing(c1, c2, merger) — два коллектора параллельно над одним стримом, слияние результатов (например, min и max за проход). collectingAndThen(collector, finisher) — пост-обработка: toList + unmodifiableList. Unmodifiable-коллекторы: toUnmodifiableList. Параллельность: groupingBy ConcurrentMap-вариант (groupingByConcurrent). Кастомный коллектор: Collector.of(supplier, accumulator, combiner, characteristics) — например, гистограмма в одну строку. Производительность: простые count/sum на маленьких коллекциях циклом быстрее — стримы платят за лямбды и пайплайн; сложные группировки — читаемость и меньше ошибок.', 'Чем filtering-downstream отличается от filter до groupingBy и когда какой брать? Зачем teeing и что он заменяет из императивного кода? Когда стрим-агрегация проигрывает циклу?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Побитовые и числовые хитрости: как hashCode с 31, кэш в Integer, переполнение — что спрашивают на собесах?', 'Классический String.hashCode: h = 31*h + c — 31 нечётное простое, переполнение int определено (JSR-133: wrap-around), распределение хорошее, умножение на 31 = (h<<5)-h — JIT заменяет на сдвиг и вычитание. Кэш хеша строки — lazy, immutable позволяет. Integer cache: Integer.valueOf кэширует -128..127 — == для Integer в этом диапазоне истинно, вне — ложь: вечная ловушка собеседований; всегда equals. Integer.MIN_VALUE: -MIN_VALUE == MIN_VALUE (нет положительного аналога), Math.abs(MIN_VALUE) < 0 — защита в hashCode-функциях: (x ^ (x >> 31)) & MAX. Float/Double.equals не рефлексивны с числами (NaN.equals(NaN)=true, а NaN != NaN, -0.0 vs 0.0 — equals ложь, == истина) — в ключах коллекций сюрпризы; для сортировки Double.compare. Переполнение: JDK 8+ Math.addExact/subtractExact/multiplyExact — бросают ArithmeticException вместо тихого wrap; Long.MAX_VALUE наносекунд хватает на ~292 года — System.nanoTime безопасен. Проверка на степень двойки: (n & -n) == n.', 'Почему умножение на 31 в hashCode и что делает JIT? Почему Math.abs(Integer.MIN_VALUE) отрицательный? Чем опасен Double в качестве ключа HashMap?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kotlin vs Java interop: @JvmStatic, @JvmOverloads, nullability — что ломается на границе?', 'Kotlin→Java: имена файлов/классов (FileKt, @file:JvmName), companion → Outer$Companion.INSTANCE (@JvmStatic делает static), свойства → getX/setX, default-аргументы — методы с полной арностью (@JvmOverloads генерирует перегрузки), nullability: T? → T с @Nullable аннотацией (для Java — предупреждение, не ошибка), platform types T! из Java в Kotlin — компилятор верит без проверки: NPE в рантайме (лечится явными типами/аннотациями). Java→Kotlin: getters/setters выглядят как свойства (sync parking), checked exceptions не проверяются Kotlin-ом (можно не ловить), static members через companion или @JvmField. SAM-конверсии: лямбда в Java-интерфейс работает, свой functional interface — fun interface. Специфика: data class equals/hashCode корректны, но Java-код вызывает component1() странно; sealed — через @JvmName хаки; suspend-функции — Continuation-параметр (Callback-стиль для Java: use coroutines with CompletableFuture bridge). Библиотеки: Kotlin stdlib в зависимостях Java-проекта транзитивно — размер. Диагностика границ: kotlinc -Xjsr305=strict (уважает JSR-305 аннотации).', 'Что такое platform type и почему NPE из Java-кода не виден компилятору Kotlin? Зачем @JvmOverloads и что без него? Как Java-код вызывает suspend-функцию?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Spring Boot автоконфигурация: @Conditional, spring.factories, как пишется свой starter?', 'Автоконфигурация — @Configuration-классы, подключаемые через META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports (Boot 2.7+; ранее spring.factories). Каждый активируется по условиям: @ConditionalOnClass (класс в classpath), @ConditionalOnMissingBean (пользовательский бин приоритетнее), @ConditionalOnProperty, @ConditionalOnResource, @ConditionalOnWebApplication. Порядок: @AutoConfigureBefore/After. Свойства — @ConfigurationProperties(prefix) + @EnableConfigurationProperties или @ConfigurationPropertiesScan; валидация JSR-303. Свой starter: autoconfigure-модуль (конфигурация + properties) + starter-модуль (только зависимости, пустой) — конвенция имени xxx-spring-boot-starter (свои) vs spring-boot-starter-xxx (официальные). Debug: --debug включает ConditionEvaluationReport ("Positive matches/Negative matches" в логе запуска), actuator /actuator/conditions. Ключевой принцип: автоконфигурация отступает перед явными бинами пользователя (OnMissingBean на всё), библиотека приносит дефолты, приложение переопределяет. Свой starter типовой состав: XxxProperties, XxxAutoConfiguration, XxxService, META-INF imports-файл, тесты: ApplicationContextRunner с UserConfigurations/FilteredClassLoader (симуляция отсутствия класса).', 'Как @ConditionalOnMissingBean обеспечивает приоритет конфигурации пользователя? Что показывает /actuator/conditions и как читать отчёт? Зачем starter делится на два модуля?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Spring Events: ApplicationEvent, @EventListener, @TransactionalEventListener — зачем и когда?', 'События — слабая связанность внутри приложения: издатель publishEvent(new OrderCreatedEvent(...)), слушатели @EventListener — Spring доставляет синхронно в том же потоке (по умолчанию), порядок @Order. Асинхронно — @Async + настроенный executor (осторожно с контекстом: MDC, security). @TransactionalEventListener(phase = AFTER_COMMIT) — слушатель сработает только после коммита: аудит, рассылки, публикация в Kafka НЕ должны происходить при откате; фазы BEFORE_COMMIT, AFTER_ROLLBACK, AFTER_COMPLETION; если транзакции нет — событие теряется (fallbackExecution = true включает). Типовая схема: бизнес-метод в транзакции публикует событие → AFTER_COMMIT-слушатель интегрируется наружу; альтернатива outbox при требованиях гарантии доставки. События vs прямые вызовы: события оправданы, когда реакций несколько/они меняются независимо (аналитика, уведомления), и вредны для основной бизнес-логики — управление превращается в неявный граф. Внутреннее: ApplicationEventMulticaster, ошибку в одном слушателе ловит ErrorHandler (по умолчанию падает всё).', 'Чем AFTER_COMMIT отличается от публикации сразу после метода и какую ошибку это предотвращает? Что происходит с @TransactionalEventListener без транзакции? Когда события хуже прямого вызова?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Hibernate кэширование: 1st level, 2nd level, query cache — что включать и почему осторожно?', 'First-level cache — сессия (Persistence Context): в одной транзакции повторный getById берёт из контекста без SQL; flush очищает отложенные изменения; dirty checking — сравнение снапшотов при флеше. Second-level — разделяемый между сессиями (Ehcache, Caffeine, Redis через JCache/Infinispan): entity по id и коллекции; включается @Cacheable на сущности + провайдер; инвалидация — при update через Hibernate, ВНЕ Hibernate (нативный SQL, другие инстансы) кэш не знает → stale; кластер: репликация/invalidation — сложность резко растёт. Query cache — результаты запросов (ключ = запрос+параметры): инвалидация по таблицам ANY-update (любая запись в таблицу роняет все запросы по ней) — на динамичных таблицах бесполезен, работает на справочниках. Практика: 90% случаев правильнее кэшировать на уровне приложения (Spring Cache + Caffeine) осознанными ключами с TTL, чем L2Hibernate; L2 оправдан: read-mostly справочники, одна точка записи. Опасности: ленивые ассоциации в кэше (detached), коллекции-монстры, негативный кэш отсутствующих id.', 'Чем first-level отличается от second-level по времени жизни и видимости? Почему query cache часто бесполезен на записываемых таблицах? Когда L2 хуже прикладного Spring Cache?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Spring Data JPA: производительность выборок — проекции vs сущности, pagination на больших таблицах?', 'Выборка сущностей тянет все поля + ленивые ассоциации при обращении; для списков/отчётов нужны проекции: interface projection (закрытые getters), DTO constructor expression (select new ru.x.UserDto(u.id, u.name) from User u) — один SQL ровно с нужными колонками, без persistence context (нет dirty checking, дешевле память). Пагинация: Pageable → limit/offset; на больших таблицах offset глубокий сканирует и отбрасывает (offset 1000000 читает миллион строк) — keyset pagination (where id > :lastId order by id limit n) для бесконечных скроллов; count-запрос Page дорог на сложных join — Slice (без count, hasNext по limit+1). @Query с Pageable: сортировка через Sort или :pageable; join fetch + pagination на коллекции — Hibernate предупреждаетHHH000104 и падает в память: сначала page родителей, потом fetch детей (два запроса). existsById vs count>0 — exists короче. Bulk: @Modifying update/delete — не трогает persistence context (устаревшие сущности в той же транзакции!) — clearAutomatically = true.', 'Почему DTO-проекция дешевле сущности в списке? Чем keyset pagination лучше offset на глубине? Что делает @Modifying(clearAutomatically) и без него что устареет?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'WebFlux vs MVC: когда реактивность оправдана и что она ломает?', 'Reactive (WebFlux + Reactor) — неблокирующий end-to-end: немного потоков обрабатывают тысячи одновременных ожиданий; выгоден: IO-bound шлюзы, агрегация многих медленных источников, SSE/стриминг, полная цепочка реактивная (R2DBC, reactive Redis/Kafka). Если хоть одно звено блокирующее (JDBC, legacy-клиент) — польза сгорает: блокирующий вызов на event-loop потоке останавливает ВСЕ запросы этого потока; обход — оборачивание в boundedElastic (переполнение отдельного пула). Ломает: ThreadLocal (MDC, SecurityContext) — нужен Reactor Context; стек-трейсы лямбд нечитаемы; отладка checkpoint/log; блокирующий心智 код в map вместо flatMap — deadlock; обучение команды дороже. Java 21 virtual threads закрывают главную нишу WebFlux (IO-конкурентность) без реактивного программирования: MVC + VT даёт throughput близко к WebFlux с обычным императивным кодом. Решение сегодня: MVC + VT по умолчанию; WebFlux — когда нужен стриминг/SSE, R2DBC, полная реактивная экосистема или уже есть реактивные клиенты.', 'Почему один блокирующий вызов убивает всю выгоду WebFlux и где его можно спрятать? Чем virtual threads угрожают главному аргументу WebFlux? Что заменяет ThreadLocal в реактивной цепочке?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'REST-версионирование и эволюция API: path vs header, deprecation — как не сломать клиентов?', 'Способы версий: URI /v1/ (просто, кэшируемо, логи читаемы — де-факто стандарт), header Accept: application/vnd.company.v2+json (чисто, но боль: curl, прокси, документация), query ?version= (плохо кэшируется), домены api2. (инфраструктурно). Добавлять обратно-совместимо можно без версии: новые поля (клиенты игнорируют unknown), новые эндпоиты, новые опциональные параметры. Ломающие изменения: удаление/переименование полей, смена типов, изменение семантики (стало 404 вместо 200), обязательность прежних опциональных полей — требуют новую версию. Deprecation-процесс: пометить в OpenAPI deprecated + Sunset-заголовок (RFC 8594), логировать использование старой версии по клиенту, коммуницировать дату выключения, метрики по версии. Client errors: 400 с problem-detail (RFC 7807) — машиночитаемо. Никогда не менять поведение молча: «мягкое» изменение семантики хуже честного v2. Внутри — feature-флаги на сервере для переходного периода, контрактные тесты (Pact, Spring Cloud Contract) фиксируют совместимость.', 'Какие изменения обратно совместимы и не требуют версии? Что такое Sunset-заголовок и как им пользоваться? Чем URI-версионирование лучше header и почему его выбирают чаще?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kafka: компакция, retention, tiered storage — как хранить топики правильно?', 'Retention: time (retention.ms, дефолт 7 дней), size (retention.bytes), или компактация (cleanup.policy=compact) — по последнему значению ключа: топик состояния (config, schema-registry changelog, __consumer_offsets); compacted ≠ вечное хранение: удаление по delete.retention.ms для tombstone (значение null = маркер удаления). Совмещение policy=compact,delete — компакция + время. Сегменты: активный сегмент не компактируется — min.cleanable.dirty.ratio управляет долей грязи; очистка log cleaner в фоне. Tiered storage (KIP-405, 3.6+): горячие сегменты локально, старые в S3 — брокер держит меньше диска, рестрайп быстрее, retention растёт до месяцев дёшево. Ключи партиционирования: по ключу — порядок в партиции; изменение ключа ломает порядок — версионировать ключи осторожно. Формат: batch + compression (lz4/zstd) — сжатие батча эффективнее построчного; zstd лучший ratio. __consumer_offsets — компактed, replication.factor=3 для всех внутренних топиков. Ретеншн ≠ гарантирующий повтор: consumer group offset может быть за retention (смещение удалено) — перечитывание с earliest потеряет хвост.', 'Чем tombstone удаляет запись в compacted-топике? Что делает policy=compact,delete? Почему tiered storage удешевляет длинный retention и что остаётся на брокере?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Схема данных в Kafka: Schema Registry, Avro/Protobuf, совместимость — зачем и как?', 'JSON без схемы — продюсер и консьюмер расходятся молча: поле переименовано, консьюмер читает null. Schema Registry — центральный реестр: продюсер регистрирует схему (subject = topic-key/value), сериализует id схемы в сообщение; консьюмер берёт схему по id; совместимость проверяется при регистрации: BACKWARD (новая читает старые данные — дефолт), FORWARD (старая читает новые), FULL (оба), NONE. Avro — компактный бинарный формат, schema evolution: добавление поля с default — BACKWARD-совместимо, удаление с default — FORWARD; изменение типа поля — обычно несовместимо. Protobuf — легче для полиглотов (нативно в gRPC), tag-based: переименование полей безопасно, удаление — reserved. Стратегии subject: TopicNameStrategy (по топику), RecordNameStrategy (по типу записи — несколько типов в топике). Практика: режим совместимости на subject (обычно BACKWARD_TRANSITIVE), запрет undebugged schema через REST-политику; consumer-specific чтение: только нужные поля (проекция). kcat/schema-registry-client для ручных проверок. Версионирование через Sunday: schema_id в заголовках облегчает миграцию.', 'Чем BACKWARD отличается от FULL совместимости и что сломается при неправильном выборе? Почему в Avro новое поле требует default? Что даёт RecordNameStrategy против TopicNameStrategy?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kafka Streams: окно, join, exactly-once — когда стримы лучше консьюмера+логики?', 'Kafka Streams — библиотека (не отдельный кластер): DSL-топология над топиками; состояние — локальный RocksDB + changelog-топик (восстановление при рестарте), поэтому масштабирование по key-партициям. Оконные агрегации: tumbling (незаходящие), hopping (перекрывающиеся), sliding (по времени события), session (по активности с gap); окно привязано к event-time через timestamp extractor (embedded — по Record timestamp); out-of-order — grace period (окно закрывается спустя grace после конца). Joins: stream-stream (окно — обе стороны по времени), stream-table (обогащение), table-table (материализованное состояние); foreign-key table join ограничен. EOS: processing.guarantee=exactly_once_v2 — атомарно смещения+выходные записи; требует transactional producer, idempotence, session timeout tuning. Когда стримы: непрерывные агрегации/окна/joins без внешнего хранилища, повтор (rebalance без потери состояния), интерактивные запросы (IQ — чтение состояния стора). Когда консьюмер: сложная бизнес-логика с БД/транзакциями, нестандартная маршрутизация — проще управлять.', 'Откуда Kafka Streams восстанавливает состояние после падения и что такое changelog? Как grace period обрабатывает опоздавшие события? Что даёт exactly_once_v2 и его цена?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Планы запросов PostgreSQL: EXPLAIN ANALYZE, сканирования, стоимость — как читать план?', 'EXPLAIN [ANALYZE, BUFFERS, VERBOSE] — ANALYZE реально выполняет (опасно на UPDATE/DELETE — обернуть в ROLLBACK-транзакцию); BUFFERS — попадания в shared_buffers/диск. Узлы: Seq Scan (полное чтение), Index Scan (по индексу + heap-доступ), Index Only Scan (только индекс — требует актуальной visibility map), Bitmap Heap Scan + Bitmap Index Scan (сначала битовая карта по индексу, потом heap — хорошо для средней селективности и OR), Nested Loop (внешняя малая + внутренняя по индексу), Hash Join (хэш меньшей стороны + скан большей), Merge Join (оба отсортированы). Числа: cost=startup..total (условные единицы, произвольные последовательные_страницы), rows — оценка планировщика, в ANALYZE actual time/rows — расхождение оценки с фактом >10x — статистика: ANALYZE таблицы, увеличение default_statistics_target, расширенная статистика (CREATE STATISTICS по зависимым колонкам). Петля (loop=N) — узел выполнен N раз, умножать actual на N. Init Plan / SubPlan — подзапросы. Антипаттерны чтения: смотреть только top-узел; сравнивать cost без ANALYZE (оценки); игнорировать BUFFERS (реальная цена I/O).', 'Чем Bitmap Scan выгоднее Index Scan при средней селективности? Что означает расхождение rows-оценки и actual в 100 раз и как чинить? Почему Index Only Scan может деградировать до Index Scan?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Репликация PostgreSQL: синхронная, асинхронная, слоты — RPO/RTO и подводные камни?', 'Физическая потоковая репликация: standby подключается к primary, получает WAL-записи; async (дефолт) — primary не ждёт standby: падение primary теряет неподтверждённые транзакции (RPO>0); sync (synchronous_standby_names) — коммит ждёт подтверждения standby (remote_write/remote_apply/flush): RPO=0, цена — латентность коммита = RTT до standby, при недоступности sync-standby коммиты висят (sync_replication_timeout). Реплика слота (replication slot) — удерживает WAL до подтверждения получения standby: защищает от отставания, но упавший standby = WAL-накопление на primary → диск переполнен (главный инцидент с pg_repl_slots); мониторинг pg_replication_slots (restart_lsn, active). Failover: patroni/etcd — автоматика; ручной promote — рассинхрон timeline (pg_rewind). Горячий standby — read-only запросы (hot_standby); конфликт recovery с запросами (vacuum удаляет записи нужные снапшоту — canceling query due to conflict, hot_standby_feedback/max_standby_streaming_delay). Логическая репликация (pub/sub) — таблицы выборочно, разные версии/схемы, no DDL. Выбор: sync — финансы/согласованные чтения; async + мониторинг lag —绝大多数 случаев.', 'Чем опасен replication slot при долгом падении standby? Какую цену платит коммит при synchronous_commit=remote_apply? Что такое WAL и почему его удержание переполняет диск?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'MongoDB: replica set, write concern, read preference — гарантии против скорости?', 'Replica set: primary принимает записи, secondaries реплицируют oplog; election при падении primary (raft-подобный, priority, votes). Write concern: w:1 — ack от primary (быстро, риск потери при его падении до репликации), w:majority — подтверждение большинством (durability, медленнее), j:true — journal flush на диске; w:0 — fire-and-forget. Read preference: primary (последовательные чтения), primaryPreferred (failover чтений), secondary (разгрузка чтений — eventual consistency: прочитал старое), secondaryPreferred, nearest (латентность). Каузальность: causal consistency session — read/write после своего write с majority; без него secondary-чтение может вернуть прошлое. Transactions: multi-document на replica set (с 4.0), сессия с startTransaction — производительность заметно ниже, ограничение 60с (по умолчанию); правильно смоделированная схема (embed) должна избегать транзакций. Индексы: secondary читает по тем же индексам — indexing plan одинаков. Мониторинг: replication lag (oplog window), election события, connection pool per-node.', 'Что теряется при w:1 и падении primary до репликации? Когда чтение с secondary возвращает устаревшие данные и как лечит causal session? Почему multi-document транзакции в Mongo — редко хороший выбор?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Redis: персистентность RDB/AOF, репликация, Sentinel vs Cluster — что выбрать под задачу?', 'Персистентность: RDB — снапшоты по расписанию (fork, компактно, быстро рестарт, потеря данных между снапшотами), AOF — журнал команд (fsync everysec: максимум 1с потери, always: без потерь но медленно, no: на откуп ОС); вместе: AOF+RDB (redis 7 hybrid — быстрый рестарт из RDB + хвост AOF). Репликация — асинхронная: replicaOf primary; полный sync (RDB-передача) при первом/отставании; отставание по bandwidth. Sentinel — надёжность одного shard: мониторинг, автоматический failover (quorum сурrogатов), уведомление клиентам нового master (через pub/sub, клиентские библиотеки поддерживают); sentinel требует 3+ узлов (нечётное) для выборов; несколько сурrogатов не масштабируют запись — один master. Cluster — шардирование: 16384 слота по хешу ключа, master-ы держат слоты, slave-ы реплицируют; клиент умный (MOVED/ASK редиректы), multi-key операции — в одном слоте (hash-теги {user1}:...); нет multi-db, транзакции ограничены слотом. Выбор: кэш с потерей — один инстанс + реплика; HA — sentinel; большой объём/пропускная — cluster. Красные флаги: KEYS в проде (SCAN), отсутствие maxmemory+policy, big keys.', 'Чем AOF everysec отличается от always по компромиссу? Почему Sentinel не масштабирует запись и что умеет Cluster с слотами? Зачем hash-теги в multi-key операциях кластера?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Docker-образ для JVM: слои, multi-stage, distroless — как уменьшить и ускорить?', 'Мульти-stage: первый stage — gradle/maven сборка (кэш зависимостей отдельным слоем: копировать только build.gradle/settings.gradle + скачать зависимости, потом исходники — инкрементальные билды), второй — jre-образ с артефактом. База: eclipse-temurin:21-jre (~260MB), alpine-варианты меньше но musl (GC-паузы другие, возможны баги JNI), distroless/java-debian12 — без shell/package manager: меньше поверхность атаки, debug только через exec nsenter; slim-варианты — компромисс. Слои: редко меняющееся раньше (зависимости → приложение), Dockerfile cache. Java-специфика: classloader-кэш CDS/AppCDS — ускорение старта; Spring Boot layertools — зависимостные слои образа (jarmode=layertools extract): базовые слои не пересобираются при каждом коммите. Размер vs безопасность: теги вместо latest (воспроизводимость), COPY --chown без root, USER app; HEALTHCHECK delegирован k8s (не дублировать). BuildKit: --mount=type=cache для gradle-кэша. Ресурсы: JVM в контейнере видит лимиты (UseContainerSupport) — память из пода. Сканирование: trivy/grype в CI. Spring Boot: исполняемый jar без распаковки → CDS недоступен — распакованный classpath быстрее стартует.', 'Зачем Spring Boot layertools и что он даёт слоям образа? Чем distroless лучше alpine и что теряешь? Почему слой зависимостей должен идти раньше кода?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kubernetes: ConfigMap/Secret, sealed-secrets, ротация — как доставлять конфиги и секреты безопасно?', 'ConfigMap — незасекреченные конфиги (env-переменные, файлы через volume), Secret — base64 (НЕ шифрование — только кодировка) с этcd-шифрованием at rest (настроить encryption at rest!), RBAC на чтение. Env vs volume: env — статичен до рестарта пода; volume-монтраж — kubelet обновляет (синхронизация ~минута, symlink-свитч). Spring: spring.config.import=optional:configtree:/etc/config/ — читает volume-дерево (файл=ключ) и подхватывает обновления без рестарта (RefreshScope/actuator refresh для бинов). GitOps: секреты в git нельзя — sealed-secrets (контроллер расшифровывает SealedSecret в кластере, приватный ключ только там) или SOPS+KMS (шифрование значений, git хранит шифротекст, расшифровка при деплое), external-secrets (секрет живёт в Vault/cloud-KMS, оператор синхронизирует). Ротация: автоматическая с внешним источником (Vault dynamic secrets — TTL), перезапуск подов на OnChange (reloader/stakater). Антипаттерны: секреты в образе (env-переменные образа видны в docker history/inspect), в CI-переменных с логированием, base64 как «защита». Аудит: audit log на etcd-доступ к secrets.', 'Почему base64 в Secret не защита и что обеспечивает реальную защиту? Чем volume-монтирование секрета лучше env-переменной? Как sealed-secrets позволяют хранить секреты в git?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Helm: шаблоны, values, hooks — как шаблонизировать деплой без боли?', 'Helm-чарт: templates/*.yaml с Go-шаблонами ({{ .Values.replicas }}), values.yaml — дефолты, overrides через -f my.yaml или --set; Chart.yaml — версия чарта и appVersion. Хелперы: {{ include "chart.fullname" . }} — переиспользуемые куски; required/fail — валидация входа; toYaml/indent — вставка кусков. Условные блоки {{- if .Values.ingress.enabled }}; range по спискам. Hooks: pre-install/post-install/pre-delete — Jobs для миграций (pre-upgrade с hook-weight), осторожно: hook-failed блокирует релиз. Релизы: helm upgrade --install --atomic (rollback при失败) --wait (готовность ресурсов); history/rollback; three-way merge при upgrade. Зависимости: subcharts (условные), alias. Библиотек-чарты для общих кусков. Альтернативы: Kustomize (патчи без шаблонов — слоистая конфигурация), plain-YAML+CD (Argo). Антипаттерны: гигантские one-fits-all чарты с сотней флагов (лучше несколько простых), helm install как замена kubectl-скриптам без версионирования, секреты в values.yaml.', 'Что делает --atomic и почему это лучше ручного rollback? Зачем pre-upgrade hook для миграций БД? Когда Kustomize удобнее Helm?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Observability: метрики, логи, трейсы — OpenTelemetry как стандарт, как собрать вместе?', 'Три столпа: метрики (агрегаты, дёшево, алертинг), логи (детали события), трейсы (путь запроса через сервисы) — корреляция по trace_id в логах (MDC + OTel appender) связывает их. OpenTelemetry — стандарт: API + SDK + OTLP-протокол + Collector (пайплайн: receive→process→export в Prometheus/Jaeger/Loki); автоинструментация Java-агентом (-javaagent:opentelemetry-javaagent.jar) — Spring/MVC/JDBC/Kafka/HTTP из коробки, spans с атрибутами; ручная — @WithSpan, Span.current(). Метрики: RED (Rate/Errors/Duration) per endpoint + USE (Utilization/Saturation/Errors) per ресурс; histogram для квантилей (не average!). Семплирование трейсов: head-based (решение в начале, parent-based сохраняет дерево) vs tail-based (решение по итогу в Collector — дорого, но интеллектуально: сохранять только ошибки/медленные). Контекст: W3C Trace Context (traceparent header). Экспоненты: exemplars связывают метрику-гистограмму с конкретным трейсом. Деплой Collector: agent (sidecar/daemonset) → gateway — отделение приложения от бэкендов.', 'Чем head-based сэмплирование отличается от tail-based и что выгоднее? Как trace_id в логах связывает три столпа? Почему для латентности гистограмма, а не среднее?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Prometheus: pull-модель, типы метрик, PromQL — как строить дашборды и алерты?', 'Pull: Prometheus скрапивает /metrics экспортеров (/service discovery в k8s); при коротких подах — pushgateway для batch-джоб. Типы: counter (только рост: http_requests_total — rate() для скорости), gauge (значение сейчас: queue_size), histogram (бакеты: latency_bucket — histogram_quantile для p99), summary (квантили на клиенте — не агрегируются, почти не используют). PromQL: rate(http_requests_total[5m]) — RPS, error ratio: sum(rate(http_requests_total{status=~"5.."}[5m])) / sum(rate(...[5m])), латентность histogram_quantile(0.99, sum(rate(latency_bucket[5m])) by (le)); aggregation by (service, endpoint). Recording rules — препcomputation тяжёлых выражений; алерты в Alertmanager: группы, inhibit, routing (дежурному в Telegram/Slack), for: 5m против флапа. Красные флаги: средние вместо квантилей, счётчики без rate, метки с высокой кардинальностью (user_id в label — взрыв временных рядов), алерты без дашборда-контекста. Золотые сигналы: latency/traffic/errors/saturation — стартовый набор любого сервиса.', 'Почему counter анализируют через rate, а не напрямую? Чем histogram лучше summary для агрегации? Что случится от user_id в метке метрики?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'SLO/SLI/error budget: как договориться о надёжности и не воевать с бизнесом?', 'SLI — измеримый индикатор: доля успешных запросов (2xx не 5xx), латентность p99 < 300ms, freshness данных < 5мин. SLO — целевой уровень SLI за окно (30 дней): 99.9% запросов успешны. Error budget = 1 - SLO (0.1%): допустимая норма сбоев — ресурс на изменения; бюджет исчерпан → заморозка фич, только надёжность (правило прописано в policy, не в споре). SLA — контракт с деньгами (страховка), строже SLO. Реализация: SLI из метрик (Prometheus), многооконный burn-rate алертинг: fast burn (2% бюджета за час — page), slow burn (5% за 6ч — ticket) — Google SRE workbook formula; SLO-дашборд: текущий SLI, остаток бюджета, прогноз. Продуктовые SLO: не все эндпоинты равны — критичный путь строже. Антипаттерны: SLO 100% (ноль бюджета — никакого деплоя), SLI по средней латентности (хвосты скрывают), SLO без последствий исчерпания (просто цифра). Проектный процесс: событие рассмотрения бюджета еженедельно, постмортемы безвинные (blameless) кормят улучшения.', 'Что такое error budget и какие организационные последствия у его исчерпания? Почему алертят на burn rate, а не на голое нарушение SLO? Чем SLA отличается от SLO?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'CI/CD пайплайн: стадии, артефакты, деплой-стратегии — что должно быть в зрелом пайплайне?', 'Стадии: lint/static (detekt, spotless) → build → unit → integration (Testcontainers) → package (образ, SBOM) → security (trivy, зависимость-скан) → deploy staging → e2e/smoke → deploy prod (ручной approval). Артефакт один на весь путь (образ иммутабелен, tag = git-sha, latest запрещён); конфигурация отдельно (env-специфичные values). Кэши: gradle/maven кэш, слой-кэш docker (buildx cache-from/to). Параллелизация: матрица джобов (JDK/модули), merge queue против поломанных main. Деплой-стратегии: rolling (дефолт k8s), blue-green (две среды, переключение — мгновенный rollback, дорого по ресурсам), canary (постепенный трафик 1%→10%→100% + метрики-гейт: Argo Rollouts, Flagger — автооткат по error rate/latency), feature flags отделяют релиз от выкатки (dark launch). Триггеры: PR — lint+test (быстро <10мин), main — полный + образ, тег — релиз. Секреты CI — из vault/OIDC, не из переменных. Метрики пайплайна: lead time, время до зелёного, failure rate, MTTR. DORA-метрики связывают CI/CD-зрелость с бизнесом.', 'Почему артефакт должен быть один и иммутуем на всех окружениях? Что даёт canary с метрик-гейтом против простого rolling? Зачем merge queue и какие метрики пайплайна смотрят?' from categories where slug = 'ci-cd';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Flyway/Liquibase: как вести миграции без простоя и конфликтов?', 'Миграции версионируются (V1__, V2__...), применяются по порядку, checksum зафиксирован в таблице истории — изменение применённого файла = ошибка (валидация при старте); flyway repair для выравнивания. Правила: файлы неизменны после мержа, новые — только сверху; откаты — новыми миграями (не редактированием), Liquibase хранит rollback-XML. Zero-downtime (expand/contract): фаза 1 — добавить колонку nullable (старый код пишет без неё), фаза 2 — деплой кода, пишущего/читающего обе, бэкфилл данных батчами, фаза 3 — contract: удалить старую. Опасные операции: rename колонки (два шага: add+copy+switch), NOT NULL на живой таблице (в PG 12+ = проверка полного скана — добавить как CHECK NOT VALID → VALIDATE отдельно), CREATE INDEX без CONCURRENTLY (блокировка записи!), длинные транзакции блокируют autovacuum. Практика: CI-прогон миграций на копии прод-данных, тайминг больших ALTER на объёме, advisory lock против параллельных запусков (flyway держит сам). Repeatable-миграции (views) перезаполняются при изменении.', 'Почему нельзя редактировать уже применённую миграцию и что такое checksum? Зачем CREATE INDEX CONCURRENTLY и чем плох полный скан при NOT NULL? Опишите expand/contract на примере переименования колонки.' from categories where slug = 'db-migrations';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Контрактные тесты: consumer-driven (Pact), producer verification — зачем при микросервисах?', 'Проблема: продюсер меняет API → консьюмер падает в проде, хотя у каждого свои тесты зелёные. Контракт — формализация ожиданий: consumer пишет тест с моком Pact, генерируется контракт (JSON: запросы/ожидаемые ответы), пушится в Pact Broker; пайплайн продюсера верифицирует контракты всех консьюмеров против своего кода — падение до деплоя. CDC vs schema-validation: Pact проверяет поведение (поля, статусы), OpenAPI-validation — форму; оба совместимы. can-i-deploy: Broker отвечает, безопасно ли релизить с текущим набором контрактов (интеграция с CI-гейтом). Spring Cloud Contract — producer-first: продюсер пишет контракты, генерирует тесты и stubs для консьюмеров (stubs в maven-репозитории). Границы: контракт ≠ e2e — он проверяет пару, не сценарий; тяжёлые бизнес-потоки всё равно требуют e2e на стенде. Практика: контракты версионировать с API, tag по веткам, брокер с матрицей совместимости; пограничные случаи (401, 500) тоже в контрактах.', 'Чем consumer-driven контракт отличается от проверки OpenAPI-схемы? Что отвечает can-i-deploy и как он блокирует небезопасный релиз? Почему контракты не заменяют e2e?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Тестирование асинхронщины: Awaitility, virtual time, тестирование Kafka-консьюмеров?', 'Асинхронные тесты нельзя ждать sleep (флаки: медленная машина = гарантированный flake, быстрая = всегда прох; sleep всегда медленный). Awaitility: await().atMost(5, SECONDS).pollInterval(100, MILLIS).untilAsserted(() -> assertThat(repo.count()).isEqualTo(3)) — активный поллинг с дедлайном; alias/condition для диагностики. Kafka-тесты: Testcontainers (реальный брокер в Docker): @Container KafkaContainer + producer в топик + awaitility на consumer-side эффект (БД-запись/флаг); embedded-брокер (побочные эффекты на файловую систему) почти умер. Топологический тест Kafka Streams: TopologyTestDriver — драйвер без брокера: pipeInput() в тему, readOutput — детерминированно, виртуальное время (advanceTime) для оконных операций. Coroutines: runTest (kotlinx-coroutines-test) — виртуальное время: delay пропускается мгновенно; advanceUntilIdle. CompletableFuture: complete вручную из теста, либо cf.join с таймаутом; правило: тест управляет временем, а не ждёт реального. Retry-логика: вносить интервалы в конфиг для теста (0ms) или фиктивные часы (Clock-абстракция).', 'Почему sleep в асинхронном тесте — гарантированный flake и что делает Awaitility? Чем TopologyTestDriver удобнее реального брокера для окон? Как runTest делает виртуальное время?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Circuit breaker и retry: Resilience4j, идемпотентность — как строить устойчивые интеграции?', 'Retry — для transient-ошибок (сеть, 503): лимит попыток + экспоненциальный backoff + jitter (без jitter синхронные ретраи создают шторм); НЕ ретраить: 4xx (ошибка запроса), timeout длинных операций (усугубление), non-idempotent POST (дубль платежа — только с идемпотентным ключом). Circuit breaker: закрыт (норма) → открыт при пороге ошибок (50% из 20 вызовов) → half-open после wait-duration пропускает пробные. Порогы из SLO зависимости. Bulkhead — изоляция пулов на зависимость (semaphore/thread pool): падение одной не съедает все воркеры; timeout на каждый вызов обязателен (комбинация: CB + timeout + bulkhead + retry). Resilience4j: декларативно @CircuitBreaker(name="payment", fallbackMethod=...) + конфигурация в yaml; fallback — деградация функциональности (кэш, дефолт, честная ошибка), не молчаливый null. Метрики: регистры Micrometer (состояния CB, длительности, отказы) — дашборд и алерты.组合 с очередями: не-критичные операции — outbox + Kafka (расслабление связности), синхронный путь только для обязательных.', 'Почему POST без идемпотентного ключа нельзя ретраить и как ключ решает? Что отличает открытый CB от half-open и кто решает вернуться? Зачем jitter в backoff и bulkhead отдельно от пула Tomcat?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'API Gateway и BFF: маршрутизация, агрегация, где логика не месте?', 'API Gateway (Spring Cloud Gateway, Envoy, Kong) — единая точка: маршрутизация по путям/хедерам, термин SSL, rate limiting (глобальный IP/token bucket), авторизация (JWT-проверка на границе), логирование/трейсинг-старт, versioning, канарейки. БФФ — слой под конкретный клиент (mobile BFF, web BFF): агрегация вызовов (экран профиля = user + orders + settings параллельно), трансформация под формат клиента (меньше трафика мобильному), клиентская логика (обрезка полей). Гравицы: шлюз без бизнес-логики (маршрут/политика — да, доменные решения — нет), BFF без переусложнения (один BFF на класс клиентов, не на экран — иначе дублирование); антипаттерн «BFF вызывает BFF». Композиция в BFF: параллельные CompletableFuture/VT-вызовы, частичная деградация (профиль без рекомендаций — 200, а не 500). GraphQL — альтернатива агрегации: клиенты запрашивают нужное, но сложность кэширования/N+1. Аутентификация: шлюз верифицирует JWT и прокидывает X-User-Id внутренним (mTLS между внутренними) — сервисы не парсят токен.', 'Какую логику допустимо держать в gateway и какая там запрещена? Чем BFF отличается от gateway и почему BFF не на каждый экран? Как GraphQL закрывает нишу агрегации?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'JUNIOR', 'STAR-метод и поведенческие вопросы: конфликт в команде, ошибка в проде — как отвечать?', 'STAR: Situation (контекст в 2 предложения), Task (что должно было произойти/твоя зона), Action (что сделал ТЫ — глаголы первого лица, не «мы» абстрактно), Result (цифры: время, деньги, метрики; вывод-урок). Подготовка: 5-7 сильных историй, каждая переиспользуется под несколько вопросов (конфликт,.failure, лидерство, дедлайн). Конфликт: не «он был неправ», а различие подходов → данные/спайк/арбитр-решение → результат и сохранённые отношения; показывай работу с людьми, не победу над ними. Ошибка в проде: признание без самоедства → минимизация ущерба (rollback, фикс) → постмортем blameless → системный фикс (тест, алерт, процесс) — ценят зрелость реакции, не безгрешность. Слабые стороны: реальная + работа над ней. Вопросы работодателю: команда, процесс релизов, онколл — твой тоже оценивают. Красные флаги ответов: обвинение всех, отсутствие цифр, истории без личного вклада, «не помню» на ключевые проекты.', 'Из каких четырёх частей состоит STAR и где теряют баллы? Как рассказывать об ошибке в проде, чтобы это выглядело зрелостью? Почему у каждого ответа должна быть цифра в Result?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Собеседование на senior: системный дизайн маленькой задачи — как структурировать ответ?', 'Структура ответа (45 мин): (1) уточнение требований — функциональные (что строим) и нефункциональные (RPS, латентность, консистентность, доступность) — НЕ пропускать, интервьюер проверяет умение спрашивать; (2) оценка объёма: RPS, хранение (бак-of-чисел: 1К RPS × 1KB × месяц = ~2.5ТБ), (3) API/контракты (endpoints, события), (4) высокоуровневая схема: клиент → LB → сервис → БД/кэш/очередь — назвать компромиссы вслух, (5) хранилище: выбор (SQL/NoSQL) с обоснованием под запросы, шардирование если нужно, (6) узкие места и масштабирование: кэш (что, где, инвалидация), очереди для пиков, реплики для чтения, (7) надёжность: что при падении каждой компоненты, ретраи/идемпотентность, (8) наблюдаемость: метрики/алерты. Говорить вслух ход мысли — интервьюер оценивает процесс, не финальную схему; рисовать по ходу; сверяться каждые 5 минут («пока сходится?»). Типовые задачи: URL-shortener (хеш, кодирование), лента (fan-out on write vs read), рейтинга (агрегаты), notification (очередь + дедуп). Ловушки: прыгнуть в детали хранилища до требований, придумать микро-сервисы на 100 RPS, игнорировать容量 чисел.', 'Почему уточнение требований — первый и самый важный шаг системного дизайна? Какие bak-of-numbers стоит проговаривать вслух? Какая самая частая ловушка начинающих на дизайн-интервью?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Собеседования двухсторонние: вопросы работодателю, red flags, оценка оффера?', 'Оценивай работодателя параллельно: команда (сколько, senior/junior соотношение, текучесть за год — спрашивать прямо), процесс (как выглядит релиз: кнопка или заявка на 3 дня; код-ревью норма или формальность; тесты обязательны?), онколл (график, компенсация, нагрузка алертов — «сколько страниц в месяц»), продукт (монетизация, рост, кто решает приоритеты), техника (стек, legacy-доля, техдолг признан или «всё ок»). Red flags: «у нас стартап, работаем по вечерам» без опциона, собеседование без вопросов тебе (не проверяют — возьмут кого угодно), «тестовое на неделю» бесплатно, зарплатная вилка скрыта до последнего, интервьюер ругает прежних сотрудников. Оффер: фикс + бонусы (реалистичность KPI), опцион (страйк, вестинг, ликвидность сценарии), ДМС (семья?), релокация/удалёнка юридически (контракт с кем, валютная зона), индексация, обучение. Переговоры: не принимать оффер на месте, вилка повышается при вежливом «у меня есть альтернативы»; справедливая цена — рынок (сравнить 2-3 оффера). Культура: как отвечают на «расскажи про последний инцидент» — blameless или поиск виноватых.', 'Какие вопросы про онколл и релизы выявляют реальный процесс, а не красивый? Что делать с тестовым заданием на неделю? Как оценивать опцион в оффере и его валютные риски?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Коллекции: ArrayList vs LinkedList — почему на собесах LinkedList почти всегда неверный ответ?', 'ArrayList — динамический массив: get O(1), add в конец амортизированно O(1) (рост в 1.5 раза), вставка/удаление в середине O(n) сдвигом; кэш-дружелюбен (непрерывная память — префетч), минимум аллокаций. LinkedList — двусвязный список: get O(n) (проход с конца/начала), вставка O(1) только если уже есть итератор на позицию, иначе поиск O(n); каждый элемент — объект-узел с двумя ссылками (память x3, промахи кэша, давление на GC). Практика: ArrayList быстрее LinkedList даже в «родных» для списка сценариях (очередь малой длины) из-за кэша; LinkedList выигрыш — только экзотика: millions of elements с частыми вставками в начало при невозможности ArrayDeque. Очереди/деки — ArrayDeque (массив-кольцо) вместо LinkedList всегда. CopyOnWriteArrayList — для read-heavy списков с редкими записями (слушатели). Управление размером: new ArrayList<>(expectedSize) — без лишних ресайзов; trimToSize. В Kotlin — MutableList по умолчанию ArrayList; ничего нового. Итог: «LinkedList для частых вставок» — теоретический ответ, практике противоречит — измерения (JMH) показывают ArrayList.', 'Почему ArrayList быстрее LinkedList при вставке в середину несмотря на O(n) у обоих? Что такое кэш-дружелюбность применительно к коллекциям? Когда ArrayDeque лучше LinkedList в роли очереди?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'HashMap внутренности Java 8+: бакеты, дерево, resize — что менялось и почему?', 'Массив бакетов (capacity — степень двойки), index = (n-1) & hash; hash — (h = key.hashCode()) ^ (h >>> 16) — старшие биты подмешиваются в младшие (иначе большие capacity игнорируют половину хеша). Коллизии: до Java 8 — связный список, с 8 — TREEIFY_THRESHOLD: список в бакете превращается в красно-чёрное дерево (поиск O(log n) вместо O(n) — защита от hash-DoS атаки множеством ключей с одним хешем); UNTREEIFY_THRESHOLD=6 — обратное превращение при уменьшения; дерево требует Comparable или tie-break-порядок хешей. Resize: при load factor 0.75 — массив удваивается, элементы переразбрасываются (в Java 8 оптимизация: бит хеша на позиции старого размера делит элементы на «низшие/высшие» без перехеширования — split списков/деревьев). put: бакет пуст — узел; есть — сравнение (hash==, equals) — замена; иначе хвост списка/дерева. null-ключ — отдельный бакет 0. Итерация — fail-fast (ConcurrentModificationException по modCount; не гарантирует детекцию в конкурентке). Порядок не гарантирован; LinkedHashMap — insertion/access order (LRU-кэш с removeEldestEntry). Правильный initial capacity = expected/0.75 + 1 — без ресайза.', 'Зачем hash-функция XOR-ит старшие 16 бит и что ломается без неё? Когда список в бакете становится деревом и от какой атаки это защищает? Как работает resize без перехеширования в Java 8+?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Generics: стирание, wildcardы PECS, reified в Kotlin — почему List<String> нельзя new T[]?', 'Стирание: дженерики — конструкция компилятора: в байткоде T → Object (или bound), мосты-методы для полиморфизма; List<String> и List<Integer> — один класс; instanceof по параметризованному типу запрещён; T нельзя инстанцировать (new T()), создать массив T[] (массивы реифицированы — ковариантность массивов с проверкой в рантайме — heap pollution). Wildcards: ? extends T — producer (читаем T), ? super T — consumer (пишем T) — PECS (Producer Extends, Consumer Super); без wildcard — инвариантность: List<Number> не принимает List<Integer> (иначе запись Double в список Integer). Bounds: <T extends Comparable<? super T>> — классика для max-функции. @SafeVarargs — подавление предупреждения о heap pollution при varargs-дженериках. Kotlin: reified T в inline-функциях — тип доступен в рантайме (inline копирует тело — стирание не мешает): filterIsInstance<T>(), T::class; star-projection <*> вместо ?. Erasure bridge: типизация сохранена в Signature-атрибуте — рефлексия читает дженерики (TypeToken/Guava, Spring ResolvableType — супертокены для партиального реифицирования).', 'Почему массивы ковариантны, а дженерики инвариантны и к чему это приводит? Что такое PECS и как применить к параметру метода? Как reified в Kotlin обходит стирание и почему только для inline?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Исключения: checked vs unchecked, производительность, sentinel/Result — дизайн обработки ошибок?', 'Checked — контракт «вызывающий обязан обработать» (IOException): хорош для предсказуемых恢复 сценариев, но на практике разлагается в throws Exception у сигнатур и boilerplate; Spring/Hibernate ушли в unchecked. RuntimeException — ошибки программирования/состояния (NPE, IllegalStateException); Error — фатальные JVM (не ловить). Стоимость исключения: заполнение stack trace ~микросекунды (десятки кадров) — в горячем пути цикла недопустимо, как control flow — антипаттерн; fillInStackTrace можно переопределить (выбрасывать кэшированное исключение без trace, JVM-тип OmitStackTraceInFastThrow уже оптимизирует частые). Ловить конкретно, не Throwable (проглотит OOM); finally/try-with-resources для очистки (AutoCloseable, suppression исключений). Дизайн: value-based — Optional для отсутствия (не ошибки), Result/Either (функциональный стиль, Kotlin: sealed Result, runCatching) для ожидаемых бизнес-ошибок без исключений; sentinel-объекты — реже. Пакетирование: @ResponseStatus/ProblemDetail на границе REST; глобальный @ControllerAdvice маппит доменные исключения в HTTP-коды; логировать один раз (на границе), не в каждом catch. Wrap: исключение-обёртка сохраняет cause — без cause диагностика мертва.', 'Почему checked-исключения проиграли войну в современных фреймворках? Что дорого в throw и когда исключение как control flow недопустимо? Как правильно мапить доменные ошибки в HTTP на границе?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'java.time: Instant, ZonedDateTime, Duration — как перестать бояться дат?', 'Основа — временная шкала UTC: Instant (мгновение, epoch-нано), машина-дружелюбен; LocalDateTime — «стенные часы» без зоны (дата+время как на календаре: расписание, дни рождения) — НЕ мгновение, нельзя сравнивать с Instant без зоны; ZonedDateTime = LocalDateTime + ZoneId (мгновение с человеко-читаемым представлением); OffsetDateTime — с фиксированным смещением (без правил DST — interchange-формат). ZoneId vs ZoneOffset: «Europe/Moscow» (правила истории/переходов) против +03:00 (снимок). Duration (нано-секунды, machine) vs Period (год-месяц-день, календарный: «месяц» — разный в днях). API: now(), of(), parse (ISO-8601), plus/minus (иммутабельно!), with (труncateTo, withDayOfMonth), between (Duration.between). Формат: DateTimeFormatter (не SimpleDateFormat — не thread-safe!), ofPattern, локали; сохранять в БД UTC (timestamptz в PG), показывать в зоне юзера. Грабли: DST-переход — LocalDateTime в зоне может не существовать (2:30 весной) или дважды (осенью) — ZonedDateTime.resolve смещает; chronofield week-based годы (Y vs y); System.currentTimeMillis (мс, эпоха) vs nanoTime (монотонная, НЕ привязана к стене — только интервалы!).', 'Чем LocalDateTime отличается от ZonedDateTime и почему первый нельзя сравнивать с Instant? Что происходит с несуществующим временем в DST-переходе? Почему nanoTime нельзя использовать как метку времени?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Autoboxing и примитивы: где Integer вместо int кусается производительностью и корректностью?', 'Boxing — int ↔ Integer: аллокация объекта (кроме IntegerCache -128..127, valueOf), в горячих циклах и коллекциях — давление на GC и промахи кэша; LongAdder вместо AtomicLong в метриках именно из-за этого. Специализированных дженерик-коллекций в JDK нет (стирание): IntStream/LongStream — потоковые специализации (без бокса), IntSummaryStatistics; сторонние: Eclipse Collections, fastutil, HPPC — Int2IntOpenHashMap без бокса, кратно быстрее и компактнее HashMap<Integer,Integer> в big-data сценариях. Корректность: == на Integer — сравнение ссылок (кэш ловит малые значения — баг проявляется на 128+ intermittently); == на int/long после unboxing — ок; NullPointerException при unboxing null-Integer (map.get → присвоение int). Nullable-примитивы невозможны — OptionalInt. Проекция: JPA-поля примитивные = 0 по умолчанию (не null!) — для «не задано» использовать обёртку; в DTO на границах — обёртки валидировать. Records с примитивами — без бокса. Varhandle/Unsafe — уже низкий уровень. Правило: внутри вычислений — примитивы, на границах — обёртки с валидацией, в коллекциях больших — специализированные библиотеки.', 'Почему == на Integer работает до 127 и падает после — что за кэш? Когда IntStream реально быстрее Stream<Integer>? Что лучше для миллиона int-ключей: HashMap<Integer,X> или сторонние библиотеки?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Immutable-структуры и defensive copy — как строить безопасные API?', 'Иммутабельность даёт: thread-safety без блокировок (safe publication через final), безопасный шаринг (кэш, memoization), предсказуемость (нет «изменилось под ногами»). Строим: класс final (или запечатан), поля private final, конструктор полный (или builder), ссылочные поля — глубокая defensive copy: List.copyOf(items) (иммутабельные копии Java 10+, null-hostile — упадёт на null-элементе), массив — clone() (массивы мутируемы всегда!),Collections.unmodifiableList — только view (обёртка над мутируемым исходником — изменение оригинала видно — НЕ иммутабельность); record — компилятор делает всё, кроме глубокой копии компонент-коллекций (компактный конструктор: this.items = List.copyOf(items)). Геттеры мутируемых полей — копию (или вернуть immutable-view). Builder: валидация в build(), финальные поля через конструктор билдера; blaze build() вызывает приватный конструктор. Строки — уже иммутабельны; Date/LocalDateTime — тоже. Mutable companion: если нужна производительность массовых изменений — wither-методы (withXxx возвращают копию), Persistent collections (PCollections, vavr) — структурное разделение, O(log n) копии. Бюджет: копирование на каждую операцию — O(n); для hot path — внутренняя мутируемость с публикацией только иммутабельного интерфейса.', 'Чем unmodifiableList отличается от List.copyOf и почему это критично? Что должен делать record с List-компонентой в компактном конструкторе? Когда wither-методы дешевле полной копии?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'JUNIOR', 'equals и hashCode при наследовании: instanceof vs getClass — что выбрать и почему?', 'instanceof (симметрия ок при отсутствии подклассов с состоянием, разрешает null-safe проверку, работает с прокси Hibernate — CGLIB-подкласс не ломает equals) vs getClass() (строгая симметрия, но прокси и любые подклассы перестают быть равны оригиналу — Hibernate-сущности в Set ведут себя странно). Рецепт для entity: бизнес-ключ (естественный идентификатор) или id-сравнение (осторожно: у несохранённой сущности id=null — равенство с null-id определить: новые сущности равны только по ссылке); никогда не использовать авто-id + генерацию в equals — генерация при первом equals ломает контракт. Для value-объектов: все поля, instanceof + cast (или pattern matching), @EqualsAndHashCode Lombok (callSuper осознанно), record — авто из компонент. Алгоритм: если o == this true; если o null / не тот тип false; каст; сравнение полей (примитивы ==, объекты Objects.equals, массивы Arrays.equals — глубокое). hashCode: Objects.hash(field1, field2) — varargs-аллокация массива в горячем коде — руками для перфа; вычисление один раз в immutable (кэш поля). Транзитивность ломается наследованием с новым полем: композиция вместо наследования — надёжный выход.', 'Почему Hibernate-прокси ломает equals на getClass() и как instanceof лечит? Что такое бизнес-ключ сущности и чем лучше id в equals? Как наследование ломает транзитивность и чем композиция лечит?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Annotation-процессинг и reflection: как работают Lombok и Spring без магии?', 'Аннотация — метаданные (@Retention SOURCE/CLASS/RUNTIME, @Target). Reflection — чтение в рантайме: Class.forName/getAnnotation, Method.invoke (setAccessible для private — с JDK 17+ модульные ограничения: --add-opens); медленный (проверки доступа, boxing аргументов) — кэшировать Method/Field объекты; MethodHandle/LambdaMetafactory быстрее повторных invoke. Annotation processor — инструмент компилятора (javac -processor): Lombok взламывает компилятор глубже (модифицирует AST — потому «магия» и конфликты с новыми JDK), MapStruct/RecordBuilder генерируют код обычным процессором. Spring: компонент-скан — reflection над classpath (ClassPathScanningCandidateComponentProvider, ASM-чтение байткода без загрузки), @Autowired через reflection-injection; с JDK 17 Spring использует метод-handle кэш; @Transactional — прокси + reflection на метаданные. Конфигурация аннотациями vs XML — читаемость, компиляция без проверки (строки в XML), refactoring-tooling. Ограничения: аннотация не наследуется от интерфейса-метода в reflection корректно (аннотации на классе — по иерархии классов). AOP+аннотации: @Cacheable — ключ по аргументам через SpEL/reflection. Производительность reflection-кода: скрытые аллокации, недоступность JIT-инлайнинга — в горячих путях генерировать код (processor) вместо reflection.', 'Чем annotation processor отличается от Lombok по механизму и почему Lombok хрупче? Почему Method.invoke медленный и что быстрее? Как Spring сканирует компоненты без загрузки всех классов?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Throwable-практикум: StackTraceElement, причины, suppressed — как читать чужой стектрейс?', 'Стектрейс — кадры от места throw вверх по вызовам; верхний кадр — точка выброса, ниже — путь; Caused by — цепочка причин (читать снизу вверх: корневая причина — последний Caused by); suppressed — try-with-resources собрал вторичные исключения при закрытии ресурсов. Читаем: найти первый «свой» пакет в кадрах (фреймворковые — контекст); grep по своим классам; line number точный для своих. NPE-детектив: «Cannot invoke X because <local> is null» (helpful NPE с Java 14 — указывает выражение); без — вычислять по строке. ClassCastException: «class A cannot be cast to class B (A and B are in different classloaders)» — конфликт лоадеров. OutOfMemoryError — тип определяет диагностику. Missing frames: JIT-инлайнинг скрывает методы (-XX:-Inline); lambdas — Synthetic/lambda$ (искать implMethod в строке); coroutine/virtual frames — jcmd Thread.dump. Логирование: e.getMessage() без стека — потеря контекста; log.error("msg", e) — полный; обёртки — обязательно cause в конструкторе. Wrapping: новые исключения без cause — стектрейс обрывается — читаемость убита.', 'Что означает Caused by и почему корневая причина в конце цепочки? Какие подсказки даёт helpful NPE с Java 14? Почему стектрейс может врать из-за JIT и как видеть lambdas?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Lock-free стек и очередь на CAS: как написать и где ошибиться?', 'Treiber stack: узел с next, top — AtomicReference; push: новый узел → next = top (чтение) → CAS(top, old, node) с повтором при неудаче; pop: CAS(top, old, top.next) — но ABA: узел снят и возвращён тем же адресом между чтением и CAS → удалённый узел в стеке → corruption; лечение — AtomicStampedReference (версия+значение) или индексная схема (слот-поколения). Очередь Michael-Scott: head/tail AtomicReference, dummy-узел; enqueue: CAS tail.next→node, затем CAS tail (помощь: если хвост отстал — продвинуть за владельцем); dequeue: CAS head→head.next (взять значение dummy). Память: освобождение узлов — hazard pointers / RCU-эпохи (Java: в библиотеках VarHandle + эквиваленты), иначе use-after-free при GC-языках не страшен, но poll может вернуть null при непустой очереди (гонка чтения value перед CAS head — считается допустимым в JDK-очередях,caller повторяет). Порядок памяти: VarHandle volatile/compareAndSet — acquire-release семантика; lazySet (putOrdered) в ненаблюдаемых путях снижает барьеры. Практика: ConcurrentLinkedQueue/Deque уже реализованы и протестированы (jcstress) — писать своё только для учебных целей или экзотических структур; баги lock-free не воспроизводятся юнит-тестами — только jcstress/long-soak.', 'Что такое ABA-проблема на примере Treiber стека и как штампы её решают? Зачем «помощь» в Michael-Scott очереди при отставшем tail? Почему юнит-тесты не ловят баги lock-free и что такое jcstress?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'CopyOnWrite и concurrent-коллекции: когда что вместо synchronized?', 'ConcurrentHashMap — сегментный (до 8) → CAS-бины (8+): чтение без блокировки (volatile), запись — CAS в пустой бин или synchronized на первый узел непустого; size — приблизительный (counterCells как LongAdder); составные операции: putIfAbsent/compute/merge — атомарные; iteration — слабо консистентно (не бросает CME, отражает состояние на момент создания). CopyOnWriteArrayList — каждая запись копирует массив: чтение без блокировок идеально, запись O(n) — только для read-mostly (слушатели, конфиги); итератор — снимок (не увидит изменений). ConcurrentLinkedQueue — lock-free Michael-Scott. BlockingQueue-семейство: ArrayBlockingQueue (один лок, bounded), LinkedBlockingQueue (два локa, optional bound), SynchronousQueue (передача рук-в-руки — newCachedThreadPool), DelayQueue (по времени), PriorityBlockingQueue; transfer() — ждёт потребителя. synchronized-коллекции (Collections.synchronizedX): глобальный лок, итерация требует ручной синхронизации — почти всегда хуже. Выбор: кэш/счётчики — CHM; конфигурация-списки — COW; продюсер-консьюмер — BlockingQueue по пропускной и границам. LongAdder — конкурентные счётчики (не CHM), чтобы не мешать hashmap.', 'Почему чтение из ConcurrentHashMap не требует блокировки и что такое слабо консистентная итерация? Когда CopyOnWriteArrayList — идеал, а когда катастрофа? Чем LinkedBlockingQueue с двумя локами быстрее ArrayBlockingQueue?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Фазы GC: minor/major, STW точки, safepoints — что происходит во время паузы?', 'Minor GC (young): root-scanning + копирование живых из eden+survivor в другой survivor/old — STW короткая (объекты-трупы не трогаются, копируются только живые — «чем больше мусора, тем быстрее minor»); copying collector метит живое переездом. Old-коллекция: G1 — смешанные: concurrent marking (pre-cleaning, remark STW, cleanup) + evacuation candidate-регионов STW; ZGC — почти всё concurrent: цветные указатели, load-barriers, STW только root-фазы (<1ms). Safepoint — точка, где все потоки остановлены в известном состоянии: JIT вставляет по polling-страницам; достигнув safepoint, JVM глобально остановлена (TTSP — time-to-safepoint: длинный счётный цикл без safepoint-поллинга (counted loop, int-инкремент до JIT-исправления) держит всех — «safepoint bias» и зависания); JNI-код не поллит — native-метод держит STW. Root set: стеки потоков, локали, JVM-внутренности (система классов, JNI-globals), card-table для old→young ссылок (write-barrier красит карточки при записи ссылки) — young-GC сканирует только dirty cards, а не весь old. Практика: -Xlog:gc* + safepoint-лог (-Xlog:safepoint): длинные TTSP =奸 suspicious циклы; JFR jdk.SafepointBegin/End.', 'Почему minor GC тем быстрее, чем больше мусора в молодом поколении? Что такое time-to-safepoint и как цикл без safepoint подвешивает весь GC? Зачем card-table и write-barrier при сборке молодого поколения?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'G1 детально: регионы, humongous, mixed GC — настройка под SLA?', 'Куча — регионы (1-32MB, степень двойки, ~2048 штук): eden/survivor/old ролятся динамически; collection set выбирает регионы с максимальным «garbage first». Пауза управляется -XX:MaxGCPauseMillis (мягкая цель — G1 меняет размер young и число old-регионов в mixed под неё). Concurrent marking cycle: IHOP (InitiatingHeapOccupancy, дефолт 45%) старт; remark/final-remark STW, cleanup. Mixed GC: young + часть old-регионов (наибольший мусор) за несколько пауз; G1HeapRegionSize для больших объектов: humongous = ≥50% региона — сразу в old-последовательность (фрагментация! большие массивы лечатся размером региона). Tuning: избегать humongous (регион под объект), MaxGCPauseMillis=SLA/4, G1MixedGCCountTarget растянуть old-евакуацию; параллельные фазы: ConcGCThreads, ParallelGCThreads; если to-space exhausted (evacuation failure) — live-set к потолку: Xmx больше или кэш резать. Пороговые признаки перехода на ZGC: паузы G1 растут с heap/compaction (humongous, fragmented) несмотря на тюнинг. Логи: -Xlog:gc*, смотреть Pause Young/Mixed/Round, to-space exhausted. Регион-подход плохо работает с heap < 6GB (слишком мелкие регионы) и > 32GB compressed-oops граница — нечувствительно, но помнить.', 'Как G1 добивается целевой паузы MaxGCPauseMillis и что происходит при её невыполнении? Что такое humongous-объект и как размер региона влияет на фрагментацию? Какие признаки говорят о переходе на ZGC?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kotlin: extension functions, top-level, scope functions — идиоматика без каши?', 'Extension fun String.slugged() = ... — статический вызов с receiver первым аргументом (не модифицирует класс; резолв по статическому типу, не виртуально — отличие от member: member всегда побеждает при конфликте сигнатур). Где: утилиты над чужими классами, DSL (собрать свой мини-язык на extensions+лямбдах с receiver). Scope functions: let (it, результат лямбды — null-check цепочки), run (this, результат — инициализация с вычислением), with (this, результат — групповые операции над объектом), apply (this, receiver — конфигурация объекта: Button().apply {...}), also (it, receiver — side-effect: логирование в цепочке). Выбор: на объекте — apply/also; преобразование — let/run; Kaше из этого — вложенные let с it внутри it — читаемость ноль: именованный val. Top-level функции — вместо static-утилит (fileName.kt с @JvmName для Java); properties аналогично. Идиоматика: val везде где можно, expression bodies, when вместо if-else цепей, elvis для дефолтов, data class + sealed для домена. Антипаттерны: extension ради extension (одноразовая логика в top-level теме), scope-цепочки длиннее двух, run для side-эффектов (тоже...).', 'Как компилируется extension function и почему она не виртуальная? В чём разница apply/also/let/run по receiver и результату? Когда extension лучше member-функции?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Kotlin: inline, noinline, crossinline, value class — производительность лямбд?', 'Лямбда в Kotlin — объект (Function1) — аллокация + вызов через invoke (без инлайнинга в caller): в горячем пути — GC-давление. inline fun: тело копируется в caller — лямбда-параметры инлайнятся в место вызова: ноль аллокаций, ноль invoke — потому stdlib-функции (map, forEach, let) inline: коллекционные цепочки бесплатны по объектам. Условия: лямбда не хранится (иначе — noinline — останется объектом) и не вызывается из другого контекста выполнения (crossinline — запрещает non-local return). Non-local return — только в inline-лямбдах (return из enclosing функции внутри forEach — валиден). reified — тип доступен в caller при инлайне (T::class). Inline больших функций раздувает байткод — только короткие и с лямбдами. value class (inline class, @JvmInline value class Meters(val v: Long)) — wrapper без аллокации в рантайме (в байткоде — просто Long, boxing только при укладке в generic/nullable): типобезопасные идентификаторы (UserId, Money) без цены обёртки; boxing происходите в Any/nullable/generic-контекстах (например List<Meters> — boxed!). Компромисс: злоупотребление inline ради «скорости» без лямбд — профит только аллокациям, код растёт; measured: JMH.', 'Почему inline-функция убирает аллокацию лямбды и когда это важно? Зачем crossinline и noinline существуют? Что такое value class и где она всё-таки боксится?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Sealed классы и enum в Kotlin: разница и совместное использование?', 'Enum — фиксированный набор экземпляров (синглтоны): одинаковые поля у всех, identity сравнение, values()/entries, реализация интерфейсов; память — один объект на вариант. Sealed class/interface — фиксированный набор ТИПОВ: каждый вариант — свой класс (data class, object, обычный класс) со своими полями; иерархия известна компилятору → exhaustive when без else. Выбор: без данных или одинаковые данные — enum; разные данные у вариантов — sealed (Status.Loading / Status.Error(val throwable) / Status.Done(val data)). Совместно: sealed иерархия с object-вариантами (без полей) внутри. When по sealed: без else — компилятор проверит полноту (добавили вариант — все when падают компиляцией: то ради чего всё затевалось); subject-ограничение: when (val s = state) { is Done -> s.data }. Java-совместимость: sealed — через @JvmName не особо; enum — из Java нативно. Полиморфизм vs when: sealed+when — процедурная обработка (легко добавлять операции), полиморфные методы — легко добавлять типы (выражение проблемы) — выбор под ось изменений. StateFlow<UiState> с sealed — стандарт Android/фронтенд-стейтов.', 'Чем sealed с object-вариантами отличается от enum по памяти и семантике? Что даёт exhaustive when без else на практике? Когда полиморфизм лучше sealed+when по оси изменений?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Kotlin coroutines: Flow vs Sequence vs RxJava — что выбрать под задачу?', 'Sequence — ленивая коллекция (однопоточная, синхронная): элементы обрабатываются по одному сквозь цепочку, suspend нельзя; для тяжёлых CPU-преобразований без IO. Flow — холодный асинхронный стрим: suspend-производитель, сбор collect — suspend; буферизация/backpressure: buffer (ёмкость), conflate (последнее-важно), collectLatest (отменять прошлую обработку); операторы map/filter/flatMapMerge; горячие — StateFlow (состояние, conflation всегда, conflated последнее значение — UI-стейт), SharedFlow (события, replay/extraBufferCapacity — подписки). Сравнение с RxJava: та же модель (Observable=Flow, BehaviorSubject=StateFlow), но корутины нативны структурированной конкурентности (отмена автоматически по scope), suspend вместо колбеков, нет отдельной библиотеки scheduler-ов. Выбор: последовательные вычисления — Sequence; асинхронные события/потоки данных — Flow; UI-состояние — StateFlow; legacy/сложные операторы — RxJava ещё уместна. Опасности: холодность Flow — collect запускает producer заново на каждого коллектора (shareIn для горячего); исключения — Flow отменяет весь стрим (catch оператор для upstream), retry; контекст — flowOn (upstream контекст) против launchIn.', 'Чем холодный Flow отличается от горячего StateFlow и что происходит при повторном collect? Когда Sequence достаточен, а когда нужен Flow? Как flowOn отличается от launchIn по области действия?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Spring Security: OAuth2 flows (authorization code + PKCE), JWT-структура — как устроен современный вход?', 'Authorization Code (с redirect): браузер → провайдер (Authorization endpoint) → логин/consent → редирект с code → бэкенд обменивает code+client_secret на tokens (Token endpoint); PKCE (обязателен для SPA/mobile): client генерирует verifier (random), challenge = SHA256(verifier), отправляет challenge при запросе кода, verifier при обмене — перехваченный code без verifier бесполезен (защита от intercepted-redirect). Tokens: access (короткоживущий, JWT или opaque), refresh (долгий, только для Token endpoint, вращение с reuse-detection — украденный refresh инвалидирует семейство), id_token (OIDC: JWT с iss/sub/aud/exp/iat + claims пользователя). JWT: header (alg) . payload (claims) . signature; проверка: подпись (RS256/ES256 — публичный ключ из JWKS endpoint, ротация ключей), exp/nbf, iss/aud, scopes; НЕ класть чувствительное — payload читаем без ключа (base64). Spring: spring-boot-starter-oauth2-resource-server (JWT-валидация из JWKS: spring.security.oauth2.resourceserver.jwt.jwk-set-uri), клиент — oauth2-client (авто-флоу, код в AuthorizationCodeGrantFilter). Выбор сессия vs JWT: распределённым API — JWT (stateless), монолиту — сессия (отзыв мгновенный, сервер-стор держит).', 'Зачем PKCE и как verifier/challenge защищает от перехвата code? Что обязательно проверять в JWT помимо подписи? Почему refresh token вращается и что такое reuse-detection?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Spring: @Scheduled, ShedLock, distributed scheduling — крон без дублей?', 'Шедулинг: @EnableScheduling + @Scheduled(cron="0 0 3 * * *", zone="Europe/Moscow") — cron из 6 полей (sec min hour day month weekday); fixedDelay (между концами), fixedRate (от стартов — наложение при зависании), initialDelay; один поток по умолчанию ( ScheduledTaskRegistrar) — долгая задача блокирует остальные: настроить TaskScheduler пул. В кластере каждая нода запустит задачу — дубль: ShedLock (аннотация @SchedulerLock + провайдер JDBC/Redis — lock-строка с lockAtMostFor/lockAtLeastFor; не queue, именно mutual exclusion), Quartz clustered (JDBC-таблицы, misfire-политики, persist), db-friendly: SELECT ... FOR UPDATE / advisory-lock PG (pg_try_advisory_lock — дёшево и транзакционно). Выбор: редкие регламентные — ShedLock; сложные зависимости/misfire — Quartz; mission-critical с retry и оркестрацией — отдельный scheduler (Airflow, Temporal). Практика: задачи идемпотентны (падение на середине → повтор), таймауты на внешние вызовы, наблюдаемость (лог старт/финиш/длительность, метрика), lockAtMostFor > худшего времени выполнения (зависание ноды — блок снимется по таймауту), зона времени явная (UTC в cron-выражении + zone= локаль).', 'Почему fixedRate опасен долгими задачами и чем fixedDelay безопаснее? Как ShedLock гарантирует единственное выполнение в кластере? Зачем идемпотентность задачи даже при блокировке?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Spring Boot: профили, конфигурация, внешние значения — иерархия и приоритеты?', 'Источники (по возрастанию приоритета): дефолты → application.yml в jar → application-{profile}.yml → вне-jar config/ → env-переменные → JVM-системные свойства → @TestPropertySource; spring.config.import подхватывает .env/vault/configserver. Профили: @Profile("prod") на бинах/конфигурациях, spring.profiles.active (env SPRING_PROFILES_ACTIVE), groups (spring.profiles.group.prod=prod-db,prod-kafka), профильные файлы переопределяют дефолты. Внешние значения: @Value("${key:default}") (SpEL, не типизирован) против @ConfigurationProperties(prefix="app") — типобезопасные группы (validation, IDE-подсказки через additional-spring-configuration-metadata.json, конструкторное связывание @ConstructorBinding по умолчанию для records). Relaxed binding: app.my-prop ↔ APP_MYPROP ↔ app.myProp. Секреты — НЕ в yml в git: env, vault (spring-cloud-vault), docker secrets (файл + spring.config.import), при старте видны в /actuator/env только с маскировкой (sanitize). Локально: .env через spring.config.import=optional:file:.env[.properties]. Проверка конфигурации при старте: fail-fast @Validated на properties. Actuator: /actuator/env (все источники с precedence), /actuator/configprops.', 'В каком порядке источники конфигурации переопределяют друг друга? Чем @ConfigurationProperties лучше @Value для группы настроек? Куда прятать секреты и что показывает /actuator/env?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'JPA: идентификация сущностей, генераторы ID, @Version против естественных ключей?', 'ID-стратегии: IDENTITY (autoincrement БД — Hibernate не батчит INSERT: jdbc-батч невозможен с identity!), SEQUENCE (выборка из sequence — батч работает, allocationSize=50 амортизирует round-trips), TABLE (универсальная, медленная — не использовать), UUID (генерация в приложении — GUID без обращения к БД, идеально распределённо; строка в индексах толще — специально UUIDv7 сортируемый). Естественный ключ (email, номер) — риски: бизнес может измениться (переименование, слияния), каскадные обновления; суррогатный + уникальный констрейнтом на естественном — надёжнее. equals/hashCode для entity: id-based с осторожностью (null-id новые сущности: равенство по ссылке до сохранения), бизнес-ключ лучший, постоянный hashCode (id.hashCode() из константы до сохранения — правило Хайбернейт-документации). @Version — оптимистичная блокировка (число) — обязательна для изменяемых сущностей с конкурентным доступом. equals по id + ленивая загрузка: прокси-класс — instanceof вместо getClass. Sequence-прыжки при рестарте (allocationSize кэш) — id с дырами — нормально. Составной ключ: @EmbeddedId (лучше @IdClass — переиспользование).', 'Почему IDENTITY ломает JDBC-батчинг INSERT-ов и что выбрать вместо? Чем UUIDv7 лучше UUIDv4 для индексов БД? Как правильно писать equals/hashCode для JPA-сущности?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Транзакции и propagation на практике: rollback-only, самовызов, читаемые транзакции?', 'Классика багов: (1) самовызов this.method() — внутренний @Transactional мимо прокси → без транзакции; лечится self-injection/разнос бинов/TransactionTemplate; (2) UnexpectedRollbackException: вложенный REQUIRED пометил rollback-only (исключение поймали во внешнем) — коммит внешнего падает «откат помечен» — понять, где граница транзакции и не глотать исключения внутри; (3) checked-исключение не откатывает по умолчанию (rollbackFor=Exception.class); (4) @Transactional на private — не работает (прокси). @Transactional(readOnly=true) — хинт: Hibernate flush NEVER (AUTO→MANUAL), драйвер PG read-only (запрет записи на уровне соединения), оптимизации реплики-роутинга; ставится на все читающие методы (менеджер транзакций всё равно открывает соединение — не «бесплатно», но дешевле). Timeout: @Transactional(timeout=5) — долгие транзакции держат коннекты и блокировки. Изоляция на уровне аннотации перекрывает дефолт БД. Тестирование: @Transactional в тесте откатывает по умолчанию (REQUIRES_NEW внутри — не откатится — ловушка). Программно: TransactionTemplate (callback, лучший контроль границ).', 'Почему самовызов не открывает транзакцию и три способа это починить? Что означает UnexpectedRollbackException и какое исключение её вызывает? Что реально даёт readOnly=true?' from categories where slug = 'spring-aop-transactions';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Собеседование на senior: как оценивают и что отличает от middle?', 'Оси оценки senior: (1) системное мышление — не «как сделать», а «стоит ли делать»: трейд-оффы вслух (проще vs гибче, сейчас vs на вырост), вопрос «а зачем эта фича?» — легитимный ответ; (2) владение доменом вглубь хотя бы одного слоя: не просто «использую Kafka», а понимаю партиции/ISR/rebalance и могу объяснить влияние на бизнес; (3) автономность: задача «улучшить X» без декомпозиции лидом — сам собираешь контекст, предлагаешь план, эскалируешь блокеры; (4) влияние на окружение: ревью, менторство, стандарты, автоматизация общих болей — мультипликатор, не только личная продуктивность; (5) инцидент-зрелость: спокойствие, приоритизация, постмортем без поиска виноватых. Отличие от middle в цифрах интервью: middle решает данную задачу, senior переформулирует её (находит проблему за вопросом), называет риски решения до вопросов; middle знает «как», senior знает «почему» и «когда не надо». Типовые ловушки-вопросы: «спроектируй X» — наблюдение за вопросами-уточнениями (requirements first!), «как бы улучшил наш сервис» (наблюдение: спрашивает ли метрики/пользователей перед «улучшениями»), поведенческие (conflict — зрелость). Анти-сигналы: максимализм технологий («везде k8s и реактив»), обесценивание («это говнокод» vs анализ trade-off), неспособность сказать «не знаю».', 'Какие три оси отличают senior-ответ от middle на дизайн-вопросе? Что значит «мультипликатор» и как это проверяют на собеседовании? Почему «не знаю» — сильный ответ, а не слабый?' from categories where slug = 'behavioral';
